// ============================================================
//  FORMAT HOUSE VIEWS  (n8n Code node — "Run Once for All Items")
//  Turns the targeted "RSS House Views" feed into one clean string
//  the agent renders the Institutional Whisper from.
//  Deterministic: this content is in the payload EVERY run.
// ============================================================

const items = $input.all();

// RSS Read emits one n8n item per article. Common fields: title, link,
// contentSnippet / content, pubDate, isoDate, creator/source.
const articles = [];
for (const it of items) {
  const j = it.json || {};
  const title = (j.title || '').trim();
  if (!title) continue;
  const link = j.link || j.guid || '';
  const snippet = (j.contentSnippet || j.content || j.summary || '')
    .replace(/<[^>]*>/g, ' ')      // strip any HTML
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 300);
  const when = (j.isoDate || j.pubDate || '').slice(0, 10);
  articles.push({ title, link, snippet, when });
}

// newest first, cap to keep the prompt lean
articles.sort((a, b) => (b.when || '').localeCompare(a.when || ''));
const top = articles.slice(0, 15);

const lines = [];
lines.push('BIG-HOUSE / STRATEGIST NEWS (targeted feed — last ~10 days). Use ONLY these articles for the Institutional Whisper. Every claim must trace to one of these headlines with its link. If an institution/target/sector/risk is NOT here, it does not appear — never fill in from memory.');
lines.push('');
if (!top.length) {
  lines.push('(No qualifying strategist/house-view articles in the feed this run — the Whisper should shrink or omit accordingly; do NOT invent house views.)');
} else {
  for (const a of top) {
    lines.push(`• [${a.when}] ${a.title}${a.snippet ? ' — ' + a.snippet : ''}${a.link ? ' (' + a.link + ')' : ''}`);
  }
}

const houseNewsContext = lines.join('\n');

return [{ json: { houseNewsContext, houseNewsCount: top.length } }];

const API_KEY = 'REDACTED_FMP_KEY';
const BASE = 'https://financialmodelingprep.com/stable/insider-trading/latest';
const PAGES = 20;

// Get portfolio tickers from the aggregated input array
const input = $input.all()[0].json;
const rawTickers = input.Ticker || [];
const tickerArray = rawTickers.flat().filter(function(t) { return typeof t === 'string' && t.length > 0; });
const myTickers = new Set(
  tickerArray.map(function(t) { return t.toUpperCase(); })
);

// Persistent storage — survives between runs
const staticData = $getWorkflowStaticData('global');
if (!staticData.insiderHistory) staticData.insiderHistory = {};

// Fetch pages until we hit a limit or run out
let allTrades = [];
for (let page = 0; page < PAGES; page++) {
  try {
    const url = `${BASE}?page=${page}&limit=100&apikey=${API_KEY}`;
    const response = await this.helpers.httpRequest({ method: 'GET', url });
    if (Array.isArray(response) && response.length > 0) {
      allTrades = allTrades.concat(response);
    } else {
      break;
    }
  } catch (e) {
    break;
  }
}

// Process trades
const trades = [];
const buysBySymbol = {};

for (const d of allTrades) {
  if (!d.symbol) continue;
  const symbol = d.symbol.toUpperCase();
  const type = (d.transactionType || '').toLowerCase();

  if (!type.includes('purchase') && !type.includes('sale')) continue;

  const shares = d.securitiesTransacted || 0;
  const price = d.price || 0;
  const value = shares * price;
  const label = type.includes('purchase') ? 'BUY' : 'SELL';

  const trade = {
    symbol, label, shares, price, value,
    name: d.reportingName || 'Unknown',
    role: d.typeOfOwner || '',
    date: d.transactionDate || d.filingDate || '',
    url: d.url || ''
  };

  trades.push(trade);

  // Save portfolio matches to persistent storage
  if (myTickers.has(symbol)) {
    const existing = staticData.insiderHistory[symbol];
    if (!existing || trade.date > existing.date) {
      staticData.insiderHistory[symbol] = trade;
    }
  }

  if (label === 'BUY') {
    if (!buysBySymbol[symbol]) buysBySymbol[symbol] = [];
    if (!buysBySymbol[symbol].find(t => t.name === trade.name)) {
      buysBySymbol[symbol].push(trade);
    }
  }
}

// ---- CONSOLIDATE TRADES ----
// Group by symbol + insider name + date to collapse tranches
// into a single summary line per insider per day
function consolidateTrades(tradeList) {
  const grouped = {};
  for (const t of tradeList) {
    const key = `${t.symbol}|${t.name}|${t.date}|${t.label}`;
    if (!grouped[key]) {
      grouped[key] = { ...t, totalValue: 0, totalShares: 0 };
    }
    grouped[key].totalValue += t.value;
    grouped[key].totalShares += t.shares;
  }
  return Object.values(grouped);
}

// Detect cluster buys (3+ distinct insiders buying same stock)
const clusterBuys = Object.entries(buysBySymbol)
  .filter(([sym, buyers]) => buyers.length >= 3)
  .map(([sym, buyers]) => ({ symbol: sym, count: buyers.length, buyers }));

// Build output lines using CONSOLIDATED trades
const lines = [];
const mentionedSymbols = new Set();

// 1) Portfolio matches from TODAY's scan — consolidated
const todayPortfolioTrades = trades.filter(t => myTickers.has(t.symbol));
const consolidatedPortfolio = consolidateTrades(todayPortfolioTrades);

// Sort by total value descending — most significant first
consolidatedPortfolio.sort((a, b) => b.totalValue - a.totalValue);

for (const t of consolidatedPortfolio) {
  mentionedSymbols.add(t.symbol);
  const avgPrice = t.totalShares > 0 ? (t.totalValue / t.totalShares).toFixed(2) : t.price.toFixed(2);
  lines.push(
    `INSIDER ${t.label}: ${t.symbol} — ${t.name} (${t.role}) ` +
    `${t.label === 'BUY' ? 'purchased' : 'sold'} ${t.totalShares.toLocaleString()} shares ` +
    `(avg $${avgPrice}, total $${Math.round(t.totalValue).toLocaleString()}) on ${t.date}. ` +
    `[PORTFOLIO HOLDING — TODAY] Filing: ${t.url}`
  );
}

// 2) Most recent historical portfolio matches (from past runs) — max 3
const historyLines = [];
for (const [symbol, t] of Object.entries(staticData.insiderHistory)) {
  if (mentionedSymbols.has(symbol)) continue;
  if (!myTickers.has(symbol)) continue;
  historyLines.push({
    date: t.date,
    text: `INSIDER ${t.label}: ${t.symbol} — ${t.name} (${t.role}) ` +
      `${t.label === 'BUY' ? 'purchased' : 'sold'} ${t.shares.toLocaleString()} shares ` +
      `at $${t.price.toFixed(2)} ($${Math.round(t.value).toLocaleString()}) on ${t.date}. ` +
      `[PORTFOLIO HOLDING — LAST KNOWN] Filing: ${t.url}`
  });
}
historyLines.sort((a, b) => b.date.localeCompare(a.date));
for (const h of historyLines.slice(0, 3)) {
  lines.push(h.text);
}

// 3) Cluster buys — outside portfolio only, max 2
for (const c of clusterBuys.slice(0, 2)) {
  if (lines.some(l => l.includes(c.symbol))) continue;
  const names = c.buyers.map(b => `${b.name} (${b.role})`).join(', ');
  lines.push(
    `CLUSTER BUY ALERT: ${c.symbol} — ${c.count} distinct insiders buying: ${names}. ` +
    `${myTickers.has(c.symbol) ? '[PORTFOLIO HOLDING]' : '[OUTSIDE ALERT]'}`
  );
}

// 4) Large outside trades — top 2 by value, $500K+ threshold
const outsideTrades = trades
  .filter(t => !myTickers.has(t.symbol) && t.value >= 500000)
  .sort((a, b) => b.value - a.value);

const consolidatedOutside = consolidateTrades(outsideTrades);
consolidatedOutside.sort((a, b) => b.totalValue - a.totalValue);

for (const t of consolidatedOutside.slice(0, 2)) {
  if (lines.some(l => l.includes(t.symbol))) continue;
  lines.push(
    `INSIDER ${t.label}: ${t.symbol} — ${t.name} (${t.role}) ` +
    `${t.label === 'BUY' ? 'purchased' : 'sold'} ${t.totalShares.toLocaleString()} shares ` +
    `($${Math.round(t.totalValue).toLocaleString()}) on ${t.date}. ` +
    `[OUTSIDE ALERT] Filing: ${t.url}`
  );
}

const summary = lines.length > 0
  ? lines.join('\n')
  : 'No insider purchases, sales, or cluster buying detected in portfolio names today.';

return [{
  json: {
    insiderSummary: summary,
    insiderCount: lines.length,
    totalScanned: allTrades.length,
    clusterBuys: clusterBuys,
    savedHistory: Object.keys(staticData.insiderHistory).length
  }
}];

// ============================================================================
//  MACRO / FIXED INCOME  ·  FRED NODE v2.0
//  n8n Code node · "Run Once for All Items"
//
//  WHAT CHANGED FROM v1
//  --------------------
//  1. HISTORY, NOT JUST LEVELS. Every series now pulls a multi-year window and
//     the node computes percentile rank, z-score, 1-week and 1-month changes,
//     and 52-week high/low. "The 10Y real yield is 2.34%" is a fact; "2.34%,
//     the 94th percentile of the last two years" is an argument. The model
//     could never compute this itself, and per the house rule, code owns
//     numbers.
//  2. NEW SERIES that close gaps visible in the shipped brief:
//     term premium (the brief INFERRED it), Brent (the brief issued a Brent
//     watch level while carrying only WTI), CCC spreads (aggregate HY hides
//     where stress actually sits), 5y5y forwards, the dollar, GDPNow, claims,
//     average hourly earnings, mortgage rates, financial conditions, 10y3m.
//  3. STALENESS IS EXPLICIT. Several series are weekly, monthly, or lag by
//     days (term premium runs ~1 week behind). Every value carries its own
//     date and an ageDays field, and the summary says "as of" rather than
//     implying today. A stale number presented as current is the fastest way
//     to lose a professional reader.
//  4. FAILURE IS LOUD IN DATA, SILENT IN PROSE. A dead series lands in
//     fredFailed with its reason and simply does not appear downstream.
//     Nothing renders "N/A" to an advisor.
//  5. EVERY v1 OUTPUT KEY IS PRESERVED, byte-for-byte in name and format, so
//     the system prompt, the user message and the formatting engine keep
//     working untouched. All new material arrives in NEW keys.
//
//  API KEY: move this to n8n credentials or an env var. A key hardcoded in a
//  node body travels into every export, screenshot and shared file.
// ============================================================================

// API KEY RESOLUTION, n8n Cloud safe.
// n8n Cloud blocks $env inside Code nodes and ACCESSING it THROWS, so it must
// be wrapped, never used bare. Order of preference:
//   1. an env var, when self-hosted
//   2. a row in the Read Config sheet with Field = fred_api_key
//   3. the literal below
// Option 2 is the one to use: the key lives in your config sheet, not in code
// that travels into every export and screenshot.
const API_KEY = (function () {
  try { if ($env && $env.FRED_API_KEY) return $env.FRED_API_KEY; } catch (e) { /* blocked on Cloud */ }
  try {
    const rows = $('Read Config').all() || [];
    for (const r of rows) {
      const f = r && r.json ? String(r.json.Field || '').toLowerCase().trim() : '';
      if (f === 'fred_api_key' && r.json.Value) return String(r.json.Value).trim();
    }
  } catch (e) { /* node not reachable from this branch */ }
  return '3005203425fa2a1c67e177db2e11e506';
})();
const BASE = 'https://api.stlouisfed.org/fred/series/observations';

// How far back to pull for percentile context. Two years is the right window
// for "is this level unusual for the current regime"; ten years would drag in
// ZIRP and make every rate look extreme.
const LOOKBACK_YEARS = 2;

// ---------------------------------------------------------------------------
// SERIES REGISTRY
// freq is documentation for the humans and drives the staleness tolerance.
// ctx:true means "compute percentile and z-score for this one" (only useful on
// series where a level is judgeable; a target range or a change series is not).
// ---------------------------------------------------------------------------
const SERIES = {
  // --- policy ---
  fedUpper:    { id: 'DFEDTARU',      freq: 'daily',   ctx: false, label: 'Fed Funds Upper' },
  fedLower:    { id: 'DFEDTARL',      freq: 'daily',   ctx: false, label: 'Fed Funds Lower' },

  // --- curve ---
  dgs2:        { id: 'DGS2',          freq: 'daily',   ctx: true,  label: '2Y Treasury' },
  dgs10:       { id: 'DGS10',         freq: 'daily',   ctx: true,  label: '10Y Treasury' },
  dgs30:       { id: 'DGS30',         freq: 'daily',   ctx: true,  label: '30Y Treasury' },
  spread2s10s: { id: 'T10Y2Y',        freq: 'daily',   ctx: true,  label: '2s10s Spread' },
  spread10y3m: { id: 'T10Y3M',        freq: 'daily',   ctx: true,  label: '10y3m Spread' },

  // --- inflation / real rates ---
  realYield10: { id: 'DFII10',        freq: 'daily',   ctx: true,  label: '10Y Real Yield (TIPS)' },
  breakeven10: { id: 'T10YIE',        freq: 'daily',   ctx: true,  label: '10Y Breakeven' },
  fwd5y5y:     { id: 'T5YIFR',        freq: 'daily',   ctx: true,  label: '5y5y Forward Inflation' },

  // --- term premium (Kim-Wright; LAGS ~1 WEEK, hence the date discipline) ---
  termPremium: { id: 'THREEFYTP10',   freq: 'daily',   ctx: true,  label: '10Y Term Premium' },

  // --- credit ---
  hySpread:    { id: 'BAMLH0A0HYM2',  freq: 'daily',   ctx: true,  label: 'High-Yield OAS' },
  igSpread:    { id: 'BAMLC0A0CM',    freq: 'daily',   ctx: true,  label: 'Investment-Grade OAS' },
  cccSpread:   { id: 'BAMLH0A3HYC',   freq: 'daily',   ctx: true,  label: 'CCC & Lower OAS' },
  bbSpread:    { id: 'BAMLH0A1HYBB',  freq: 'daily',   ctx: true,  label: 'BB OAS' },

  // --- volatility ---
  vix:         { id: 'VIXCLS',        freq: 'daily',   ctx: true,  label: 'VIX' },

  // --- financial conditions ---
  nfci:        { id: 'NFCI',          freq: 'weekly',  ctx: true,  label: 'Chicago Fed Financial Conditions' },

  // --- dollar & commodities ---
  dollar:      { id: 'DTWEXBGS',      freq: 'daily',   ctx: true,  label: 'Broad Dollar Index' },
  brent:       { id: 'DCOILBRENTEU',  freq: 'daily',   ctx: true,  label: 'Brent Crude' },
  wti:         { id: 'DCOILWTICO',    freq: 'daily',   ctx: true,  label: 'WTI Crude' },

  // --- growth & labor (these feed the standing Topics, which currently have
  //     no numbers behind them at all) ---
  gdpNow:      { id: 'GDPNOW',        freq: 'weekly',  ctx: false, resets: true, label: 'Atlanta Fed GDPNow' },
  claims:      { id: 'ICSA',          freq: 'weekly',  ctx: true,  label: 'Initial Jobless Claims' },
  avgHourly:   { id: 'CES0500000003', freq: 'monthly', ctx: false, label: 'Average Hourly Earnings' },
  unemployment:{ id: 'UNRATE',        freq: 'monthly', ctx: false, label: 'Unemployment Rate' },

  // --- housing ---
  mortgage30:  { id: 'MORTGAGE30US',  freq: 'weekly',  ctx: true,  label: '30Y Mortgage Rate' },
};

// ---------------------------------------------------------------------------
// FETCH
// observation_start keeps the payload small; we only need the lookback window.
// ---------------------------------------------------------------------------
const startDate = (() => {
  const d = new Date();
  d.setFullYear(d.getFullYear() - LOOKBACK_YEARS);
  return d.toISOString().slice(0, 10);
})();

const pull = async (key, cfg) => {
  const url = `${BASE}?series_id=${cfg.id}`
    + `&observation_start=${startDate}`
    + `&sort_order=desc&limit=100000&file_type=json&api_key=${API_KEY}`;
  try {
    const raw = await this.helpers.httpRequest({
      method: 'GET', url, json: true, timeout: 15000,
    });
    const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
    // FRED returns newest-first here. Keep only real prints.
    const obs = (data.observations || []).filter(o =>
      o && o.value !== '.' && o.value !== '' && o.value != null && !isNaN(parseFloat(o.value))
    );
    if (!obs.length) return [key, { ok: false, reason: 'no observations' }];
    return [key, {
      ok: true,
      value: parseFloat(obs[0].value),
      date: obs[0].date,
      prior: obs[1] ? parseFloat(obs[1].value) : null,
      priorDate: obs[1] ? obs[1].date : null,
      series: obs.map(o => ({ d: o.date, v: parseFloat(o.value) })), // newest-first
    }];
  } catch (e) {
    return [key, { ok: false, reason: String(e && e.message ? e.message : e).slice(0, 140) }];
  }
};

const R = Object.fromEntries(
  await Promise.all(Object.entries(SERIES).map(([k, cfg]) => pull(k, cfg)))
);

// ---------------------------------------------------------------------------
// MATH  ·  all of it deterministic, none of it trusted to the model
// ---------------------------------------------------------------------------
const DAY = 86400000;
const today = new Date();

function ageDays(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z');
  return Math.max(0, Math.round((today - d) / DAY));
}

// Value as of N calendar days ago: walk the newest-first series to the first
// observation on or before the target date. Handles weekends, holidays and
// weekly/monthly series without special-casing frequency.
function valueDaysAgo(series, n) {
  if (!Array.isArray(series) || !series.length) return null;
  const target = new Date(series[0].d + 'T00:00:00Z').getTime() - n * DAY;
  for (let i = 0; i < series.length; i++) {
    if (new Date(series[i].d + 'T00:00:00Z').getTime() <= target) return series[i].v;
  }
  return null;
}

function percentileRank(series, v) {
  if (!Array.isArray(series) || series.length < 30 || v == null) return null;
  let below = 0;
  for (let i = 0; i < series.length; i++) if (series[i].v < v) below++;
  return Math.round((below / series.length) * 100);
}

function zScore(series, v) {
  if (!Array.isArray(series) || series.length < 30 || v == null) return null;
  const n = series.length;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += series[i].v;
  const mean = sum / n;
  let sq = 0;
  for (let i = 0; i < n; i++) sq += Math.pow(series[i].v - mean, 2);
  const sd = Math.sqrt(sq / n);
  if (!sd) return null;
  return Math.round(((v - mean) / sd) * 100) / 100;
}

function hiLo(series) {
  if (!Array.isArray(series) || !series.length) return { hi: null, lo: null };
  let hi = -Infinity, lo = Infinity;
  for (let i = 0; i < series.length; i++) {
    if (series[i].v > hi) hi = series[i].v;
    if (series[i].v < lo) lo = series[i].v;
  }
  return { hi, lo };
}

// Ordinal suffix, because "53th percentile" in a brief for a CFA is the kind
// of small wrongness that makes a reader distrust the big numbers.
function ord(n) {
  if (n == null) return '';
  const a = n % 100, b = n % 10;
  const suf = (a >= 11 && a <= 13) ? 'th' : b === 1 ? 'st' : b === 2 ? 'nd' : b === 3 ? 'rd' : 'th';
  return n + suf;
}

function round(v, dp) {
  if (v == null || isNaN(v)) return null;
  const f = Math.pow(10, dp == null ? 2 : dp);
  return Math.round(v * f) / f;
}

// Build the enriched record for one series.
function enrich(key) {
  const r = R[key];
  const cfg = SERIES[key];
  if (!r || !r.ok) return null;
  const s = r.series;
  const v = r.value;
  const age = ageDays(r.date);
  // Tolerance by publication frequency. Beyond it, the value is real but it is
  // NOT today's reading, and anything downstream must say so.
  const tol = cfg.freq === 'daily' ? 5 : cfg.freq === 'weekly' ? 12 : 45;
  const out = {
    label: cfg.label,
    seriesId: cfg.id,
    freq: cfg.freq,
    value: round(v, 2),
    date: r.date,
    ageDays: age,
    stale: age > tol,
    // chgPrior is the change versus the PREVIOUS PRINT of this series, which
    // for a monthly series is month over month, not day over day. The old
    // chg1d name was a lie on every non-daily series; it is kept for
    // compatibility and chgBasis says what it actually measures.
    chgBasis: cfg.freq === 'daily' ? 'day over day'
            : cfg.freq === 'weekly' ? 'week over week' : 'month over month',
    chgPrior: r.prior == null ? null : round(v - r.prior, 2),
    chg1d: r.prior == null ? null : round(v - r.prior, 2),
    chg1w: (() => { const p = valueDaysAgo(s, 7);  return p == null ? null : round(v - p, 2); })(),
    chg1m: (() => { const p = valueDaysAgo(s, 30); return p == null ? null : round(v - p, 2); })(),
    chg3m: (() => { const p = valueDaysAgo(s, 91); return p == null ? null : round(v - p, 2); })(),
  };
  // Series that reset on a schedule (GDPNow rebases each quarter) produce
  // change figures that compare two different objects. Null them rather than
  // ship a number that means nothing.
  if (cfg.resets) { out.chgPrior = null; out.chg1d = null; out.chg1w = null; out.chg1m = null; out.chg3m = null; }
  if (cfg.ctx) {
    const { hi, lo } = hiLo(s);
    out.pctile = percentileRank(s, v);
    out.z = zScore(s, v);
    out.hi2y = round(hi, 2);
    out.lo2y = round(lo, 2);
    out.obsCount = s.length;
  }
  return out;
}

const M = {};
Object.keys(SERIES).forEach(k => { const e = enrich(k); if (e) M[k] = e; });

const failed = Object.entries(R)
  .filter(([, v]) => !v.ok)
  .map(([k, v]) => ({ key: k, seriesId: SERIES[k].id, reason: v.reason }));

// ---------------------------------------------------------------------------
// LEGACY OUTPUT  ·  identical names and formats to v1, so nothing downstream
// has to change. Missing series degrade to '0.00'/'N/A' exactly as before.
// ---------------------------------------------------------------------------
const g   = (k) => (M[k] ? M[k].value : 0) || 0;
const gc  = (k, f) => (M[k] && M[k][f] != null ? M[k][f] : 0) || 0;
const gd  = (k) => (M[k] ? M[k].date : 'N/A');
const f2  = (v) => Number(v).toFixed(2);
const sgn = (v) => (Number(v) >= 0 ? '+' : '') + Number(v).toFixed(2);

const fedLower = g('fedLower'), fedUpper = g('fedUpper');

// ---------------------------------------------------------------------------
// DERIVED READS  ·  the cross-series facts a person would have to work out by
// hand, computed once, here, where they can be verified.
// ---------------------------------------------------------------------------
const derived = {};

// Real yields vs breakevens: which leg is moving the nominal 10Y.
if (M.realYield10 && M.breakeven10) {
  const rc = M.realYield10.chg1d, bc = M.breakeven10.chg1d;
  // Two guards, both learned from a live run that produced a confident and
  // meaningless answer.
  // (a) SAME AS-OF DATE. TIPS and breakevens publish on different lags, so a
  //     naive comparison pits Thursday's move against Friday's.
  // (b) MATERIAL MOVE. When both legs are inside a basis point of flat, there
  //     is no driver to name, and saying "inflation expectations" because
  //     0.02 beat 0.00 is a fabricated conclusion dressed as analysis.
  const sameDay = M.realYield10.date === M.breakeven10.date;
  const material = rc != null && bc != null && Math.max(Math.abs(rc), Math.abs(bc)) >= 0.03;
  if (!sameDay) {
    derived.tenYearDriver = null;
    derived.tenYearDriverNote =
      `Not computed: the real yield prints as of ${M.realYield10.date} and the breakeven as of ${M.breakeven10.date}, so the daily changes are not comparable.`;
  } else if (!material) {
    derived.tenYearDriver = 'neither leg moved materially';
    derived.tenYearDriverDetail =
      `10Y real ${sgn(rc)} and breakeven ${sgn(bc)}, both inside a basis point of flat`;
  } else {
    derived.tenYearDriver =
      Math.abs(rc) >= Math.abs(bc) * 2 ? 'real yields'
      : Math.abs(bc) >= Math.abs(rc) * 2 ? 'inflation expectations'
      : 'both legs roughly evenly';
    derived.tenYearDriverDetail =
      `10Y real ${sgn(rc)} vs breakeven ${sgn(bc)} on the day`;
  }
}

// Credit quality spread: the tell aggregate HY hides.
if (M.cccSpread && M.bbSpread) {
  const gap = M.cccSpread.value - M.bbSpread.value;
  derived.cccBbGap = round(gap, 2);
  const gapPrior = (M.cccSpread.chg1m != null && M.bbSpread.chg1m != null)
    ? (M.cccSpread.value - M.cccSpread.chg1m) - (M.bbSpread.value - M.bbSpread.chg1m)
    : null;
  derived.cccBbGapChg1m = gapPrior == null ? null : round(gap - gapPrior, 2);
  derived.creditQualityRead = derived.cccBbGapChg1m == null ? null
    : (derived.cccBbGapChg1m > 0.15 ? 'low-quality credit underperforming, risk appetite narrowing'
      : derived.cccBbGapChg1m < -0.15 ? 'low-quality credit outperforming, risk appetite broadening'
      : 'quality spread stable');
}

// Curve regime, stated plainly.
if (M.spread2s10s) {
  const v = M.spread2s10s.value;
  derived.curveRegime = v < 0 ? 'inverted' : v < 0.25 ? 'flat' : v < 1 ? 'moderately positive' : 'steep';
  derived.curveDirection = M.spread2s10s.chg1m == null ? null
    : (M.spread2s10s.chg1m > 0.05 ? 'steepening' : M.spread2s10s.chg1m < -0.05 ? 'flattening' : 'stable');
}

// Term premium vs expectations: is the long end about supply or about the Fed.
if (M.termPremium && M.dgs10) {
  derived.termPremium = M.termPremium.value;
  derived.termPremiumAsOf = M.termPremium.date;
  derived.termPremiumStale = M.termPremium.ageDays > 5;
  derived.longEndDriver = M.termPremium.chg1m == null ? null
    : (M.termPremium.chg1m > 0.1 ? 'term premium rising: a supply and fiscal story'
      : M.termPremium.chg1m < -0.1 ? 'term premium falling: the long end is about policy expectations'
      : 'term premium broadly unchanged');
}

// Financial conditions in words. NFCI is centred on zero by construction.
if (M.nfci) {
  const v = M.nfci.value;
  const p = M.nfci.pctile;
  // "Looser than average" understates a reading sitting at the loosest level
  // in two years, which is exactly what a live run produced.
  derived.financialConditions =
    (p != null && p <= 5) ? 'at their loosest in two years'
    : (p != null && p >= 95) ? 'at their tightest in two years'
    : v > 0 ? 'tighter than average' : 'looser than average';
  derived.financialConditionsTrend = M.nfci.chg1m == null ? null
    : (M.nfci.chg1m > 0.05 ? 'tightening' : M.nfci.chg1m < -0.05 ? 'easing' : 'stable');
}

// Oil spread, so a Brent watch level is never issued off a WTI number again.
if (M.brent && M.wti) derived.brentWtiSpread = round(M.brent.value - M.wti.value, 2);

// ---------------------------------------------------------------------------
// SUMMARIES FOR THE PROMPT
// macroSummary keeps its v1 shape (the prompt reads it) and gains "as of"
// discipline. macroContext is the new block: levels judged against their own
// two-year history, which is the part the model cannot compute.
// ---------------------------------------------------------------------------
// Per-series display: claims arrive in persons and must render in thousands,
// index levels take no percent sign, and changes must use the same scale as
// the level they sit next to.
const DISPLAY = {
  claims:  { div: 1000, unit: 'K', dp: 0, chgDp: 1 },
  vix:     { div: 1, unit: '', dp: 2 },
  nfci:    { div: 1, unit: '', dp: 2 },
  dollar:  { div: 1, unit: '', dp: 2 },
  brent:   { div: 1, unit: '', dp: 2, pre: '$' },
  wti:     { div: 1, unit: '', dp: 2, pre: '$' },
};

function disp(key, v) {
  if (v == null) return 'n/a';
  const d = DISPLAY[key] || { div: 1, unit: '%', dp: 2 };
  const n = v / d.div;
  return (d.pre || '') + n.toFixed(d.dp) + (d.unit == null ? '%' : d.unit);
}

function dispChg(key, v) {
  if (v == null) return 'n/a';
  const d = DISPLAY[key] || { div: 1, unit: '%', dp: 2 };
  const n = v / d.div;
  const dp = d.chgDp == null ? d.dp : d.chgDp;   // claims move in hundreds; 0dp hides it
  return (n >= 0 ? '+' : '') + n.toFixed(dp) + (d.unit || '');
}

function line(key) {
  const m = M[key];
  if (!m) return null;
  const chg = m.chg1d == null ? '' : ` (chg ${dispChg(key, m.chg1d)},`;
  return `${m.label}: ${disp(key, m.value)}${chg ? chg : ' ('} as of ${m.date})`;
}

const macroSummary = [
  `Fed Funds Target Range: ${f2(fedLower)}%–${f2(fedUpper)}% (as of ${gd('fedUpper')})`,
  line('dgs10'), line('dgs2'), line('dgs30'),
  line('spread2s10s'), line('vix'),
  line('realYield10'), line('breakeven10'),
  line('hySpread'), line('igSpread'),
].filter(Boolean).join('\n');

function ctxLine(key) {
  const m = M[key];
  if (!m || m.pctile == null) return null;
  const stale = m.ageDays > (m.freq === 'daily' ? 5 : m.freq === 'weekly' ? 12 : 45)
    ? ' [STALE, do not call this today\u2019s level]' : '';
  return `${m.label}: ${disp(key, m.value)} · ${ord(m.pctile)} percentile of the last ${LOOKBACK_YEARS}y `
    + `(range ${disp(key, m.lo2y)} to ${disp(key, m.hi2y)}, z ${m.z == null ? 'n/a' : m.z}) · `
    + `1w ${dispChg(key, m.chg1w)}, 1m ${dispChg(key, m.chg1m)} · `
    + `as of ${m.date}${stale}`;
}

const macroContext = [
  'MACRO CONTEXT (levels judged against their own two-year history; percentile is where today sits in that window).',
  '',
  ctxLine('dgs2'), ctxLine('dgs10'), ctxLine('dgs30'), ctxLine('realYield10'),
  ctxLine('breakeven10'), ctxLine('fwd5y5y'), ctxLine('termPremium'),
  ctxLine('spread2s10s'), ctxLine('spread10y3m'),
  ctxLine('hySpread'), ctxLine('igSpread'), ctxLine('cccSpread'), ctxLine('vix'),
  ctxLine('nfci'), ctxLine('dollar'), ctxLine('brent'), ctxLine('mortgage30'),
  ctxLine('claims'),
].filter(Boolean).join('\n');

// A level at the edge of its own two-year range is the most quotable fact the
// macro block can produce, and it is invisible in a level alone. Surfaced here
// so the brief does not have to notice it.
const extremeRows = [];
Object.keys(M).forEach(k => {
  const m = M[k];
  if (!m || m.pctile == null) return;
  const hi = m.pctile >= 95, lo = m.pctile <= 5;
  if (!hi && !lo) return;
  extremeRows.push({
    key: k, m: m, hi: hi,
    // Rank by how far from the middle of its own distribution, so the most
    // unusual readings lead. A run that flags ten series has flagged nothing.
    rank: Math.abs(m.z == null ? (hi ? 2 : -2) : m.z),
    text: `${m.label} at ${disp(k, m.value)} is at a two-year ${hi ? 'HIGH' : 'LOW'} (${ord(m.pctile)} percentile, range ${disp(k, m.lo2y)} to ${disp(k, m.hi2y)}, as of ${m.date})`,
  });
});
extremeRows.sort((a, b) => b.rank - a.rank);
const extremes = extremeRows.slice(0, 5).map(x => x.text);
const extremesMore = extremeRows.length > 5 ? extremeRows.length - 5 : 0;

const derivedLines = [
  derived.tenYearDriver ? `The 10Y move is being driven by ${derived.tenYearDriver}${derived.tenYearDriverDetail ? ' (' + derived.tenYearDriverDetail + ')' : ''}.` : null,
  derived.longEndDriver ? `Long end: ${derived.longEndDriver}${derived.termPremiumStale ? ' (term premium data lags, as of ' + derived.termPremiumAsOf + ')' : ''}.` : null,
  derived.curveRegime ? `Curve is ${derived.curveRegime}${derived.curveDirection ? ' and ' + derived.curveDirection : ''}.` : null,
  derived.creditQualityRead ? `Credit: ${derived.creditQualityRead} (CCC minus BB gap ${derived.cccBbGap}%).` : null,
  derived.financialConditions ? `Financial conditions ${derived.financialConditions}${derived.financialConditionsTrend ? ' and ' + derived.financialConditionsTrend : ''}.` : null,
  derived.brentWtiSpread != null ? `Brent trades $${derived.brentWtiSpread.toFixed(2)} over WTI.` : null,
  derived.tenYearDriverNote || null,
].filter(Boolean);

if (extremes.length) {
  derivedLines.push('AT A TWO-YEAR EXTREME (most unusual first): ' + extremes.join('; ')
    + (extremesMore ? `; plus ${extremesMore} more series at an extreme.` : '.'));
}

// REGIME DIVERGENCE. The highest-value macro read available on a day when the
// risk-appetite gauges and the rate/credit gauges disagree: everything that
// measures fear can sit at a two-year low while the long end and junk credit
// sit at a two-year high. Neither number alone says it; only the pair does.
(function () {
  const calm = ['vix', 'hySpread', 'nfci', 'igSpread'].filter(k => M[k] && M[k].pctile != null && M[k].pctile <= 10);
  const stress = ['dgs30', 'dgs10', 'termPremium', 'cccSpread', 'realYield10'].filter(k => M[k] && M[k].pctile != null && M[k].pctile >= 90);
  if (calm.length >= 2 && stress.length >= 2) {
    derived.regimeDivergence = true;
    derivedLines.push(
      'REGIME DIVERGENCE: the risk-appetite gauges and the rate gauges are at OPPOSITE two-year extremes. '
      + calm.map(k => M[k].label + ' at the ' + ord(M[k].pctile) + ' percentile').join(', ')
      + ' say calm, while '
      + stress.map(k => M[k].label + ' at the ' + ord(M[k].pctile) + ' percentile').join(', ')
      + ' say the opposite. Equity volatility is priced for benign conditions while the long end and the low-quality end of credit are not.'
    );
  }
})();

const macroDerived = derivedLines.length
  ? 'DERIVED MACRO READS (computed from the series above; render verbatim, never recompute):\n' + derivedLines.map(l => '- ' + l).join('\n')
  : '';

function ageTag(m) {
  if (!m) return '';
  return m.stale ? ` [${m.ageDays} DAYS OLD, this is NOT a current reading]` : '';
}

const growthLines = [
  // GDPNow resets each quarter, so a change versus the prior print compares
  // two different quarters and means nothing. Level and date only.
  M.gdpNow      ? `Atlanta Fed GDPNow: ${f2(M.gdpNow.value)}% for the quarter (as of ${M.gdpNow.date})${ageTag(M.gdpNow)}` : null,
  M.claims      ? `Initial Jobless Claims: ${Math.round(M.claims.value / 1000)}K (chg ${dispChg('claims', M.claims.chg1w)} w/w, as of ${M.claims.date})${ageTag(M.claims)}` : null,
  M.unemployment? `Unemployment Rate: ${f2(M.unemployment.value)}% (as of ${M.unemployment.date})${ageTag(M.unemployment)}` : null,
  M.avgHourly   ? `Average Hourly Earnings: $${f2(M.avgHourly.value)} (as of ${M.avgHourly.date})${ageTag(M.avgHourly)}` : null,
  M.mortgage30  ? `30Y Mortgage Rate: ${f2(M.mortgage30.value)}% (chg ${sgn(M.mortgage30.chg1w)} 1w, as of ${M.mortgage30.date})${ageTag(M.mortgage30)}` : null,
  M.dollar      ? `Broad Dollar Index: ${f2(M.dollar.value)} (chg ${sgn(M.dollar.chg1m)} 1m, as of ${M.dollar.date})${ageTag(M.dollar)}` : null,
].filter(Boolean);

const growthSummary = growthLines.length
  ? 'GROWTH, LABOR, HOUSING AND DOLLAR (these support the standing Topics; every figure is dated, several are weekly or monthly and are NOT today\u2019s reading):\n'
    + growthLines.map(l => '- ' + l).join('\n')
  : '';

// ---------------------------------------------------------------------------
// RETURN
// ---------------------------------------------------------------------------
return [{
  json: {
    // ===== v1 KEYS, UNCHANGED IN NAME AND FORMAT =====
    fedFundsRate:  `${f2(fedLower)}%–${f2(fedUpper)}%`,
    yield2Y:       f2(g('dgs2')),
    yield10Y:      f2(g('dgs10')),
    yield30Y:      f2(g('dgs30')),
    spread2s10s:   f2(g('spread2s10s')),
    vix:           f2(g('vix')),
    rateDate:      gd('dgs10'),
    fedUpper:      String(g('fedUpper')),
    fedLower:      String(g('fedLower')),

    yield2YChg:     f2(gc('dgs2', 'chg1d')),
    yield10YChg:    f2(gc('dgs10', 'chg1d')),
    yield30YChg:    f2(gc('dgs30', 'chg1d')),
    spread2s10sChg: f2(gc('spread2s10s', 'chg1d')),

    realYield10:    f2(g('realYield10')),
    realYield10Chg: f2(gc('realYield10', 'chg1d')),
    breakeven10:    f2(g('breakeven10')),
    breakeven10Chg: f2(gc('breakeven10', 'chg1d')),
    hySpread:       f2(g('hySpread')),
    hySpreadChg:    f2(gc('hySpread', 'chg1d')),
    hySpreadDate:   gd('hySpread'),
    igSpread:       f2(g('igSpread')),
    igSpreadChg:    f2(gc('igSpread', 'chg1d')),
    igSpreadDate:   gd('igSpread'),

    fredFailed:     failed.map(f => f.key),
    macroSummary:   macroSummary,

    // ===== NEW: the depth layer =====
    // Full enriched record per series: value, date, ageDays, 1d/1w/1m/3m
    // changes, percentile, z-score, 2y high and low.
    macro:          M,
    macroContext:   macroContext,   // percentile-aware prose block for the prompt
    macroDerived:   macroDerived,   // cross-series reads, pre-computed
    growthSummary:  growthSummary,  // feeds the standing Topics
    macroDerivedObj: derived,       // same reads, structured
    fredFailedDetail: failed,       // key, seriesId and reason, for debugging
    fredLookbackYears: LOOKBACK_YEARS,
    fredAsOf:       new Date().toISOString(),

    // Convenience singles the brief kept reaching for and did not have.
    termPremium:      M.termPremium ? f2(M.termPremium.value) : null,
    termPremiumDate:  M.termPremium ? M.termPremium.date : null,
    fwd5y5y:          M.fwd5y5y     ? f2(M.fwd5y5y.value) : null,
    cccSpread:        M.cccSpread   ? f2(M.cccSpread.value) : null,
    bbSpread:         M.bbSpread    ? f2(M.bbSpread.value) : null,
    spread10y3m:      M.spread10y3m ? f2(M.spread10y3m.value) : null,
    brent:            M.brent       ? f2(M.brent.value) : null,
    brentDate:        M.brent       ? M.brent.date : null,
    wtiFred:          M.wti         ? f2(M.wti.value) : null,
    dollarIndex:      M.dollar      ? f2(M.dollar.value) : null,
    nfci:             M.nfci        ? String(M.nfci.value) : null,
    gdpNow:           M.gdpNow      ? f2(M.gdpNow.value) : null,
    claimsK:          M.claims      ? String(Math.round(M.claims.value / 1000)) : null,
    mortgage30:       M.mortgage30  ? f2(M.mortgage30.value) : null,
    unemployment:     M.unemployment? f2(M.unemployment.value) : null,
  }
}];

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  PRICE DATA v2 , quotes for holdings + WATCHLIST + indices + commodities,    ║
// ║  book move COMBINED and PER MANDATE.                                         ║
// ║                                                                              ║
// ║  v2 CHANGES vs v1:                                                           ║
// ║   1. UNWRAPS the O-aggregate single-element array wrapping on mandates,      ║
// ║      holdingsByMandate, holdingsWeightsByMandate, personalization, Ticker,   ║
// ║      Watchlist. This node is the first Code node after O aggregate, so       ║
// ║      everything downstream (look-through, rollup, agent, engine) now         ║
// ║      receives clean objects. mandates.isMulti works from here on.            ║
// ║   2. WATCHLIST QUOTES: full quote treatment for every watchlist name,        ║
// ║      emitted as `watchlistQuotes` + appended to quoteSummary under a         ║
// ║      clearly separated "WATCHLIST (tracked, not held)" section. Watchlist    ║
// ║      quotes NEVER enter book-move math or holdings blocks.                   ║
// ║   3. NASDAQ: ^IXIC (Composite) fetched for the headline tile alongside QQQ.  ║
// ║      indexCloses gains ixic / ixicPct / ixicChg.                             ║
// ║   4. BOOK MOVE PER MANDATE: bookMoveByMandate, one entry per book, each      ║
// ║      computed ONLY from that book's holdings with weights normalized within  ║
// ║      the book. Combined move unchanged (weights are already mandate-scaled). ║
// ║      bookMoveSummary now carries the per-book lines when isMulti.            ║
// ║   5. Failed-quote report (quotesFailed) so a bad symbol is visible, not      ║
// ║      silent.                                                                 ║
// ║  Single portfolio: byMandate fields render null and output matches v1.       ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

const items = $input.all();
const results = [];
const FMP_KEY = 'REDACTED_FMP_KEY';

// ^GSPC = S&P 500 · ^IXIC = Nasdaq Composite · QQQ = Nasdaq-100 ETF
// GCUSD = Gold spot · CLUSD = WTI Crude spot · ^VIX = CBOE Volatility Index
const REFERENCE_SYMBOLS = ['^GSPC', '^IXIC', 'QQQ', 'GCUSD', 'CLUSD', '^VIX'];

// ── unwrap the O-aggregate single-element array wrapping ──────────────────────
function unwrap(v){ return (Array.isArray(v) && v.length === 1 && !Array.isArray(v[0]) && typeof v[0] === 'object') ? v[0] : v; }
function unwrapDeepArray(v){
  // [["A","B"]] -> ["A","B"]  ·  ["A","B"] -> ["A","B"]  ·  anything else -> []
  if (!Array.isArray(v)) return [];
  if (v.length === 1 && Array.isArray(v[0])) return v[0].slice();
  return v.slice();
}
function unwrapString(v){
  if (Array.isArray(v)) return unwrapString(v[0]);
  return (v === null || v === undefined) ? '' : String(v);
}

function fmpSymbol(t){
  if (!t) return t;
  return String(t).replace(/\//g, '-').replace(/\./g, '-');
}

for (const item of items) {

  // ── 0) normalize the payload ONCE, pass the clean version through ───────────
  const src = item.json || {};
  const mandates = unwrap(src.mandates) || null;
  const holdingsByMandate = unwrap(src.holdingsByMandate) || null;
  const holdingsWeightsByMandate = unwrap(src.holdingsWeightsByMandate) || null;
  const personalization = unwrapString(src.personalization);
  const tickers = unwrapDeepArray(src.Ticker);
  const watchlist = unwrapDeepArray(src.Watchlist)
    .map(function(t){ return String(t).toUpperCase().trim(); })
    .filter(function(t){ return /^[A-Z][A-Z.\-]{0,5}$/.test(t); });

  const heldSet = {};
  tickers.forEach(function(t){ heldSet[String(t).toUpperCase().trim()] = 1; });
  // a watchlist name that is ALSO held is a holding; drop it from the watchlist fetch
  const watchOnly = watchlist.filter(function(t){ return !heldSet[t]; });

  // ── 1) one fetch loop: holdings + watchlist + references ────────────────────
  const fetchPlan = [];
  tickers.forEach(function(t){ fetchPlan.push({ sym: t, kind: 'hold' }); });
  watchOnly.forEach(function(t){ fetchPlan.push({ sym: t, kind: 'watch' }); });
  REFERENCE_SYMBOLS.forEach(function(t){ fetchPlan.push({ sym: t, kind: 'ref' }); });

  const quotes = [];           // holdings only, same shape as v1
  const watchlistQuotes = [];  // NEW , watchlist names, same normalized shape
  const referenceQuotes = {};
  const quotesFailed = [];

  for (let i = 0; i < fetchPlan.length; i++) {
    const plan = fetchPlan[i];
    const url = 'https://financialmodelingprep.com/stable/quote?symbol='
      + encodeURIComponent(fmpSymbol(plan.sym)) + '&apikey=' + FMP_KEY;
    try {
      const resp = await this.helpers.httpRequest({ url: url, method: 'GET', json: true });
      if (Array.isArray(resp) && resp.length > 0) {
        const q = resp[0];
        let computedPct = q.changesPercentage;
        if (computedPct == null && q.change != null && q.previousClose) {
          computedPct = (q.change / q.previousClose) * 100;
        }
        const normalized = {
          symbol: plan.sym,
          name: q.name || '',
          price: q.price,
          change: q.change,
          changePct: computedPct,
          volume: q.volume,
          marketCap: q.marketCap,
          pe: q.pe,
          yearHigh: q.yearHigh,
          yearLow: q.yearLow,
          dayHigh: q.dayHigh,
          dayLow: q.dayLow,
          open: q.open,
          previousClose: q.previousClose,
          priceAvg50: q.priceAvg50,
          priceAvg200: q.priceAvg200,
          exchange: q.exchange
        };
        if (plan.kind === 'ref') referenceQuotes[plan.sym] = normalized;
        else if (plan.kind === 'watch') watchlistQuotes.push(normalized);
        else quotes.push(normalized);
      } else {
        quotesFailed.push(plan.sym);
      }
    } catch (err) {
      quotesFailed.push(plan.sym);
      console.error('Quote fetch failed for ' + plan.sym + ': ' + err.message);
    }
  }

  // ── 2) COMBINED weights (already mandate-scaled by Aggregate Sheets) ────────
  let amtByTicker = {};
  let hw = unwrap(src.holdingsWeights);
  if (hw && typeof hw === 'object' && !Array.isArray(hw)) {
    for (const k in hw) amtByTicker[String(k).toUpperCase().trim()] = hw[k];
  }
  if (Object.keys(amtByTicker).length === 0) {
    // legacy fallback: read the sheet directly
    try {
      const holdingRows = $('Read Holdings1').all();
      for (let hr = 0; hr < holdingRows.length; hr++) {
        const hj = holdingRows[hr].json;
        if (hj && hj.Ticker != null) {
          const wv = (hj.Weight !== undefined ? hj.Weight : hj.Amount);
          amtByTicker[String(hj.Ticker).toUpperCase().trim()] = wv;
        }
      }
    } catch (e) { /* leave empty, equal-weight fallback below */ }
  }

  function parseWeight(v){
    if (v == null || v === '') return null;
    const n = parseFloat(String(v).replace('%','').replace(/,/g,'').trim());
    return (isFinite(n) && n >= 0) ? n : null;
  }

  const weightByTicker = {};
  tickers.forEach(function(t){
    weightByTicker[String(t).toUpperCase().trim()] = parseWeight(amtByTicker[String(t).toUpperCase().trim()]);
  });
  let totalWeight = 0;
  for (const tk in weightByTicker) { if (weightByTicker[tk] != null) totalWeight += weightByTicker[tk]; }
  const hasWeights = totalWeight > 0;

  quotes.forEach(function(q){
    const raw = weightByTicker[String(q.symbol).toUpperCase().trim()];
    q.weightPct = (hasWeights && raw != null) ? (raw / totalWeight * 100) : null;
  });
  // watchlist quotes NEVER carry a weight
  watchlistQuotes.forEach(function(q){ q.weightPct = null; });

  // ── 3) book move helper: one mandate at a time, weights normalized WITHIN ───
  function bookMoveFrom(symbolList, weightsMap){
    const wByT = {};
    let wSum = 0, anyWeight = false;
    symbolList.forEach(function(t){
      const k = String(t).toUpperCase().trim();
      const w = parseWeight(weightsMap ? weightsMap[k] : null);
      wByT[k] = w;
      if (w != null){ wSum += w; anyWeight = true; }
    });
    const inBook = {};
    symbolList.forEach(function(t){ inBook[String(t).toUpperCase().trim()] = 1; });
    const moved = quotes.filter(function(q){
      return q.changePct != null && inBook[String(q.symbol).toUpperCase().trim()];
    });
    if (!moved.length) return { move: null, basis: 'Equal-Wt', n: 0 };
    if (anyWeight && wSum > 0){
      let cs = 0, cw = 0;
      moved.forEach(function(q){
        const w = wByT[String(q.symbol).toUpperCase().trim()];
        if (w != null){ cw += w; cs += w * q.changePct; }
      });
      if (cw > 0) return { move: cs / cw, basis: 'Weighted', n: moved.length };
    }
    let sum = 0;
    moved.forEach(function(q){ sum += q.changePct; });
    return { move: sum / moved.length, basis: 'Equal-Wt', n: moved.length };
  }

  // combined move: the union with the combined (mandate-scaled) weights
  const combined = bookMoveFrom(tickers, amtByTicker);
  const bookMove = combined.move;
  const bookMoveBasis = combined.basis;

  // ── 4) PER-MANDATE book moves ───────────────────────────────────────────────
  let bookMoveByMandate = null;
  const isMulti = !!(mandates && mandates.isMulti === true
    && Array.isArray(mandates.portfolios) && mandates.portfolios.length > 1
    && holdingsByMandate && holdingsWeightsByMandate);
  if (isMulti){
    bookMoveByMandate = [];
    mandates.portfolios.forEach(function(p){
      const syms = holdingsByMandate[p.name] || [];
      const wmap = holdingsWeightsByMandate[p.name] || {};
      const r = bookMoveFrom(syms, wmap);
      bookMoveByMandate.push({
        name: p.name,
        mandateWeightPct: p.weight,
        move: (r.move == null) ? null : Math.round(r.move * 10000) / 10000,
        basis: r.basis,
        holdingsQuoted: r.n
      });
    });
  }

  // ── 5) summary strings ──────────────────────────────────────────────────────
  let bookMoveSummary = (bookMove != null)
    ? 'BOOK MOVE: ' + (bookMove > 0 ? '+' : '') + bookMove.toFixed(2) + '% (' + bookMoveBasis + ')'
    : 'BOOK MOVE: N/A';
  if (isMulti && bookMoveByMandate){
    const parts = bookMoveByMandate.map(function(b){
      return b.name + ' (' + b.mandateWeightPct + '%): '
        + (b.move == null ? 'N/A' : (b.move > 0 ? '+' : '') + b.move.toFixed(2) + '%');
    });
    bookMoveSummary += ' | By mandate: ' + parts.join(' · ');
  }

  const indexCloses = {
    spx:  referenceQuotes['^GSPC'] ? referenceQuotes['^GSPC'].price : null,
    spxPct: referenceQuotes['^GSPC'] ? referenceQuotes['^GSPC'].changePct : null,
    ixic: referenceQuotes['^IXIC'] ? referenceQuotes['^IXIC'].price : null,
    ixicPct: referenceQuotes['^IXIC'] ? referenceQuotes['^IXIC'].changePct : null,
    ixicChg: referenceQuotes['^IXIC'] ? referenceQuotes['^IXIC'].change : null,
    qqq:  referenceQuotes['QQQ'] ? referenceQuotes['QQQ'].price : null,
    qqqPct: referenceQuotes['QQQ'] ? referenceQuotes['QQQ'].changePct : null,
    vix:  referenceQuotes['^VIX'] ? referenceQuotes['^VIX'].price : null,
    vixPct: referenceQuotes['^VIX'] ? referenceQuotes['^VIX'].changePct : null,
    vixChg: referenceQuotes['^VIX'] ? referenceQuotes['^VIX'].change : null
  };

  const commodities = {
    gold: referenceQuotes['GCUSD'] ? referenceQuotes['GCUSD'].price : null,
    goldPct: referenceQuotes['GCUSD'] ? referenceQuotes['GCUSD'].changePct : null,
    goldDayHigh: referenceQuotes['GCUSD'] ? referenceQuotes['GCUSD'].dayHigh : null,
    goldDayLow: referenceQuotes['GCUSD'] ? referenceQuotes['GCUSD'].dayLow : null,
    crude: referenceQuotes['CLUSD'] ? referenceQuotes['CLUSD'].price : null,
    crudePct: referenceQuotes['CLUSD'] ? referenceQuotes['CLUSD'].changePct : null,
    crudeDayHigh: referenceQuotes['CLUSD'] ? referenceQuotes['CLUSD'].dayHigh : null,
    crudeDayLow: referenceQuotes['CLUSD'] ? referenceQuotes['CLUSD'].dayLow : null
  };

  let commoditySummary = '';
  if (commodities.gold != null){
    commoditySummary += 'Gold (spot): $' + commodities.gold.toFixed(2);
    if (commodities.goldPct != null) commoditySummary += ' (' + (commodities.goldPct > 0 ? '+' : '') + commodities.goldPct.toFixed(2) + '% today)';
  }
  if (commodities.crude != null){
    if (commoditySummary) commoditySummary += '\n';
    commoditySummary += 'WTI Crude (spot): $' + commodities.crude.toFixed(2);
    if (commodities.crudePct != null) commoditySummary += ' (' + (commodities.crudePct > 0 ? '+' : '') + commodities.crudePct.toFixed(2) + '% today)';
  }
  if (indexCloses.vix != null){
    if (commoditySummary) commoditySummary += '\n';
    commoditySummary += 'VIX (CBOE Volatility Index): ' + indexCloses.vix.toFixed(2);
    if (indexCloses.vixPct != null) commoditySummary += ' (' + (indexCloses.vixPct > 0 ? '+' : '') + indexCloses.vixPct.toFixed(2) + '% today)';
  }
  if (indexCloses.ixic != null){
    if (commoditySummary) commoditySummary += '\n';
    commoditySummary += 'Nasdaq Composite: ' + indexCloses.ixic.toLocaleString('en-US', { maximumFractionDigits: 0 });
    if (indexCloses.ixicPct != null) commoditySummary += ' (' + (indexCloses.ixicPct > 0 ? '+' : '') + indexCloses.ixicPct.toFixed(2) + '% today)';
  }

  function quoteLine(q){
    return q.symbol
      + (q.weightPct != null ? ' (' + q.weightPct.toFixed(1) + '% of book)' : '')
      + ': $' + (q.price != null ? q.price : 'N/A')
      + ' | ' + (q.changePct != null ? (q.changePct > 0 ? '+' : '') + q.changePct.toFixed(2) + '%' : 'N/A')
      + ' | PE: ' + (q.pe != null ? q.pe : 'N/A')
      + ' | 52w: $' + (q.yearLow != null ? q.yearLow : 'N/A') + '-$' + (q.yearHigh != null ? q.yearHigh : 'N/A')
      + ' | 50dMA: $' + (q.priceAvg50 != null ? q.priceAvg50 : 'N/A')
      + ' | Vol: ' + (q.volume != null ? q.volume.toLocaleString() : 'N/A');
  }
  let quoteSummary = quotes.map(quoteLine).join('\n');
  if (watchlistQuotes.length){
    quoteSummary += '\n\nWATCHLIST (tracked, not held , NEVER blended into book statistics):\n'
      + watchlistQuotes.map(quoteLine).join('\n');
  }

  const output = Object.assign({}, src, {
    // normalized payload replaces the array-wrapped originals
    Ticker: tickers,
    Watchlist: watchlist,
    mandates: mandates,
    holdingsByMandate: holdingsByMandate,
    holdingsWeightsByMandate: holdingsWeightsByMandate,
    holdingsWeights: (hw && typeof hw === 'object' && !Array.isArray(hw)) ? hw : (src.holdingsWeights || null),
    personalization: personalization,

    quotes: quotes,
    watchlistQuotes: watchlistQuotes,
    quotesFailed: quotesFailed,
    quoteSummary: quoteSummary,
    indexCloses: indexCloses,
    commodities: commodities,
    commoditySummary: commoditySummary,
    bookMove: bookMove,
    bookMoveBasis: bookMoveBasis,
    bookMoveSummary: bookMoveSummary,
    bookMoveByMandate: bookMoveByMandate
  });

  results.push({ json: output });
}

return results;

const API_KEY = 'REDACTED_FMP_KEY';
const input = $input.first().json;
const tickers = (input.Ticker?.[0] || []).filter(Boolean);

// Split into chunks of 15 symbols per request
const CHUNK_SIZE = 15;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const results = [];

for (let i = 0; i < tickers.length; i += CHUNK_SIZE) {
  const chunk = tickers.slice(i, i + CHUNK_SIZE);

  // Process chunk in parallel
  const promises = chunk.map(ticker =>
    this.helpers.httpRequest({
      method: 'GET',
      url: `https://financialmodelingprep.com/stable/technical-indicators/rsi?symbol=${ticker}&periodLength=14&timeframe=1day&apikey=${API_KEY}`,
      timeout: 8000,
    })
    .then(response => {
      if (Array.isArray(response) && response.length > 0) {
        return { ticker, ...response[0] };
      }
      return { ticker, error: 'NO_DATA' };
    })
    .catch(e => ({ ticker, error: e.message }))
  );

  const chunkResults = await Promise.all(promises);
  results.push(...chunkResults);

  // Pause between chunks to respect rate limits
  if (i + CHUNK_SIZE < tickers.length) {
    await sleep(1500);
  }
}

return [{ json: { rsiData: results } }];

const input = $input.first().json;
const rsiData = input.rsiData || [];

const valid = rsiData
  .filter(r => r.rsi != null && !isNaN(parseFloat(r.rsi)))
  .map(r => ({ ticker: r.ticker, rsi: parseFloat(parseFloat(r.rsi).toFixed(1)), date: r.date?.slice(0, 10) }))
  .sort((a, b) => a.rsi - b.rsi);

if (valid.length === 0) {
  return [{ json: { rsiSummary: 'RSI data unavailable.' } }];
}

const avg      = parseFloat((valid.reduce((s, r) => s + r.rsi, 0) / valid.length).toFixed(1));
const lowest3  = valid.slice(0, 3);
const highest3 = valid.slice(-3).reverse();

const tag = rsi => rsi >= 70 ? ' OVERBOUGHT' : rsi <= 30 ? ' OVERSOLD' : '';

// Full lookup string for agent — every ticker and its RSI
const fullRsiLookup = valid
  .slice()
  .sort((a, b) => a.ticker.localeCompare(b.ticker))
  .map(r => `${r.ticker}: ${r.rsi}${tag(r.rsi)}`)
  .join(', ');

// Compact display summary for the bar
const rsiBarSummary = [
  `Portfolio Avg RSI: ${avg}`,
  `Highest: ${highest3.map(r => `${r.ticker} (${r.rsi}${tag(r.rsi)})`).join(', ')}`,
  `Lowest: ${lowest3.map(r => `${r.ticker} (${r.rsi}${tag(r.rsi)})`).join(', ')}`
].join(' | ');

// Full agent context
const rsiSummary = `RSI-14 scan across ${valid.length} positions. ${rsiBarSummary}. Full portfolio: ${fullRsiLookup}.`;

return [{
  json: {
    rsiData:         valid,          // full sorted array — agent can reference any ticker
    rsiSummary:      rsiSummary,     // full context string for agent prompt
    rsiBarSummary:   rsiBarSummary,  // compact string for the visual bar
    portfolioAvgRsi: avg,            // number for the bar
    highest3:        highest3,       // top 3 for bar display
    lowest3:         lowest3,        // bottom 3 for bar display
  }
}];

const rawData = $input.all();

// FMP returns newest first — reverse to oldest first for EMA calculation
const prices = rawData
  .slice()
  .reverse()
  .map(function(item) { return item.json.close; });

// EMA helper
function calcEMA(data, period) {
  var k = 2 / (period + 1);
  var ema = data[0];
  for (var i = 1; i < data.length; i++) {
    ema = data[i] * k + ema * (1 - k);
  }
  return ema;
}

if (prices.length < 35) {
  return [{ json: { sro: null, sroRegime: 'INSUFFICIENT DATA', sroColor: '#aaa' } }];
}

var ema10 = calcEMA(prices, 10);
var ema35 = calcEMA(prices, 35);
var sro   = ((ema10 - ema35) / ema35) * 100;
var sroRounded = Math.round(sro * 100) / 100;

var sroRegime, sroColor;
if (sro >= 5) {
  sroRegime = 'EXTREMELY OB';  sroColor = '#7f1d1d';
} else if (sro >= 3) {
  sroRegime = 'OVERBOUGHT';    sroColor = '#b91c1c';
} else if (sro >= 1) {
  sroRegime = 'MILDLY OB';     sroColor = '#92400e';
} else if (sro > -1) {
  sroRegime = 'NEUTRAL';       sroColor = '#166534';
} else if (sro > -3) {
  sroRegime = 'MILDLY OS';     sroColor = '#92400e';
} else if (sro > -5) {
  sroRegime = 'OVERSOLD';      sroColor = '#1d4ed8';
} else {
  sroRegime = 'EXTREMELY OS';  sroColor = '#1e3a8a';
}

return [{
  json: {
    sro:       sroRounded,
    sroRegime: sroRegime,
    sroColor:  sroColor
  }
}];

// ============================================================
// EARNINGS CALENDAR — 7-DAY FORWARD LOOKER
// For the MO/MC Briefing Agent
// ============================================================
// Input: O aggregate node output
// Output: Clean earnings data feeding into Merge3
// ============================================================

const FMP_API_KEY = 'REDACTED_FMP_KEY';

// ---- 1. Pull AllTickers — unwrap O aggregate's nested array ----
const upstream = $input.first().json;
const rawTickers = upstream.AllTickers || [];
const uniqueTickers = Array.isArray(rawTickers[0]) ? rawTickers[0] : rawTickers;

if (uniqueTickers.length === 0) {
  return [{
    json: {
      earningsThisWeek: [],
      earningsCount: 0,
      message: 'No tickers found.',
      sectionLabel: 'EARNINGS THIS WEEK',
      summaryLine: 'No portfolio or watchlist earnings in the next 7 days.'
    }
  }];
}

// ---- 2. Build 7-day window in PT ----
const utcNow = new Date();
const ptNow  = new Date(utcNow.toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
const ptIn7  = new Date(ptNow.getTime() + 7 * 24 * 60 * 60 * 1000);

const fmtDate = (d) => d.toISOString().slice(0, 10);
const fromDate = fmtDate(ptNow);
const toDate   = fmtDate(ptIn7);

// ---- 3. Call FMP stable earnings calendar ----
const url = `https://financialmodelingprep.com/stable/earnings-calendar?from=${fromDate}&to=${toDate}&apikey=${FMP_API_KEY}`;

let calendarData;
try {
  calendarData = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    json: true
  });
} catch (err) {
  return [{
    json: {
      earningsThisWeek: [],
      earningsCount: 0,
      error: 'FMP_FETCH_FAILED',
      message: err.message,
      sectionLabel: 'EARNINGS THIS WEEK',
      summaryLine: 'Unable to fetch earnings calendar.'
    }
  }];
}

if (!Array.isArray(calendarData)) {
  return [{
    json: {
      earningsThisWeek: [],
      earningsCount: 0,
      error: 'UNEXPECTED_RESPONSE',
      sectionLabel: 'EARNINGS THIS WEEK',
      summaryLine: 'Unable to fetch earnings calendar.'
    }
  }];
}

// ---- 4. Filter to portfolio/watchlist tickers only ----
// Normalize uniqueTickers to uppercase for comparison
const normalizedTickers = uniqueTickers.map(t => t.toUpperCase().trim());

const matches = [];

for (const event of calendarData) {
  const sym = (event.symbol || '').toUpperCase().trim();
  if (!normalizedTickers.includes(sym)) continue;

  // Timing label
  const rawTime = (event.time || '').toLowerCase().trim();
  let timing = 'TBD';
  if (rawTime === 'amc' || rawTime.includes('after')) timing = 'amc';
  else if (rawTime === 'bmo' || rawTime.includes('before')) timing = 'bmo';

  // Day of week
  const dateObj = new Date(event.date + 'T12:00:00');
  const dayOfWeek = dateObj.toLocaleDateString('en-US', { weekday: 'long' });
  const shortDay  = dateObj.toLocaleDateString('en-US', { weekday: 'short' });

  // Days from now
  const daysAway = Math.ceil((dateObj - ptNow) / (1000 * 60 * 60 * 24));

  // Fiscal quarter
  let fiscalQuarter = null;
  let fiscalYear = null;
  if (event.fiscalDateEnding) {
    const fde = new Date(event.fiscalDateEnding);
    fiscalQuarter = Math.ceil((fde.getMonth() + 1) / 3);
    fiscalYear = fde.getFullYear();
  }

  const quarterLabel = fiscalQuarter && fiscalYear
    ? `Q${fiscalQuarter} ${fiscalYear}`
    : '';

  matches.push({
    symbol:          sym,
    date:            event.date,
    dayOfWeek:       dayOfWeek,
    shortDay:        shortDay,
    daysAway:        daysAway,
    timing:          timing,
    quarterLabel:    quarterLabel,
    epsEstimate:     event.epsEstimated     ?? null,
    revenueEstimate: event.revenueEstimated ?? null,
    weekAheadTag:    `${sym} ${quarterLabel} ${timing}`.trim(),
    tableRow:        `${sym} | ${dayOfWeek} | ${timing.toUpperCase()} | EPS Est: ${event.epsEstimated ?? 'N/A'}`
  });
}

// Sort by date
matches.sort((a, b) => new Date(a.date) - new Date(b.date));

// ---- 5. Build summary line for the agent ----
let summaryLine = '';
if (matches.length === 0) {
  summaryLine = 'No portfolio or watchlist earnings in the next 7 days.';
} else {
  const labels = matches.map(m => `${m.symbol} (${m.shortDay} ${m.timing})`).join(', ');
  summaryLine = `Earnings this week: ${labels}`;
}

// ---- 6. Return single clean output ----
return [{
  json: {
    sectionLabel:     'EARNINGS THIS WEEK',
    earningsCount:    matches.length,
    earningsThisWeek: matches,
    summaryLine:      summaryLine,
    windowFrom:       fromDate,
    windowTo:         toDate,
    tickersScanned:   normalizedTickers.length
  }
}];

// ============================================================
// POLITICIAN TRADES — SENATE + HOUSE (COMPOSITE SCORED)
// For the MO/MC Briefing Agent
// ============================================================

const FMP_API_KEY = 'REDACTED_FMP_KEY';

// ---- 1. Pull AllTickers — unwrap O aggregate nested array ----
const upstream = $input.first().json;
const rawTickers = upstream.AllTickers || [];
const portfolioTickers = Array.isArray(rawTickers[0]) ? rawTickers[0] : rawTickers;
const normalizedTickers = portfolioTickers.map(t => t.toUpperCase().trim());

// ---- 2. Fetch Senate + House latest trades ----
const senateUrl = `https://financialmodelingprep.com/stable/senate-latest?page=0&limit=100&apikey=${FMP_API_KEY}`;
const houseUrl  = `https://financialmodelingprep.com/stable/house-latest?page=0&limit=100&apikey=${FMP_API_KEY}`;

let senateData = [];
let houseData  = [];

try {
  senateData = await this.helpers.httpRequest({ method: 'GET', url: senateUrl, json: true });
  if (!Array.isArray(senateData)) senateData = [];
} catch (err) { senateData = []; }

try {
  houseData = await this.helpers.httpRequest({ method: 'GET', url: houseUrl, json: true });
  if (!Array.isArray(houseData)) houseData = [];
} catch (err) { houseData = []; }

const allTrades = [
  ...senateData.map(t => ({ ...t, chamber: 'Senate' })),
  ...houseData.map(t =>  ({ ...t, chamber: 'House'  }))
];

if (allTrades.length === 0) {
  return [{
    json: {
      polSectionLabel:   'POLITICIAN TRADES',
      polSummaryLine:    'No politician trade data available.',
      topTrade:          null,
      topPortfolioTrade: null,
      topCluster:        null,
      topByDollar:       null,
      polClusterBuys:    [],
      portfolioTrades:   [],
      totalTrades:       0,
      portfolioMatches:  0,
      clusterCount:      0,
      senateTotal:       0,
      houseTotal:        0
    }
  }];
}

// ---- 3. Amount parsing ----
function parseAmountUpper(amountStr) {
  if (!amountStr) return 0;
  const nums = amountStr.replace(/,/g, '').match(/\d+/g);
  if (!nums || nums.length === 0) return 0;
  return parseInt(nums[nums.length - 1], 10);
}

function amountTier(upper) {
  if (upper >= 1000000) return 'LARGE (>$1M)';
  if (upper >= 250000)  return 'SIGNIFICANT ($250K+)';
  if (upper >= 50000)   return 'NOTABLE ($50K+)';
  if (upper >= 15000)   return 'MODERATE ($15K+)';
  return 'SMALL (<$15K)';
}

// ---- 4. Scoring functions ----
const now = new Date();

function recencyScore(disclosureDate, transactionDate) {
  const d = new Date(disclosureDate || transactionDate || 0);
  const daysAgo = (now - d) / (1000 * 60 * 60 * 24);
  if (daysAgo <= 1)  return 100;
  if (daysAgo <= 3)  return 90;
  if (daysAgo <= 7)  return 75;
  if (daysAgo <= 14) return 55;
  if (daysAgo <= 30) return 35;
  return 10;
}

function sizeScore(amountUpper) {
  if (amountUpper >= 1000000) return 100;
  if (amountUpper >= 500000)  return 85;
  if (amountUpper >= 250000)  return 70;
  if (amountUpper >= 100000)  return 55;
  if (amountUpper >= 50000)   return 40;
  if (amountUpper >= 15000)   return 25;
  return 10;
}

// ---- 5. Filter and score trades ----
const stockTrades = allTrades.filter(t => {
  const type = (t.assetType || '').toLowerCase();
  return type.includes('stock') || type === '' || !t.assetType;
});

const taggedTrades = stockTrades.map(trade => {
  const sym         = (trade.symbol || '').toUpperCase().trim();
  const inPortfolio = normalizedTickers.includes(sym);
  const firstName   = trade.firstName || '';
  const lastName    = trade.lastName  || '';
  const name        = `${firstName} ${lastName}`.trim() || 'Unknown';
  const rawType     = (trade.type || '').toLowerCase();
  const isBuy       = rawType.includes('purchase') || rawType.includes('buy');
  const tradeType   = isBuy ? 'BUY' : 'SELL';
  const amount      = trade.amount || 'undisclosed';
  const amountUpper = parseAmountUpper(trade.amount);
  const txDate      = trade.transactionDate  || 'N/A';
  const discDate    = trade.disclosureDate   || 'N/A';
  const link        = trade.link || '';
  const asset       = trade.assetDescription || sym;
  const chamber     = trade.chamber;
  const tier        = amountTier(amountUpper);

  const rScore = recencyScore(trade.disclosureDate, trade.transactionDate);
  const sScore = sizeScore(amountUpper);
  const compositeScore = Math.round((rScore * 0.5) + (sScore * 0.5));
  const portfolioBonus = inPortfolio ? 15 : 0;
  const finalScore = Math.min(compositeScore + portfolioBonus, 100);

  const summary = `[${chamber}] ${name} ${tradeType} ${sym} (${asset}) — ${amount} (${tier}) — tx: ${txDate} | disclosed: ${discDate}${inPortfolio ? ' ★ PORTFOLIO' : ''}`;

  const alphaRead = inPortfolio
    ? (isBuy
        ? `${chamber} member ${name} accumulating ${sym} (${tier}) — reinforces the position. Politicians with committee access often trade ahead of policy clarity.`
        : `${chamber} member ${name} reducing ${sym} (${tier}) — soft caution signal on a current holding. Watch for policy headwinds.`)
    : (isBuy
        ? `${chamber} member ${name} buying ${sym} (${tier}) — not in the portfolio. ${amountUpper >= 50000 ? 'Significant size — worth evaluating.' : 'Monitor for follow-through.'}`
        : `${chamber} member ${name} selling ${sym} (${tier}) — not a current holding. ${amountUpper >= 50000 ? 'Notable size — broader market context.' : 'Routine disclosure.'}`);

  return {
    symbol:          sym,
    name:            name,
    chamber:         chamber,
    tradeType:       tradeType,
    isBuy:           isBuy,
    amount:          amount,
    amountUpper:     amountUpper,
    amountTier:      tier,
    transactionDate: txDate,
    disclosureDate:  discDate,
    link:            link,
    inPortfolio:     inPortfolio,
    compositeScore:  finalScore,
    summary:         summary,
    alphaRead:       alphaRead
  };
});

// ---- 6. Cluster buys ----
const buysByTicker = {};
taggedTrades.forEach(trade => {
  if (!trade.isBuy) return;
  if (!buysByTicker[trade.symbol]) buysByTicker[trade.symbol] = [];
  const normalizedName = trade.name.replace(/[^a-zA-Z\s]/g, '').toLowerCase().trim();
  const alreadyCounted = buysByTicker[trade.symbol]
    .some(t => t.normalizedName === normalizedName);
  if (!alreadyCounted) {
    buysByTicker[trade.symbol].push({ ...trade, normalizedName });
  }
});

const polClusterBuys = Object.entries(buysByTicker)
  .filter(([sym, trades]) => trades.length >= 2)
  .map(([sym, trades]) => {
    const totalUpper = trades.reduce((sum, t) => sum + t.amountUpper, 0);
    const inPortfolio = normalizedTickers.includes(sym);
    return {
      symbol:       sym,
      inPortfolio:  inPortfolio,
      buyCount:     trades.length,
      amountTier:   amountTier(totalUpper),
      politicians:  trades.map(t => `${t.name} (${t.chamber})`).join(', '),
      mostRecent:   trades.sort((a,b) => new Date(b.disclosureDate) - new Date(a.disclosureDate))[0].disclosureDate,
      clusterAlert: `CLUSTER BUY: ${trades.length} politicians buying ${sym}${inPortfolio ? ' ★ PORTFOLIO' : ''} — ${trades.map(t => t.name).join(', ')} — combined ~${amountTier(totalUpper)}`
    };
  })
  .sort((a, b) => b.buyCount !== a.buyCount ? b.buyCount - a.buyCount : 0);

// ---- 7. Portfolio trades — essential fields only, top 3 ----
const portfolioTrades = [...taggedTrades]
  .filter(t => t.inPortfolio)
  .sort((a, b) => b.compositeScore - a.compositeScore)
  .slice(0, 3)
  .map(t => ({
    symbol:          t.symbol,
    name:            t.name,
    chamber:         t.chamber,
