// Process Ratings — infers endpoint from row fields, uses FMP's symbol directly
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
const cutoff = new Date(Date.now() - SEVEN_DAYS_MS);

const allItems = $input.all();

const recentRatingChanges = {};
const recentPriceTargets = {};
const priceTargetConsensus = {};

// Reverse FMP normalization: BRK-B → BRK/B
function denormalize(sym) {
  if (!sym) return sym;
  return sym.replace('-', '/');
}

for (const item of allItems) {
  const row = item.json;
  const symbol = denormalize(row.symbol);
  if (!symbol) continue;

  // Infer endpoint type from row shape
  const isConsensus = row.targetConsensus != null || row.targetHigh != null || row.targetMedian != null;
  const isPriceTarget = row.priceTarget != null && !isConsensus;
  const isGrade = row.newGrade != null || row.gradingCompany != null;

  // === Consensus (no date, just one row per ticker) ===
  if (isConsensus) {
    priceTargetConsensus[symbol] = {
      high: row.targetHigh ?? null,
      low: row.targetLow ?? null,
      median: row.targetMedian ?? null,
      consensus: row.targetConsensus ?? null
    };
    continue;
  }

  // === Price target news ===
  if (isPriceTarget) {
    const dateField = row.publishedDate || row.date;
    if (!dateField) continue;
    const d = new Date(dateField);
    if (isNaN(d.getTime()) || d < cutoff) continue;

    if (!recentPriceTargets[symbol]) recentPriceTargets[symbol] = [];
    recentPriceTargets[symbol].push({
      date: dateField,
      firm: row.analystCompany || row.gradingCompany || 'Unknown',
      analyst: row.analystName || null,
      newTarget: row.priceTarget ?? null,
      previousTarget: row.priceWhenPosted ?? null
    });
    continue;
  }

  // === Grades ===
  if (isGrade) {
    if (!row.date) continue;
    const d = new Date(row.date);
    if (isNaN(d.getTime()) || d < cutoff) continue;

    if (!recentRatingChanges[symbol]) recentRatingChanges[symbol] = [];
    recentRatingChanges[symbol].push({
      date: row.date,
      firm: row.gradingCompany || 'Unknown',
      action: row.action || 'reiterated',
      previousGrade: row.previousGrade || null,
      newGrade: row.newGrade || null
    });
  }
}

// Sort and cap at 5 most recent per ticker
for (const sym of Object.keys(recentRatingChanges)) {
  recentRatingChanges[sym].sort((a, b) => new Date(b.date) - new Date(a.date));
  recentRatingChanges[sym] = recentRatingChanges[sym].slice(0, 5);
}
for (const sym of Object.keys(recentPriceTargets)) {
