// Filter to US only, exclude past events
const now = new Date();

const events = rawData
  .filter(row => row.country === 'US' || row.country === 'USA')
  .filter(row => {
    const d = new Date(row.date);
    return !isNaN(d.getTime()) && d >= now;
  })
  .map(row => ({
    event: row.event || 'Unknown',
    date: row.date,
    impact: row.impact || 'Low',
    previous: row.previous ?? null,
    estimate: row.estimate ?? null,
    unit: row.unit || null
  }))
  .sort((a, b) => new Date(a.date) - new Date(b.date));

// Group by day
const byDay = {};
for (const ev of events) {
  const day = ev.date.split(' ')[0] || ev.date.split('T')[0];
  if (!byDay[day]) byDay[day] = [];
  byDay[day].push(ev);
}

// High/medium impact only
const highImpactByDay = {};
for (const [day, dayEvents] of Object.entries(byDay)) {
  const filtered = dayEvents.filter(e => e.impact === 'High' || e.impact === 'Medium');
  if (filtered.length > 0) highImpactByDay[day] = filtered;
}

// Convert UTC to ET
function toET(utcDateStr) {
  const d = new Date(utcDateStr.replace(' ', 'T') + 'Z');
  if (isNaN(d.getTime())) return utcDateStr;
  return d.toLocaleString('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: true
  });
}

// Enrich with ET, dedup near-identical, strip nulls and UTC date
function enrichAndTrim(eventsList) {
  const seen = new Set();
  return eventsList
    .filter(e => {
      const key = `${e.event.replace(/\s*\([A-Za-z]{3}\)\s*$/, '')}|${e.date}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .map(e => {
      const trimmed = {
        event: e.event,
        dateET: toET(e.date),
        impact: e.impact
      };
      if (e.previous != null) trimmed.previous = e.previous;
      if (e.estimate != null) trimmed.estimate = e.estimate;
      if (e.unit) trimmed.unit = e.unit;
      return trimmed;
    });
}

const trimmedByDay = {};
for (const day of Object.keys(highImpactByDay)) {
  trimmedByDay[day] = enrichAndTrim(highImpactByDay[day]);
}

return [{
  json: {
    economicCalendar: {
      lookforwardDays: 14,
      from,
      to,
      eventsByDay: trimmedByDay,
      _meta: {
        totalEvents: events.length,
