  var mo = parseInt(p[1], 10);
  var q = mo <= 3 ? "Q1" : mo <= 6 ? "Q2" : mo <= 9 ? "Q3" : "Q4";
  return { q: q, year: p[0], asOf: String(d).slice(0, 10), key: p[0] + "-" + q };
