      if (!topSeller || chg < topSeller.chg) topSeller = { name: hs[h].investorName, chg: chg };
    }
    var fd = String(hs[h].filingDate || "").slice(0, 10);
    if (fd > newestFiled) newestFiled = fd;
  }
  flows.push({
    symbol: symF, net: net, buyers: buyers, sellers: sellers,
    topBuyer: topBuyer, topSeller: topSeller, newestFiled: newestFiled,
  });
}

function actorTag(actor) {
  if (!actor) return "";
  var famous = isFamous(actor.name) ? " ⭐" : "";
  return actor.name + famous + " (" + (actor.chg > 0 ? "+" : "") + formatValue(actor.chg) + ")";
}

var rows = [];

// Row 1: top net ACCUMULATION
var inflow = null;
for (var f1 = 0; f1 < flows.length; f1++) {
  if (flows[f1].net > 0 && (!inflow || flows[f1].net > inflow.net)) inflow = flows[f1];
}
if (inflow) {
  rows.push({
    symbol: inflow.symbol, isFund: false,
    line: inflow.symbol + ": TOP NET BUYING — institutions net added " + formatValue(inflow.net) +
      " (" + inflow.buyers + " buyers vs " + inflow.sellers + " sellers). Biggest buyer: " +
      actorTag(inflow.topBuyer) + " [latest filing " + shortDate(inflow.newestFiled) + "]",
  });
}

// Row 2: top net DISTRIBUTION
var outflow = null;
for (var f2 = 0; f2 < flows.length; f2++) {
  if (flows[f2].net < 0 && (!outflow || flows[f2].net < outflow.net)) outflow = flows[f2];
}
if (outflow) {
  rows.push({
    symbol: outflow.symbol, isFund: false,
    line: outflow.symbol + ": TOP NET SELLING — institutions net sold " + formatValue(Math.abs(outflow.net)) +
      " (" + outflow.sellers + " sellers vs " + outflow.buyers + " buyers). Biggest seller: " +
      actorTag(outflow.topSeller) + " [latest filing " + shortDate(outflow.newestFiled) + "]",
  });
}

// Remaining slots: named conviction-fund moves, newest filings first.
var fundCandidates = [];
var fpTickers = Object.keys(fundPositions);
for (var t = 0; t < fpTickers.length; t++) {
  var symT = fpTickers[t];
  var fundNames = Object.keys(fundPositions[symT]);
  for (var fn = 0; fn < fundNames.length; fn++) {
    var fName = fundNames[fn];
    var byDate = fundPositions[symT][fName];
    var dates = Object.keys(byDate).sort().reverse();
    var cur = byDate[dates[0]];
    var priorPos = dates.length > 1 ? byDate[dates[1]] : null;
    var stamp = " [as of " + shortDate(dates[0]) + (cur.filed ? ", filed " + shortDate(cur.filed) : "") + "]";

    var actionText;
    if (priorPos) {
      var delta = cur.shares - priorPos.shares;
      var pct = priorPos.shares > 0 ? Math.round((delta / priorPos.shares) * 100) : 0;
      if (delta > 0) actionText = "added " + formatShares(delta) + " sh (+" + pct + "%) — now " + formatShares(cur.shares) + " sh (" + formatValue(cur.value) + ")";
      else if (delta < 0) actionText = "trimmed " + formatShares(Math.abs(delta)) + " sh (" + pct + "%) — now " + formatShares(cur.shares) + " sh (" + formatValue(cur.value) + ")";
      else actionText = "held steady — " + formatShares(cur.shares) + " sh (" + formatValue(cur.value) + ")";
    } else {
      actionText = "holds — " + formatShares(cur.shares) + " sh (" + formatValue(cur.value) + ")";
    }

    fundCandidates.push({
      symbol: symT, isFund: true,
      line: symT + ": " + fName + " " + actionText + stamp,
      sortVal: cur.value,
      filedDate: cur.filed || "0000-00-00",
    });
  }
}
fundCandidates.sort(function (a, b) {
  if (a.filedDate !== b.filedDate) return a.filedDate > b.filedDate ? -1 : 1;
  return b.sortVal - a.sortVal;
});

// Row plan: TOP NET BUYING + TOP NET SELLING (already in rows), then
// exactly two named-fund rows: the most significant MOVE (biggest add or
// trim, not a hold), and the most RECENTLY FILED action. Max 4 rows total.
var usedTickers = {};
for (var u = 0; u < rows.length; u++) usedTickers[rows[u].symbol] = true;

function isMove(c) { return /added|trimmed|opened a new position|fully exited/.test(c.line); }

// Slot 3: biggest named-fund MOVE by dollar size
var moveCands = [];
for (var m1 = 0; m1 < fundCandidates.length; m1++) {
  if (isMove(fundCandidates[m1]) && !usedTickers[fundCandidates[m1].symbol]) moveCands.push(fundCandidates[m1]);
}
moveCands.sort(function (a, b) { return b.sortVal - a.sortVal; });
if (moveCands.length) {
  rows.push(moveCands[0]);
  usedTickers[moveCands[0].symbol] = true;
}

// Slot 4: most recently FILED named-fund action not already shown
var recentCands = [];
for (var m2 = 0; m2 < fundCandidates.length; m2++) {
  if (isMove(fundCandidates[m2]) && !usedTickers[fundCandidates[m2].symbol]) recentCands.push(fundCandidates[m2]);
}
recentCands.sort(function (a, b) {
  if (a.filedDate !== b.filedDate) return a.filedDate > b.filedDate ? -1 : 1;
  return b.sortVal - a.sortVal;
});
if (recentCands.length) {
  rows.push(recentCands[0]);
  usedTickers[recentCands[0].symbol] = true;
}

rows = rows.slice(0, 4);

var hasData = rows.length > 0;
var summaryParts = [];
if (hasData) {
  summaryParts.push("13F SMART MONEY SNAPSHOT (" + periodStr + ")", "",
    "NET FLOW + KEY MOVES (institutional filers; net figures from sampled filings):");
  for (var ml = 0; ml < rows.length; ml++) summaryParts.push("- " + rows[ml].line);
}

return [{ json: {
  smartMoney: {
    hasData: hasData, period: periodShort, periodFull: periodStr,
    rows: rows.map(function (r) { return { symbol: r.symbol, isFund: r.isFund, line: r.line }; }),
  },
  smartMoneySummary: hasData ? summaryParts.join("\n") : "",
  meta: {
    generatedAt: new Date().toISOString(),
    tickersAnalyzed: Object.keys(bookTickerSet).length,
    filingPeriod: periodStr, namedFundHits: Object.keys(fundPositions).length,
    dataSource: "SEC 13F filings via Financial Modeling Prep",
  },
}}];

// TICKER + NAMED FUND BUILDER — feeds the 13F HTTP Request
// Tracks ONLY this advisor's holdings + watchlist. Conviction funds only.
// Field-tolerant: reads Ticker, then tickers, then AllTickers, so both
// workflow paths/runs resolve the book regardless of upstream shape.
// Sanity filter kills #VALUE! sheet-error strings and other junk.
// Deadline-aware quarters; fully self-rolling.

var inputData = $input.first().json;

function collect(field) {
  var raw = inputData[field] || [];
  var out = [];
  for (var i = 0; i < raw.length; i++) {
    if (Array.isArray(raw[i])) {
      for (var j = 0; j < raw[i].length; j++) out.push(raw[i][j]);
    } else {
      out.push(raw[i]);
    }
  }
  return out;
}

function isTickerLike(t) {
  // 1-6 chars, uppercase letters/digits/dot/dash only. Kills "#VALUE! (...)".
  return /^[A-Z0-9.\-]{1,6}$/.test(t);
}

var skip = ["ETH", "BTC"];
var seen = {};
var bookTickers = [];

// primary holdings: first field that yields anything
var holdingsRaw = collect("Ticker");
if (!holdingsRaw.length) holdingsRaw = collect("tickers");
if (!holdingsRaw.length) holdingsRaw = collect("AllTickers");

var all = holdingsRaw.concat(collect("Watchlist"));
for (var k = 0; k < all.length; k++) {
  var t = String(all[k] || "").trim();
  if (t && !seen[t] && skip.indexOf(t) === -1 && isTickerLike(t)) {
    seen[t] = true;
    bookTickers.push(t);
  }
}

// ---- deadline-aware quarter math ----
function quarterEnd(y, q) {
  return new Date(Date.UTC(y, q * 3, 0));
}
function prevQuarter(y, q) {
  return q === 1 ? { y: y - 1, q: 4 } : { y: y, q: q - 1 };
}
var now = new Date();
var cy = now.getUTCFullYear();
var cq = Math.ceil((now.getUTCMonth() + 1) / 3);
var cand = prevQuarter(cy, cq);
var DAY = 86400000;
while (now - quarterEnd(cand.y, cand.q) < 50 * DAY) {
  cand = prevQuarter(cand.y, cand.q);
}
var latest = cand;
var prior = prevQuarter(latest.y, latest.q);

var filingQ = cq - 1;
var filingYear = cy;
if (filingQ <= 0) { filingQ = 4; filingYear = filingYear - 1; }

// Conviction funds only — verified CIKs (SEC EDGAR).
var NAMED_FUNDS = [
  { name: "Berkshire Hathaway",        cik: "0001067983" },
  { name: "Bridgewater Associates",    cik: "0001350694" },
  { name: "Point72 Asset Management",  cik: "0001603466" },
  { name: "Tiger Global Management",   cik: "0001167483" },
  { name: "Pershing Square Capital",   cik: "0001336528" },
  { name: "Elliott Investment Management", cik: "0001791786" },
  { name: "Coatue Management",         cik: "0001135730" },
  { name: "Appaloosa",                 cik: "0001656456" },
  { name: "Baupost Group",             cik: "0001061768" },
  { name: "Viking Global Investors",   cik: "0001103804" },
  { name: "Soros Fund Management",     cik: "0001029160" },
  { name: "Greenlight Capital",        cik: "0001079114" },
  { name: "Third Point",               cik: "0001040273" },
  { name: "Lone Pine Capital",         cik: "0001061165" },
  { name: "Dragoneer Investment Group", cik: "0001602189" },
  { name: "Altimeter Capital Management", cik: "0001541617" },
];

var output = [];
for (var b = 0; b < bookTickers.length; b++) {
  output.push({ json: {
    queryType: "ticker", ticker: bookTickers[b], page: 0,
    year: filingYear, quarter: filingQ,
  }});
}
for (var f = 0; f < NAMED_FUNDS.length; f++) {
  output.push({ json: {
    queryType: "fund", fundName: NAMED_FUNDS[f].name, cik: NAMED_FUNDS[f].cik,
    year: latest.y, quarter: latest.q,
  }});
  output.push({ json: {
    queryType: "fund", fundName: NAMED_FUNDS[f].name, cik: NAMED_FUNDS[f].cik,
    year: prior.y, quarter: prior.q,
  }});
}
return output;

parameters.text:
=This is your input for today's briefing. All data lives in the named blocks below. The system prompt refers to these blocks by name. If a block renders empty, "[]", "null", or "undefined", treat it as absent and omit dependent elements gracefully. Never print placeholder text.

=== SESSION (what "today" means on THIS run) ===

Run timestamp: {{ $json["Readable date"] }} ({{ $json.Timezone }})
Market data as of: {{ $json.rateDate }}

THE WINDOW THIS BRIEF COVERS depends on the mode. On a MORNING run, the window is overnight and pre-market since the prior session's close: that is what "new" means today. On an AFTERNOON run, the window is the session that just traded. Material outside the window may still be used when it is genuinely the most important thing available, but it is framed with its date and it does not lead two briefs in a row.

If the run timestamp falls on a Saturday or a Sunday, or before the opening bell on a weekday, THE MARKET DID NOT TRADE TODAY. Every price, move, and index level in this message is the LAST COMPLETED SESSION. Write "Friday's session" (or whichever day it was) and frame the brief as preparation for the NEXT open. Never write "today" about a session that has not happened, and never write "the market fell today" on a Sunday.

=== ADVISOR PROFILE ===

Name: {{ $json.advisorName }}

Firm: {{ $json.firm }}

Email: {{ $json.email }}

Mode: {{ $json.Mode }}

Temperature: {{ $json.Temperature }}

Context: {{ $json.Context }}

=== PORTFOLIO HOLDINGS ===

{{ $json.Ticker }}

=== WATCHLIST ===

{{ $json.Watchlist }}

=== WATCHLIST PERFORMANCE (nine windows: today, w1, m1, m3, m6, ytd, y1, y3, y5) ===

{{ JSON.stringify($json.watchlistPerf || null) }}

=== WATCHLIST QUOTES (price, day change, 52-week range, 50/200 day averages, volume. A watchlist name MAY carry its own price and move. It may NEVER carry a consensus target or an implied upside) ===

{{ JSON.stringify($json.watchlistQuotes || null) }}

=== TOPICS TRACKED ===

{{ $json.Topics }}

=== PEOPLE FOLLOWED ===

{{ $json.People }}

=== SITUATIONS MONITORED (Section 03 ONLY, every entry becomes a closed drawer, ranked by what moved today) ===

{{ $json.Situations }}

=== SENSITIVITY SCENARIOS (Section 07 scenario drawers ONLY, DIFFERENT from Situations. Scenario names come from here exactly, never from Situations. Do not cross-pollinate) ===

{{ JSON.stringify($json.Sensitivity) }}

=== MANDATE STRUCTURE (governs RULE 9. isMulti false, missing, or null means ONE book and Rule 9 is ignored entirely) ===

{{ JSON.stringify($json.mandates || { isMulti: false }) }}

=== BOOK MOVE (pre-computed, render verbatim, NEVER recompute or blend) ===

Combined: {{ $json.bookMoveSummary }} | Basis: {{ $json.bookMoveBasis }}

By mandate: {{ JSON.stringify($json.bookMoveByMandate || null) }}

=== QUOTE FAILURES (symbols that returned nothing this run. A name here has NO price, NO sector, and NO weight anywhere. Say nothing rather than guess, and never mention the failure) ===

{{ JSON.stringify($json.quotesFailed || []) }}

=== BENCHMARK SECTOR WEIGHTS (S&P 500 sector weights, for the X-Ray's active-bet read. If null, state tilts qualitatively and never estimate an index weight) ===

{{ JSON.stringify($json.benchmarkSectorWeights || null) }}

=== SECTOR EXPOSURE (pre-computed true ETF look-through; combined view when two mandates are live) ===

{{ JSON.stringify($json.sectorExposure) }}

=== SECTOR EXPOSURE BY MANDATE (multi only; null when single. Per-mandate svs-read lines reason from THIS, never the combined view) ===

{{ JSON.stringify($json.sectorExposureByMandate || null) }}

=== SECTOR CONTRIBUTIONS (which holdings and fund slices compose each sleeve) ===

{{ JSON.stringify($json.sectorContrib || null) }}

=== SECTOR CONTRIBUTIONS BY MANDATE (multi only; null when single. Use when a sector read must name the position driving that sleeve in that specific book) ===

{{ JSON.stringify($json.sectorContribByMandate || null) }}

=== SECTOR EXPOSURE META (basis, classified %, dropped funds. FOR YOUR REASONING ONLY: never mention coverage, classification or dropped funds anywhere in the brief) ===

{{ JSON.stringify($json.sectorExposureMeta || null) }}

=== HYPOTHETICAL BOOK RETURN (engine renders the Performance Scoreboard from this across nine windows. You get AT MOST one prose sentence, always labeled "based on your current allocation") ===

{{ JSON.stringify($json.hypoBookReturn || null) }}

=== HYPOTHETICAL BOOK RETURN BY MANDATE (multi only; null when single. Each carries its own coveragePct and mandateWeightPct. This is what lets you say which book carried the quarter without performing arithmetic) ===

{{ JSON.stringify($json.hypoBookReturnByMandate || null) }}

=== BENCHMARKS, TWO OF THEM (engine renders the scoreboard rows and the Edge row; reason from these, never emit their numbers) ===

S&P 500 (VOO), nine windows: {{ JSON.stringify($json.benchmarkPerf || null) }}

Nasdaq-100 (QQQ), nine windows: {{ JSON.stringify($json.benchmarkPerfQQQ || null) }}

Both together: {{ JSON.stringify($json.benchmarks || null) }}

=== HOLDINGS PERFORMANCE (per-holding trailing returns across nine windows plus the sector benchmark ticker; cite both sides verbatim. ETF rows have sector:null and are never benchmarked to a single SPDR. With two mandates each row also carries `mandates` and `weightInMandate`, and weightInMandate is the number that matters inside a mandate wrapper) ===

{{ JSON.stringify($json.holdingsPerf || null) }}

=== HOLDINGS BY MANDATE (multi only; null when single) ===

{{ JSON.stringify($json.holdingsByMandate || null) }}

=== POSITION WEIGHTS BY MANDATE (multi only; null when single. Each position's weight INSIDE its own book, never across both. A 12% position in the smaller book still leads that book) ===

{{ JSON.stringify($json.holdingsWeightsByMandate || null) }}

=== PRICE/TECH (each holding prefixed with "(X% of book)" when weights are set; no prefix means equal-weight) ===

{{ $json.quoteSummary }}

=== FULL QUOTES (each carries weightPct, or null when unweighted) ===

{{ JSON.stringify($json.quotes) }}

=== VALUATION (multiples, margins, and QUARTERLY MARGIN TRENDS per holding. `trends.direction` counts consecutive quarters. `trends.flip` marks a margin that changed sign THIS quarter. `trends.breakeven` projects at the current pace and must always be framed as an estimate. `trends.vsSector` fires only when a name moves opposite its own sector peers IN THIS BOOK. Sector names here are RAW FEED NAMES: Consumer Cyclical is Consumer Discretionary, Financial Services is Financials, Healthcare is Health Care, Basic Materials is Materials, Consumer Defensive is Consumer Staples. ETFs and crypto proxies legitimately return nothing) ===

{{ JSON.stringify($json.valuation || []) }}

=== SECTOR P/E (yesterday's snapshot, all 11 sectors. This is what turns a multiple into an active-bet read: a holding at 28x against a sector at 22x is paying a premium, and the question is what for) ===

{{ JSON.stringify($json.sectorPE || null) }}

=== SECTOR MARGIN TREND (median operating-margin move for each sector's names IN THIS BOOK. The peer set is the reader's own holdings, which is why a divergence lands) ===

{{ JSON.stringify($json.sectorMarginTrend || null) }}

=== COMPANY PROFILES (sector, industry, beta, marketCap, isEtf per ticker) ===

{{ JSON.stringify(Object.fromEntries(Object.entries($json.profiles?.profilesByTicker || {}).map(function(e){ return [e[0], { sector: e[1].sector, industry: e[1].industry, companyName: e[1].companyName, marketCap: e[1].marketCap, beta: e[1].beta, dividendYield: e[1].dividendYield, isEtf: e[1].isEtf, isFund: e[1].isFund, isAdr: e[1].isAdr }]; }))) }}

=== SECTOR ETFs, LIVE (all 11 SPDRs) ===

By symbol: {{ JSON.stringify($json.sectorETFs?.bySymbol || {}) }}

Ranked by performance: {{ JSON.stringify($json.sectorETFs?.sortedByPerformance || []) }}

=== SENTIMENT & TECHNICALS ===

VIX: {{ $json.vix }}

SRO: {{ $json.sro }}% ({{ $json.sroRegime }})

Portfolio Avg RSI: {{ $json.portfolioAvgRsi }}

Most Overbought / Oversold: {{ $json.rsiBarSummary }}

RSI Full Scan: {{ $json.rsiSummary }}

=== EARNINGS ===

Count (next 7 days): {{ $json.earningsCount }}

Summary: {{ $json.summaryLine }}

Window: {{ $json.windowFrom }} → {{ $json.windowTo }}

Data: {{ JSON.stringify($json.earningsThisWeek) }}

=== ECONOMIC CALENDAR (14 days forward) ===

{{ JSON.stringify($json.economicCalendar?.eventsByDay || {}) }}

=== MACRO (FRED) ===

{{ $json.macroSummary }}

=== MACRO CONTEXT (every series judged against its OWN two-year history) ===

{{ $json.macroContext }}

A level alone is a fact; a level against its own range is an argument, and the argument is what the reader is paying for. **Every figure that carries a sentence of argument carries its comparator; incidental figures stay bare.** A full brief normally lands around twelve to fourteen comparative figures. "The 30-year is at 5.19%" is worth far less than "the 30-year is at 5.19%, the 96th percentile of the last two years." USE THE PERCENTILE whenever a rate, spread, or level carries the weight of a paragraph. Copy the figures character for character. Never compute a percentile yourself, and never describe a level as high or low without the number that makes it so.

Any line ending in [STALE, do not call this today's level] is real data with an older print date. Cite it WITH its date ("as of August 21") or leave it out. Never attach a present-tense verb to it.

=== DERIVED MACRO READS (pre-computed cross-series conclusions) ===

{{ $json.macroDerived }}

These are computed in code from the series above, not inferred. Render them as written when you use them, and NEVER recompute, re-derive, or contradict them. Two carry unusual weight:

- AT A TWO-YEAR EXTREME is the single most quotable macro fact available on any given day. If a series your book actually depends on sits at an extreme, that belongs in Section 01 or the Section 02 opener.
- REGIME DIVERGENCE appears only when the risk-appetite gauges and the rate gauges sit at OPPOSITE two-year extremes. When it appears, it is usually the most important sentence in the entire macro picture: it means the volatility and credit markets are priced for calm while the long end and the low-quality end of credit are not. Do not bury it.

If a line reads "Not computed" with a reason, that is a deliberate refusal because the inputs were not comparable. Respect it. Do not perform the comparison yourself.

=== FIXED INCOME (FRED, EOD; OAS spreads lag ~1 day. Render verbatim in the FI drawer; the engine re-verifies) ===

2Y: {{ $json.yield2Y }}% (Δ {{ $json.yield2YChg }}) | 10Y: {{ $json.yield10Y }}% (Δ {{ $json.yield10YChg }}) | 30Y: {{ $json.yield30Y }}% (Δ {{ $json.yield30YChg }}) | 2s10s: {{ $json.spread2s10s }} (Δ {{ $json.spread2s10sChg }})

10Y Real (TIPS): {{ $json.realYield10 }}% (Δ {{ $json.realYield10Chg }}) | 10Y Breakeven: {{ $json.breakeven10 }}% (Δ {{ $json.breakeven10Chg }})

HY OAS: {{ $json.hySpread }}% (Δ {{ $json.hySpreadChg }}) | IG OAS: {{ $json.igSpread }}% (Δ {{ $json.igSpreadChg }})

Fed Funds Target Range: {{ $json.fedFundsRate }} (as of {{ $json.rateDate }})

=== GROWTH, LABOR, HOUSING AND THE DOLLAR (supports the TOPICS above; several series are weekly or monthly) ===

{{ $json.growthSummary }}

Every figure here is dated and SEVERAL ARE NOT CURRENT. A line marked [N DAYS OLD, this is NOT a current reading] must be cited with its date or omitted. GDPNow rebases each quarter, so it carries a level and no change figure. These series exist so a tracked topic (the dollar, GDP, housing, the labor market) can rest on a number instead of on a headline.

=== INDEX & COMMODITY CLOSES (engine renders the snapshot tiles; use these for prose only. indexCloses carries spx, ixic, qqq, and vix, each with price and percent move) ===

Indexes: {{ JSON.stringify($json.indexCloses) }}

Commodities: {{ $json.commoditySummary }}

=== CORPORATE INSIDER TRADES (powers Insider Edge in Section 05) ===

{{ $json.insiderSummary }}

=== 13F INSTITUTIONAL SMART MONEY (last-quarter filings, Hedge Fund Flow) ===

{{ $json.smartMoneySummary }}

=== POLITICIAN TRADES (powers the political line in Insider Edge) ===

Summary: {{ $json.polSummaryLine }}

Top Trade Overall: {{ JSON.stringify($json.topTrade) }}

Top Portfolio Trade: {{ JSON.stringify($json.topPortfolioTrade) }}

Top Cluster Buy: {{ JSON.stringify($json.topCluster) }}

Cluster Buys (all): {{ JSON.stringify($json.polClusterBuys) }}

Portfolio Politician Trades: {{ JSON.stringify($json.portfolioTrades) }}

Top By Dollar: {{ JSON.stringify($json.topByDollar) }}

=== ANALYST RATINGS & PRICE TARGETS (only state "from $Y" when a prior target is explicitly present. READ THE RATING ACTIONS, NOT JUST THE TARGET MOVES: a firm that lifts a target and MAINTAINS Neutral is saying something a target raise alone does not) ===

Recent Rating Changes: {{ JSON.stringify($json.recentRatingChanges) }}

Recent Price Target Changes: {{ JSON.stringify($json.recentPriceTargets) }}

Price Target Consensus: {{ JSON.stringify($json.priceTargetConsensus) }}

=== ANALYST DESK ROLLUP (digested; respect any "EXCLUDED as likely-stale" line, and that exclusion is binding everywhere in the brief) ===

{{ JSON.stringify($json.analystDeskSummary) }}

=== HOUSE NEWS (Institutional Whisper ONLY; use only what is here, never fill from memory; links are redirects, cite as plain (Source) spans, never paste them) ===

{{ JSON.stringify($json.houseNewsContext) }}

=== STOCK NEWS (holdings-specific news + press releases, DIRECT publisher URLs, safe to link. Several items per ticker: the FIRST is rarely the best one) ===

Summary by ticker:

{{ $json.stockNews?.summary || '(none)' }}

Full items with URLs:

{{ JSON.stringify($json.stockNews?.digest || []) }}

=== SEC FILINGS, PRIMARY SOURCE (8-K item codes, 13D/13G; last 5 days) ===

{{ $json.secFilingsSummary }}

This is the highest evidence tier in the entire message: the company's own filing, not an article about it. THE ITEM CODE IS THE SIGNAL, and the codes are not interchangeable:

- Item 4.02 (non-reliance, a restatement), Item 1.03 (bankruptcy), Item 1.05 (material cybersecurity incident), Item 3.01 (delisting notice), Item 4.01 (auditor change), Item 5.01 (change in control): on a HELD name, any of these is the most important thing in the brief and LEADS Section 01. No exceptions.
- Item 5.02 (officer or director departure) on a held name is a desk-item candidate on its own. Several across the book in one week is a pattern worth naming.
- Item 2.02 is the earnings 8-K and pairs with the earnings data elsewhere in this message.
- A SC 13D is an activist stake with a stated purpose, filed within days. It is news. A SC 13G is a passive stake, usually an index fund, and is rarely worth a line.

A filing tagged "inferred from the release, not read off the filing body" had its item code deduced from an attached press release rather than read from the filing itself. Use the substance, never claim the filing "states" the item.

A WATCHLIST filing may be described as an EVENT ("Intel filed an 8-K disclosing an officer change") and never carries a target, a valuation, or an implied upside.

Link the filing URL directly. Cite it as (SEC).

=== PEOPLE NEWS (for People Watch) ===

{{ JSON.stringify($json.peopleNews) }}

=== NEWS CONTEXT (all market feeds, pre-aggregated, deduped, and CAPPED PER PUBLISHER so no single source dominates. Roughly 90 items across a dozen outlets. This is your ONLY source of general market news. Where an item carries a `facts` field, those are hard operational details pulled from the ARTICLE BODY that the headline did not contain: named facilities, people below CEO level, contract terms, dollar figures, capacity numbers. PREFER those for any niche or operational read. An item with no `facts` field was commentary, which is normal and not a gap.

EVERY ITEM ALSO CARRIES: `publisher` (the publication name, USE THIS when you cite, never the bare domain), `tier` (1 = primary source or wire, 2 = major financial press, 3 = aggregator or commentary), `opinion` (true means it argues a view rather than reporting a fact, so attribute it as opinion), and `ageHours`.

TIER IS A RANKING TOOL, NOT A BAN. Every item here is available to you. But AT LEAST ONE of the two Must-Read articles must be tier 1 or tier 2, and when two items cover the same story, cite the lower-tier number. A tier-3 aggregator in a premium slot while a wire covered the same story is the fastest way to lose a professional reader) ===

