// ── n8n Code node: "Strip Market Pulse -> Podcast Text" v3 ──
// Mode: Run Once for All Items
// Input:  EITHER the Validator output [{ output: "<div class='...'>...</div>" }]
//         OR the raw DeepSeek response  [{ choices: [{ message: { content: "<div ...>" } }] }]
//         OR the old agent node output  [{ output: "..." }]
// Output: [{ podcastInput: "[FIRST ON YOUR DESK]\n...", sectionCount: N }]
//
// v3: reads the brief from whichever shape arrives, and strips a markdown code
// fence if the model wrapped the brief in one. Wire this node from the Validator
// so a truncated brief never becomes a podcast.
//
// v2: STOPPED matching hardcoded class names (they change every prompt
// version and silently drop sections). Splits on the brief's own
// sec-num/sec-title markers, so every section the agent authors is captured
// with its own title as the header. Version-proof against markup renames.

// Inner label divs whose text duplicates section headers: remove them.
const REDUNDANT_LABEL_CLASSES =
  /<div\s+class\s*=\s*["'][^"']*\b(subsection-label|big-idea-part-label|big-idea-selected-tag|smart-money-label|analyst-revisions-label|mover-label|sens-label|wildcard-label|trump-pulse-label|must-read-label|lbl|dl)\b[^"']*["'][^>]*>.*?<\/div>/gis;

function htmlToText(html) {
  let t = html;
  t = t.replace(REDUNDANT_LABEL_CLASSES, ' ');
  // Drop <a> tags entirely; links are citations and the podcast cannot read URLs.
  t = t.replace(/<a\b[^>]*>.*?<\/a>/gis, '');
  t = t.replace(/\(\s*(source|filing)\s*\)/gi, '');
  t = t.replace(/\(\s*\)/g, '');
  // Lists and breaks to newlines.
  t = t.replace(/<li\b[^>]*>/gi, '\n- ').replace(/<\/li>/gi, '');
  t = t.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n');
  t = t.replace(/<\/div>/gi, '\n');
  // Strip remaining tags.
  t = t.replace(/<[^>]+>/g, ' ');
  // Decode entities.
  t = t.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
       .replace(/&nbsp;/g, ' ').replace(/&plusmn;/g, '+/-')
       .replace(/&middot;/g, '-').replace(/&#39;|&rsquo;/g, "'")
       .replace(/&quot;/g, '"').replace(/&mdash;/g, '-').replace(/&ndash;/g, '-');
  // Ban em and en dashes in the deliverable chain.
  t = t.replace(/\u2014/g, '-').replace(/\u2013/g, '-');
  // Strip emoji and dingbats that TTS stumbles on.
  t = t.replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '');
  // Tidy whitespace.
  t = t.replace(/[ \t]+/g, ' ')
       .replace(/ *\n */g, '\n')
       .replace(/\n{3,}/g, '\n\n')
       .trim();
  return t;
}

// Read the brief from whichever shape arrived.
function readBrief(json) {
  let raw = json.output
    || (json.choices && json.choices[0] && json.choices[0].message && json.choices[0].message.content)
    || json.text
    || '';
  raw = String(raw);
  // Strip a markdown code fence the model sometimes wraps the brief in.
  raw = raw.replace(/^\s*```(?:html)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  return raw;
}

const out = [];
for (const item of $input.all()) {
  const raw = readBrief(item.json);
  const blocks = [];
  // Split the document at every section marker (sec-num). Everything between
  // one marker and the next is one section.
  const marker = /<div\s+class\s*=\s*["'][^"']*\bsec-num\b[^"']*["'][^>]*>/gi;
  const starts = [];
  let m;
  while ((m = marker.exec(raw)) !== null) starts.push(m.index);
  if (starts.length === 0) {
    // Fallback: no markers at all. Strip the whole document as one block
    // rather than shipping nothing.
    const whole = htmlToText(raw);
    if (whole) blocks.push('[MARKET BRIEF]\n' + whole);
  } else {
    for (let s = 0; s < starts.length; s++) {
      const chunk = raw.slice(starts[s], s + 1 < starts.length ? starts[s + 1] : raw.length);
      // Section title from the chunk's own sec-title div.
      const titleMatch = chunk.match(/<div\s+class\s*=\s*["'][^"']*\bsec-title\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);
      let title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : ('SECTION ' + (s + 1));
      title = title.toUpperCase();
      // Remove the sec-num and sec-title divs themselves before text conversion.
      let body = chunk
        .replace(/<div\s+class\s*=\s*["'][^"']*\bsec-num\b[^"']*["'][^>]*>[\s\S]*?<\/div>/i, '')
        .replace(/<div\s+class\s*=\s*["'][^"']*\bsec-title\b[^"']*["'][^>]*>[\s\S]*?<\/div>/i, '');
      const text = htmlToText(body);
      if (text) blocks.push('[' + title + ']\n' + text);
    }
  }
  out.push({
    json: {
      podcastInput: blocks.join('\n\n'),
      sectionCount: blocks.length,
    },
  });
}
return out;

// ============================================================
//  ANALYST DESK ROLLUP v2  (n8n Code node - "Run Once for All Items")
//  Reads data ALREADY in the merged payload and builds one
//  plain-text string the agent uses for the Institutional Whisper
//  and the Analyst Price Targets block.
//  PASSES THE FULL PAYLOAD THROUGH UNCHANGED + adds analystDeskSummary.
//
//  v2 CHANGES vs v1:
//   1. HOLDINGS vs WATCHLIST separated end to end. Watchlist names get
//      their own clearly-labeled PT-move section carrying an explicit
//      instruction: analyst ACTIONS may be referenced, but a watchlist
//      name NEVER gets a consensus target, an implied upside, or a
//      price stated (Rule 0 item 8). The consensus-gap layer is
//      holdings-only BY CONSTRUCTION, even now that watchlistQuotes
//      exist, so a watchlist price can never produce an upside line.
//   2. PER-MANDATE tags when two books are live: every holdings PT move
//      and rating action carries [BookName], and a one-line mandate
//      digest tells the model where this week's analyst attention
//      concentrated.
//   3. Sanity guard extended: a consensus more than 60% BELOW the live
//      price is flagged as likely-stale alongside the >100%-above guard.
//   4. Explicit no-coverage line so the model knows which held names
//      have no analyst data this week (prevents padding).
//  Everything else from v1 preserved: the 7-day window framing, the
//  maintains rollup, the stale exclusions, fmt and pct helpers.
// ============================================================

const item = $input.first().json;

function unwrap(v){ return (Array.isArray(v) && v.length === 1 && !Array.isArray(v[0]) && typeof v[0] === 'object') ? v[0] : v; }
const mandates = unwrap(item.mandates) || null;
const holdingsByMandate = unwrap(item.holdingsByMandate) || null;
const isMulti = !!(mandates && mandates.isMulti === true
  && Array.isArray(mandates.portfolios) && mandates.portfolios.length > 1
  && holdingsByMandate);

const recentPriceTargets   = item.recentPriceTargets   || {};
const recentRatingChanges  = item.recentRatingChanges  || {};
const priceTargetConsensus = item.priceTargetConsensus || {};
const quotes               = Array.isArray(item.quotes) ? item.quotes : [];
const watchlistQuotes      = Array.isArray(item.watchlistQuotes) ? item.watchlistQuotes : [];

// ---------- who is held, who is watchlist, who is in which book ----------
const heldSet = {};
const priceMap = {};   // HOLDINGS ONLY. Watchlist prices are deliberately kept
                       // out so the consensus-gap layer can never compute an
                       // upside for a name this reader does not hold.
for (const q of quotes){
  const s = String(q.symbol || '').toUpperCase().trim();
  if (!s) continue;
  heldSet[s] = 1;
  if (q.price != null) priceMap[s] = Number(q.price);
}
const watchSet = {};
{
  const wl = item.Watchlist;
  const flat = Array.isArray(wl) ? (Array.isArray(wl[0]) ? wl[0] : wl) : String(wl || '').split(/[,;\n]+/);
  flat.forEach(function(t){
    const s = String(t).toUpperCase().trim();
    if (s && !heldSet[s]) watchSet[s] = 1;
  });
  watchlistQuotes.forEach(function(q){
    const s = String(q.symbol || '').toUpperCase().trim();
    if (s && !heldSet[s]) watchSet[s] = 1;
  });
}
const mandateOf = {};
if (isMulti){
  mandates.portfolios.forEach(function(p){
    (holdingsByMandate[p.name] || []).forEach(function(t){
      const s = String(t).toUpperCase().trim();
      if (!mandateOf[s]) mandateOf[s] = [];
      mandateOf[s].push(p.name);
    });
  });
}
function tag(ticker){
  if (!isMulti) return '';
  const m = mandateOf[String(ticker).toUpperCase().trim()];
  return (m && m.length) ? ' [' + m.join(' + ') + ']' : '';
}

const fmt = (n) => {
  const x = Number(n);
  if (!isFinite(x)) return 'N/A';
  return x >= 100 ? '$' + x.toFixed(0) : '$' + x.toFixed(2);
};
const pct = (n) => (n >= 0 ? '+' : '') + n.toFixed(0) + '%';

// ---------- LAYER A: price-target moves (last 7d), holdings and watchlist apart ----------
const ptHold = [];
const ptWatch = [];
for (const [ticker, arr] of Object.entries(recentPriceTargets)){
  if (!Array.isArray(arr)) continue;
  const T = String(ticker).toUpperCase().trim();
  for (const t of arr){
    const nt = Number(t.newTarget), pt = Number(t.previousTarget);
    if (!isFinite(nt) || !isFinite(pt) || pt === 0) continue;
    const chg = ((nt - pt) / pt) * 100;
    if (Math.abs(chg) < 1) continue;   // skip noise / reiterations at the same level
    const row = { ticker: T, firm: t.firm || 'firm', date: (t.date || '').slice(0, 10), newT: nt, prevT: pt, chg: chg };
    if (heldSet[T]) ptHold.push(row);
    else if (watchSet[T]) ptWatch.push(row);
    else ptHold.push(row);   // unknown names stay in the main list, as v1 did
  }
}
ptHold.sort((a, b) => Math.abs(b.chg) - Math.abs(a.chg));
ptWatch.sort((a, b) => Math.abs(b.chg) - Math.abs(a.chg));

const ptHoldLines = ptHold.slice(0, 12).map(m =>
  `• ${m.ticker}${tag(m.ticker)}: ${m.firm} → ${fmt(m.newT)} (from ${fmt(m.prevT)}, ${pct(m.chg)}) [${m.date}]`
);
// Watchlist rows show the firm ACTION only. No live price, no upside math.
const ptWatchLines = ptWatch.slice(0, 8).map(m =>
  `• ${m.ticker}: ${m.firm} moved its target ${m.chg >= 0 ? 'UP' : 'DOWN'} ${pct(Math.abs(m.chg))} on ${m.date}`
);

// ---------- LAYER B: rating actions, same split ----------
const ratingHold = [];
const ratingWatch = [];
let maintainCount = 0;
const maintainTickers = new Set();
for (const [ticker, arr] of Object.entries(recentRatingChanges)){
  if (!Array.isArray(arr)) continue;
  const T = String(ticker).toUpperCase().trim();
  for (const r of arr){
    const action = (r.action || '').toLowerCase();
    if (action === 'maintain'){ maintainCount++; maintainTickers.add(T); continue; }
    const line = `• ${T}${heldSet[T] ? tag(T) : ''}: ${r.firm || 'firm'} ${action.toUpperCase()} ${r.previousGrade || '?'} → ${r.newGrade || '?'} [${(r.date || '').slice(0,10)}]`;
    if (watchSet[T] && !heldSet[T]) ratingWatch.push(line);
    else ratingHold.push(line);
  }
}

// ---------- LAYER C: consensus gap vs live price. HOLDINGS ONLY, BY CONSTRUCTION ----------
const gaps = [];
for (const [ticker, c] of Object.entries(priceTargetConsensus)){
  const T = String(ticker).toUpperCase().trim();
  if (!heldSet[T]) continue;                    // watchlist and unknown names never enter
  const price = priceMap[T];
  const cons = c && Number(c.consensus);
  if (!isFinite(price) || !isFinite(cons) || price === 0) continue;
  const upside = ((cons - price) / price) * 100;
  gaps.push({ ticker: T, price, cons, upside, high: c.high, low: c.low });
}

// stale guards: >100% above the price, or >60% below it, is almost always broken
// FMP data (pre-split, dropped coverage). Pull those out of the ranking.
const MAX_PLAUSIBLE_UPSIDE = 100;
const MAX_PLAUSIBLE_DOWNSIDE = -60;
const staleGaps = gaps.filter(g => g.upside > MAX_PLAUSIBLE_UPSIDE || g.upside < MAX_PLAUSIBLE_DOWNSIDE);
const cleanGaps = gaps.filter(g => g.upside <= MAX_PLAUSIBLE_UPSIDE && g.upside >= MAX_PLAUSIBLE_DOWNSIDE);
cleanGaps.sort((a, b) => b.upside - a.upside);

const topUpside = cleanGaps.slice(0, 5).map(g =>
  `• ${g.ticker}${tag(g.ticker)}: ${pct(g.upside)} to consensus (${fmt(g.price)} → ${fmt(g.cons)})`
);
const aboveConsensus = cleanGaps.filter(g => g.upside < 0).map(g =>
  `• ${g.ticker}${tag(g.ticker)}: trading ${pct(g.upside)} vs consensus, ABOVE street target (${fmt(g.price)} vs ${fmt(g.cons)})`
);
const staleNote = staleGaps.map(g => `${g.ticker} (${pct(g.upside)})`);

// ---------- coverage honesty: held names with zero analyst data this week ----------
const touched = {};
ptHold.forEach(m => touched[m.ticker] = 1);
ratingHold.forEach(l => { const m = l.match(/^• ([A-Z.\-]+)/); if (m) touched[m[1]] = 1; });
maintainTickers.forEach(t => touched[t] = 1);
cleanGaps.forEach(g => touched[g.ticker] = 1);
const noCoverage = Object.keys(heldSet).filter(t => !touched[t]).sort();

// ---------- per-mandate digest ----------
let mandateDigest = '';
if (isMulti){
  const counts = {};
  mandates.portfolios.forEach(p => counts[p.name] = 0);
  ptHold.forEach(m => (mandateOf[m.ticker] || []).forEach(n => counts[n]++));
  ratingHold.forEach(l => {
    const m = l.match(/^• ([A-Z.\-]+)/);
    if (m) (mandateOf[m[1]] || []).forEach(n => counts[n]++);
  });
  mandateDigest = Object.keys(counts).map(n => n + ': ' + counts[n] + ' analyst action' + (counts[n] === 1 ? '' : 's')).join(' · ');
}

// ---------- assemble ----------
const out = [];
out.push('ANALYST DESK ROLLUP, firm-attributed, last 7 days. Use ONLY what appears below; do not invent firms, targets, or grades.');
out.push('');
out.push('PRICE TARGET MOVES ON YOUR HOLDINGS (this week):');
out.push(ptHoldLines.length ? ptHoldLines.join('\n') : '• None in the last 7 days.');
if (ptWatchLines.length){
  out.push('');
  out.push('ANALYST ACTIONS ON WATCHLIST NAMES (tracked, NOT held. These may be referenced as analyst ACTIVITY only. NEVER state a consensus target, an implied upside, or a share price for any name in this list):');
  out.push(ptWatchLines.join('\n'));
}
out.push('');
out.push('RATING ACTIONS (upgrades/downgrades):');
if (ratingHold.length) out.push(ratingHold.join('\n'));
else out.push('• No upgrades/downgrades on holdings; ' + maintainCount + ' reiterations across ' + (maintainTickers.size || 0) + ' names.');
if (ratingHold.length && maintainCount){
  out.push('  (plus ' + maintainCount + ' reiterations across ' + maintainTickers.size + ' names.)');
}
if (ratingWatch.length){
  out.push('Watchlist rating actions (activity only, same restriction as above):');
  out.push(ratingWatch.join('\n'));
}
out.push('');
out.push('CONSENSUS GAP (live price vs street consensus. HOLDINGS ONLY. No watchlist name has a citable consensus or upside, ever):');
out.push('Biggest upside:');
out.push(topUpside.length ? topUpside.join('\n') : '• N/A');
if (aboveConsensus.length){
  out.push('Trading above consensus (street has caught up / overshot):');
  out.push(aboveConsensus.join('\n'));
}
if (staleNote.length){
  out.push('');
  out.push('EXCLUDED as likely-stale consensus data, DO NOT cite: ' + staleNote.join(', '));
}
if (noCoverage.length){
  out.push('');
  out.push('NO ANALYST DATA THIS WEEK on: ' + noCoverage.join(', ') + '. Do not manufacture analyst context for these names.');
}
if (mandateDigest){
  out.push('');
  out.push('WHERE THE ATTENTION CONCENTRATED: ' + mandateDigest + '.');
}

const analystDeskSummary = out.join('\n');

// passthrough + new field (mandates re-emitted unwrapped for downstream)
return [{ json: Object.assign({}, item, {
  mandates: mandates,
  holdingsByMandate: holdingsByMandate,
  analystDeskSummary: analystDeskSummary
}) }];

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  SECTOR LOOK-THROUGH v6 , true underlying exposure + multi-timeframe returns ║
// ║  + per-sector CONTRIBUTION MAP + PER-MANDATE everything + dual benchmarks.   ║
// ║                                                                              ║
// ║  v6 CHANGES vs v5:                                                           ║
// ║   1. EIGHT RETURN WINDOWS everywhere: w1 (1 week), y3, y5 join today/m1/m3/  ║
// ║      m6/ytd/y1. Same FMP endpoint, zero extra API calls. Applies to sector   ║
// ║      rows, holdingsPerf, hypoBookReturn, benchmarks, watchlistPerf.          ║
// ║   2. DUAL BENCHMARKS: benchmarkPerf stays VOO (S&P 500, backward             ║
// ║      compatible). NEW benchmarkPerfQQQ (Nasdaq-100 via QQQ) and a combined   ║
// ║      `benchmarks` object carrying both.                                      ║
// ║   3. PER MANDATE, when mandates.isMulti (all null on a single book):         ║
// ║        sectorExposureByMandate    top-7 + Other per book                     ║
// ║        sectorExposureFullByMandate                                           ║
// ║        sectorContribByMandate                                                ║
// ║        hypoBookReturnByMandate    eight windows per book                     ║
// ║      Weights are that book's own, normalized within the book (they arrive   ║
// ║      that way from Aggregate Sheets). ETF sector weightings are fetched      ║
// ║      once per ticker and cached, so the per-mandate pass costs zero extra    ║
// ║      ETF calls.                                                              ║
// ║   4. holdingsPerf rows gain `mandates`: which book(s) hold the name, and     ║
// ║      `weightInMandate`: the position's weight inside its own book.           ║
// ║   5. Watchlist parsing hardened for the clean array shape (and the legacy    ║
// ║      nested/string shapes), cap raised to 12, held names still skipped.      ║
// ║  Everything from v5 is preserved: drop-don't-misassign for unresolvable     ║
// ║  ETFs, coverage honesty in sectorExposureMeta, the pass-through root.        ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

const FMP_KEY = 'REDACTED_FMP_KEY';

const SECTOR_NORMALIZE = {
  'Financial Services': 'Financials', 'Financials': 'Financials',
  'Technology': 'Technology', 'Information Technology': 'Technology',
  'Healthcare': 'Health Care', 'Health Care': 'Health Care',
  'Consumer Cyclical': 'Consumer Discretionary', 'Consumer Discretionary': 'Consumer Discretionary',
  'Consumer Defensive': 'Consumer Staples', 'Consumer Staples': 'Consumer Staples',
  'Communication Services': 'Communication Services',
  'Industrials': 'Industrials', 'Energy': 'Energy', 'Utilities': 'Utilities',
  'Basic Materials': 'Materials', 'Materials': 'Materials', 'Real Estate': 'Real Estate'
};
function normSector(s){ if (!s) return null; return SECTOR_NORMALIZE[s] || s; }

const SECTOR_TO_SPDR = {
  'Technology': 'XLK', 'Financials': 'XLF', 'Health Care': 'XLV',
  'Consumer Discretionary': 'XLY', 'Consumer Staples': 'XLP',
  'Communication Services': 'XLC', 'Industrials': 'XLI', 'Energy': 'XLE',
  'Utilities': 'XLU', 'Materials': 'XLB', 'Real Estate': 'XLRE'
};
const EXCLUDE_SECTORS = { 'Cash & Others': 1, 'Cash': 1, 'Other': 1, 'Others': 1, 'N/A': 1 };

const root = $input.first().json;

// ── unwrap guards (Price Data v2 already normalizes; this survives without it) ─
function unwrap(v){ return (Array.isArray(v) && v.length === 1 && !Array.isArray(v[0]) && typeof v[0] === 'object') ? v[0] : v; }
const mandates = unwrap(root.mandates) || null;
const holdingsByMandate = unwrap(root.holdingsByMandate) || null;
const holdingsWeightsByMandate = unwrap(root.holdingsWeightsByMandate) || null;

const quotes = Array.isArray(root.quotes) ? root.quotes : [];
const profByT = (root.profiles && root.profiles.profilesByTicker) || {};
const spdr = (root.sectorETFs && root.sectorETFs.bySymbol) || {};

// ── 1) per-position COMBINED weight ────────────────────────────────────────────
const haveWeights = quotes.some(q => typeof q.weightPct === 'number' && isFinite(q.weightPct));
const N = quotes.length || 1;
function weightFor(q){
  if (haveWeights) return (typeof q.weightPct === 'number' && isFinite(q.weightPct)) ? q.weightPct : 0;
  return 100 / N;
}

// ── 2) trailing-returns helper , EIGHT windows, cached per ticker ──────────────
function num(v){ const n = parseFloat(v); return isFinite(n) ? n : null; }
const EMPTY_PERF = { today: null, w1: null, m1: null, m3: null, m6: null, ytd: null, y1: null, y3: null, y5: null };
function emptyPerf(){ return Object.assign({}, EMPTY_PERF); }

async function fetchPriceChange(ticker){
  try {
    const url = 'https://financialmodelingprep.com/stable/stock-price-change?symbol='
      + encodeURIComponent(ticker) + '&apikey=' + FMP_KEY;
    const resp = await this.helpers.httpRequest({ url: url, method: 'GET', json: true });
    const r = Array.isArray(resp) ? resp[0] : resp;
    if (!r) return null;
    const round = (x) => x === null ? null : Math.round(x * 100) / 100;
    return {
      today: round(num(r['1D'])),
      w1:    round(num(r['5D'])),
      m1:    round(num(r['1M'])),
      m3:    round(num(r['3M'])),
      m6:    round(num(r['6M'])),
      ytd:   round(num(r['ytd'])),
      y1:    round(num(r['1Y'])),
      y3:    round(num(r['3Y'])),
      y5:    round(num(r['5Y']))
    };
  } catch (e) { return null; }
}
const priceChangeCache = {};
async function getPriceChange(ticker){
  const t = String(ticker || '').toUpperCase().trim();
  if (!t) return null;
  if (priceChangeCache.hasOwnProperty(t)) return priceChangeCache[t];
  const pc = await fetchPriceChange.call(this, t);
  priceChangeCache[t] = pc;
  return pc;
}

// ── 3) ETF sector-weighting fetch, cached so the per-mandate pass is free ──────
const etfWeightCache = {};
async function getEtfSectorRows(ticker){
  const t = String(ticker || '').toUpperCase().trim();
  if (etfWeightCache.hasOwnProperty(t)) return etfWeightCache[t];
  let rows = [];
  try {
    const url = 'https://financialmodelingprep.com/stable/etf/sector-weightings?symbol='
      + encodeURIComponent(t) + '&apikey=' + FMP_KEY;
    const resp = await this.helpers.httpRequest({ url: url, method: 'GET', json: true });
    if (Array.isArray(resp)) rows = resp;
  } catch (e) { rows = []; }
  etfWeightCache[t] = rows;
  return rows;
}

// ── 4) the exposure computation, as a FUNCTION so it runs per book ─────────────
// symbols: which tickers are in this book. weightOf(sym): that book's own weight
// for the symbol (percent scale is irrelevant, only relative size matters).
async function computeExposure(symbols, weightOf){
  const sectorTotals = {};
  const contribRaw = {};
  const etfsResolved = [];
  const etfsMissing = [];
  let droppedWeight = 0;

  function addSector(sec, amt, symbol){
    const s = normSector(sec);
    if (!s) return;
    sectorTotals[s] = (sectorTotals[s] || 0) + amt;
    if (!contribRaw[s]) contribRaw[s] = {};
    contribRaw[s][symbol] = (contribRaw[s][symbol] || 0) + amt;
  }

  for (const sym of symbols){
    const t = String(sym || '').toUpperCase().trim();
    const w = weightOf(t);
    if (!isFinite(w) || w <= 0) continue;
    const prof = profByT[t];
    const isEtf = prof && prof.isEtf === true;
    if (isEtf){
      const rows = await getEtfSectorRows.call(this, t);
      if (rows.length > 0){
        let denom = 0; const clean = [];
        for (const r of rows){
          const secName = r.sector; const wp = parseFloat(r.weightPercentage);
          if (!secName || !isFinite(wp)) continue;
          if (EXCLUDE_SECTORS[secName]) continue;
          clean.push({ sector: secName, wp: wp }); denom += wp;
        }
        if (denom > 0){
          for (const c of clean) addSector(c.sector, w * (c.wp / denom), t);
          etfsResolved.push(t);
        } else { droppedWeight += w; etfsMissing.push(t); }
      } else { droppedWeight += w; etfsMissing.push(t); }
    } else {
      addSector(prof && prof.sector ? prof.sector : 'Unclassified', w, t);
    }
  }

  function moveFor(sec){
    const sy = SECTOR_TO_SPDR[sec];
    if (sy && spdr[sy] && typeof spdr[sy].changePercent === 'number'){
      return Math.round(spdr[sy].changePercent * 100) / 100;
    }
    return null;
  }

  let fullRows = Object.keys(sectorTotals).map(function(s){
    return { sector: s, pct: Math.round(sectorTotals[s] * 10) / 10, move: moveFor(s), spdr: SECTOR_TO_SPDR[s] || null };
  }).filter(function(r){ return r.pct > 0; })
    .sort(function(a, b){ return b.pct - a.pct; });

  for (const r of fullRows){
    if (r.spdr){
      const pc = await getPriceChange.call(this, r.spdr);
      r.perf = pc || Object.assign(emptyPerf(), { today: r.move });
      if (r.perf.today === null && r.move !== null) r.perf.today = r.move;
    } else {
      r.perf = Object.assign(emptyPerf(), { today: r.move });
    }
  }

  const grandTotal = fullRows.reduce(function(a, r){ return a + r.pct; }, 0);

  function hypoFor(field){
    let wsum = 0, contrib = 0;
    for (const r of fullRows){
      const v = r.perf ? r.perf[field] : null;
      if (v === null || !isFinite(r.pct)) continue;
      contrib += r.pct * v; wsum += r.pct;
    }
    return wsum > 0 ? Math.round((contrib / wsum) * 100) / 100 : null;
  }
  const hypo = {
    basis: 'current-weight hypothetical (static mix, excludes dropped ETFs)',
    coveragePct: Math.round(grandTotal * 10) / 10,
    today: hypoFor('today'), w1: hypoFor('w1'),
    m1: hypoFor('m1'), m3: hypoFor('m3'), m6: hypoFor('m6'),
    ytd: hypoFor('ytd'), y1: hypoFor('y1'), y3: hypoFor('y3'), y5: hypoFor('y5')
  };

  const contrib = {};
  Object.keys(contribRaw).forEach(function(s){
    contrib[s] = Object.keys(contribRaw[s]).map(function(sym){
      return { symbol: sym, w: Math.round(contribRaw[s][sym] * 100) / 100 };
    }).filter(function(c){ return c.w > 0.01; })
      .sort(function(a, b){ return b.w - a.w; });
  });

  const TOP_N = 7;
  const top = fullRows.slice(0, TOP_N).map(function(r){
    return { sector: r.sector, pct: r.pct, move: r.move, spdr: r.spdr, perf: r.perf };
  });
  const rest = fullRows.slice(TOP_N);
  const restPct = rest.reduce(function(a, r){ return a + r.pct; }, 0);
  if (restPct > 0) top.push({ sector: 'Other', pct: Math.round(restPct * 10) / 10, move: null, spdr: null, perf: null });

  return {
    display: top, full: fullRows, contrib: contrib, hypo: hypo,
    grandTotal: Math.round(grandTotal * 10) / 10,
    droppedWeightPct: Math.round(droppedWeight * 10) / 10,
    etfsResolved: etfsResolved, etfsMissing: etfsMissing
  };
}

// ── 5) COMBINED book, exactly as v5 saw it ─────────────────────────────────────
const combinedWeights = {};
quotes.forEach(function(q){
  combinedWeights[String(q.symbol || '').toUpperCase().trim()] = weightFor(q);
});
const combinedSymbols = quotes.map(function(q){ return String(q.symbol || '').toUpperCase().trim(); });
const combined = await computeExposure.call(this, combinedSymbols, function(t){ return combinedWeights[t] || 0; });

// ── 6) PER MANDATE, when live ──────────────────────────────────────────────────
const isMulti = !!(mandates && mandates.isMulti === true
  && Array.isArray(mandates.portfolios) && mandates.portfolios.length > 1
  && holdingsByMandate && holdingsWeightsByMandate);

let sectorExposureByMandate = null;
let sectorExposureFullByMandate = null;
let sectorContribByMandate = null;
let hypoBookReturnByMandate = null;
const mandateOf = {};   // SYMBOL -> [book names]

if (isMulti){
  sectorExposureByMandate = {};
  sectorExposureFullByMandate = {};
  sectorContribByMandate = {};
  hypoBookReturnByMandate = {};
  for (const p of mandates.portfolios){
    const syms = (holdingsByMandate[p.name] || []).map(function(t){ return String(t).toUpperCase().trim(); });
    const wmap = holdingsWeightsByMandate[p.name] || {};
    syms.forEach(function(t){
      if (!mandateOf[t]) mandateOf[t] = [];
      mandateOf[t].push(p.name);
    });
    // The per-mandate weight map arrives as decimals summing to 1 within the
    // book (0.25 = 25%). Normalize to percent scale so sleeve percentages read
    // as percentages, exactly like the combined path.
    let wsumM = 0;
    syms.forEach(function(t){ const w = parseFloat(wmap[t]); if (isFinite(w) && w > 0) wsumM += w; });
    const scaleM = wsumM > 0 ? (100 / wsumM) : 0;
    const r = await computeExposure.call(this, syms, function(t){
      const w = parseFloat(wmap[t]);
      return (isFinite(w) && scaleM > 0) ? w * scaleM : 0;
    });
    sectorExposureByMandate[p.name] = r.display;
    sectorExposureFullByMandate[p.name] = r.full;
    sectorContribByMandate[p.name] = r.contrib;
    hypoBookReturnByMandate[p.name] = Object.assign({ mandateWeightPct: p.weight }, r.hypo);
  }
}

// ── 7) holding-level trailing returns, with mandate tags ───────────────────────
const holdingsPerf = [];
for (const q of quotes){
  const t = String(q.symbol || '').toUpperCase().trim();
  const prof = profByT[t] || profByT[q.symbol];
  const isEtf = prof && prof.isEtf === true;
  const pc = await getPriceChange.call(this, t);
  let weightInMandate = null;
  if (isMulti && mandateOf[t] && mandateOf[t].length){
    const home = mandateOf[t][0];
    const w = parseFloat((holdingsWeightsByMandate[home] || {})[t]);
    weightInMandate = isFinite(w) ? Math.round(w * 10000) / 100 : null;  // as % of its book
  }
  holdingsPerf.push({
    symbol: t,
    isEtf: !!isEtf,
    sector: isEtf ? null : normSector(prof && prof.sector ? prof.sector : null),
    spdr: (!isEtf && prof && prof.sector) ? (SECTOR_TO_SPDR[normSector(prof.sector)] || null) : null,
    weightPct: weightFor(q),
    mandates: isMulti ? (mandateOf[t] || []) : null,
    weightInMandate: weightInMandate,
    perf: pc || emptyPerf()
  });
}

// ── 8) benchmarks: S&P 500 (VOO, backward compatible) + Nasdaq-100 (QQQ) ───────
let benchmarkPerf = null;
{
  const pc = await getPriceChange.call(this, 'VOO');
  if (pc) benchmarkPerf = Object.assign({ symbol: 'VOO', label: 'S&P 500' }, pc);
}
let benchmarkPerfQQQ = null;
{
  const pc = await getPriceChange.call(this, 'QQQ');
  if (pc) benchmarkPerfQQQ = Object.assign({ symbol: 'QQQ', label: 'Nasdaq-100' }, pc);
}
const benchmarks = { spx: benchmarkPerf, qqq: benchmarkPerfQQQ };

// ── 9) watchlist trailing returns (watchlist is NOT part of the portfolio) ─────
const watchlistPerf = [];
{
  let cands = [];
  const wl = root.Watchlist;
  if (Array.isArray(wl)) {
    const flat = (Array.isArray(wl[0]) ? wl[0] : wl);
    cands = flat.map(function(s){ return String(s).toUpperCase().trim(); });
  } else {
    cands = String(wl || '').split(/[,;\n]+/).map(function(s){ return s.trim().toUpperCase(); });
  }
  cands = cands.filter(function(s){ return /^[A-Z][A-Z.\-]{0,5}$/.test(s); });
  const seen = {};
  const held = {};
  quotes.forEach(function(q){ held[String(q.symbol || '').toUpperCase().trim()] = 1; });
  for (const t of cands.slice(0, 12)){
    if (seen[t] || held[t]) continue;
    seen[t] = 1;
    const pc = await getPriceChange.call(this, t);
    watchlistPerf.push({ symbol: t, perf: pc || emptyPerf() });
  }
}

// ── 10) pass everything through, append ────────────────────────────────────────
const output = Object.assign({}, root, {
  mandates: mandates,
  holdingsByMandate: holdingsByMandate,
  holdingsWeightsByMandate: holdingsWeightsByMandate,

  sectorExposure: combined.display,
  sectorExposureMeta: {
    basis: haveWeights ? 'Weighted' : 'Equal-Wt',
    grandTotal: combined.grandTotal,
    droppedWeightPct: combined.droppedWeightPct,
    etfsResolved: combined.etfsResolved,
    etfsMissing: combined.etfsMissing,
    note: 'Unresolvable ETFs excluded, not renormalized. grandTotal + droppedWeightPct is approximately 100.'
  },
  sectorExposureFull: combined.full,
  sectorContrib: combined.contrib,
  hypoBookReturn: combined.hypo,

  sectorExposureByMandate: sectorExposureByMandate,
  sectorExposureFullByMandate: sectorExposureFullByMandate,
  sectorContribByMandate: sectorContribByMandate,
  hypoBookReturnByMandate: hypoBookReturnByMandate,

  holdingsPerf: holdingsPerf,
  benchmarkPerf: benchmarkPerf,
  benchmarkPerfQQQ: benchmarkPerfQQQ,
  benchmarks: benchmarks,
  watchlistPerf: watchlistPerf,
  dataAsOf: new Date().toISOString()
});

return [{ json: output }];

