// ║  AGGREGATE SHEETS - v2                                                   ║
// ║  Full replacement for the Aggregate Sheets Code node.                    ║
// ║                                                                          ║
// ║  WHAT CHANGED vs v1                                                      ║
// ║   1. Reads Read Holdings 2 and builds the mandate structure. One book or ║
// ║      two, same code path. No second tab means isMulti false and the      ║
// ║      output is identical to v1.                                          ║
// ║   2. Weights normalize WITHIN each mandate, then blend by mandate weight ║
// ║      for the combined view. Never across the union.                      ║
// ║   3. Filters #VALUE! and other spreadsheet errors out of every ticker    ║
// ║      list. Those were reaching the FMP fetches as real symbols.          ║
// ║   4. Handles both column names: "Portfolio" and "Portfolio/Weight".      ║
// ║   5. No spread operators, no em dashes.                                  ║
// ╚══════════════════════════════════════════════════════════════════════════╝

// ── helpers ────────────────────────────────────────────────────────────
// Node names drift: "Read Holdings 2" vs "Read Holdings2" vs a trailing space.
// Every lookup tries a list of candidates and takes the first that resolves with
// rows. A missing node throws inside $() and is caught, so an absent tab and a
// misnamed node both degrade to empty rather than killing the run.
function safeRows(names){
  var list = (typeof names === 'string') ? [names] : names;
  for (var i = 0; i < list.length; i++){
    try {
      var rows = $(list[i]).all();
      if (rows && rows.length) return rows.map(function(r){ return r.json || {}; });
    } catch (e) { /* try the next candidate */ }
  }
  return [];
}

// Which candidate actually resolved, for the debug block at the bottom.
function whichNode(names){
  var list = (typeof names === 'string') ? [names] : names;
  for (var i = 0; i < list.length; i++){
    try { var r = $(list[i]).all(); if (r && r.length) return list[i] + ' (' + r.length + ' rows)'; }
    catch (e) { /* next */ }
  }
  return 'not found';
}

// Every node this workflow reads, with the spellings seen in the wild.
var NODE = {
  h1:    ['Read Holdings1', 'Read Holdings 1', 'Read Holdings', 'Read Holdings1 ', 'Holdings1'],
  h2:    ['Read Holdings2', 'Read Holdings 2', 'Read Holdings2 ', 'Read Holdings 2 ', 'Holdings2', 'Holdings 2'],
  watch: ['Read Watchlist', 'Read WatchList', 'Read Watchlist ', 'Watchlist'],
  earn:  ['Read Earnings', 'Read Earnings ', 'Earnings'],
  topic: ['Read Topics', 'Read Topics ', 'Topics'],
  people:['Read People', 'Read People ', 'People'],
  sit:   ['Read Situations', 'Read Situations ', 'Situations'],
  sens:  ['Read Sensitivity', 'Read Sensitivity ', 'Sensitivity'],
  cfg:   ['Read Config', 'Read Config ', 'Config'],
  mode:  ['Read Mode', 'Read Mode ', 'Mode'],
  pers:  ['Read Personalization', 'Read personalization', 'Read Personalisation', 'Personalization']
};

// Spreadsheet errors were reaching the API fetches as if they were tickers.
function isRealTicker(t){
  if (!t) return false;
  var s = String(t).toUpperCase().trim();
  if (!s.length || s.length > 6) return false;
  if (s.indexOf('#') === 0) return false;                 // #VALUE!, #REF!, #N/A
  if (s.indexOf('!') > -1 || s.indexOf(' ') > -1) return false;
  return /^[A-Z][A-Z.\-]{0,5}$/.test(s);
}
function cleanTickers(list){
  var out = [], seen = {};
  for (var i = 0; i < list.length; i++){
    var t = String(list[i] || '').toUpperCase().trim();
    if (!isRealTicker(t) || seen[t]) continue;
    seen[t] = 1; out.push(t);
  }
  return out;
}
function pick(obj, keys){
  for (var i = 0; i < keys.length; i++){
    if (obj[keys[i]] !== undefined && obj[keys[i]] !== null && String(obj[keys[i]]).trim() !== '') return obj[keys[i]];
  }
  return '';
}

// ── mandate name and weight from the Portfolio column ───────────────────
// Accepts "Roth IRA | 70", "House - 30", "Taxable, 40", or a bare name.
// The value lives in the first non-empty cell of the column; the rest are blank.
function readMandateCell(rows, fallbackName){
  var raw = '';
  for (var i = 0; i < rows.length; i++){
    var v = pick(rows[i], ['Portfolio', 'Portfolio/Weight', 'portfolio', 'Portfolio / Weight', 'Mandate']);
    if (String(v).trim()){ raw = String(v).trim(); break; }
  }
  if (!raw) return { name: fallbackName, weight: null };

  var m = raw.match(/^(.*?)[\s|,\-]+(\d+(?:\.\d+)?)\s*%?$/);
  if (m) return { name: m[1].trim() || fallbackName, weight: parseFloat(m[2]) };
  return { name: raw, weight: null };
}

// ── one mandate's holdings, weights normalized within itself ────────────
function buildMandate(nodeNames, fallbackName){
  var rows = safeRows(nodeNames);
  var tickers = [], weights = {}, sum = 0;

  for (var i = 0; i < rows.length; i++){
    var d = rows[i];
    var t = String(pick(d, ['Ticker','ticker'])).toUpperCase().trim();
    if (!isRealTicker(t)) continue;                       // also drops the totals row
    var w = parseFloat(pick(d, ['Amount','Weight','weight','amount']));
    if (!isFinite(w)) w = null;
    if (weights[t] !== undefined){                        // same name twice in one tab
      if (w !== null) weights[t] = (weights[t] || 0) + w;
      continue;
    }
    tickers.push(t);
    weights[t] = w;
    if (w !== null) sum += w;
  }

  // Normalize within THIS mandate so a book always sums to 1. Never across books.
  if (sum > 0 && Math.abs(sum - 1) > 0.005){
    for (var k in weights){ if (weights[k] !== null) weights[k] = weights[k] / sum; }
  }

  var meta = readMandateCell(rows, fallbackName);
  return { name: meta.name, declaredWeight: meta.weight, tickers: tickers, weights: weights };
}

// ── build both books ────────────────────────────────────────────────────
var m1 = buildMandate(NODE.h1, 'Portfolio 1');
var m2 = buildMandate(NODE.h2, 'Portfolio 2');

var books = [];
if (m1.tickers.length) books.push(m1);
if (m2.tickers.length) books.push(m2);
if (!books.length) books.push(m1);                        // degrade rather than throw

var isMulti = books.length > 1;

// Mandate weights: use the declared split when both are present and sane,
// otherwise fall back to an even split. Never guess a blend from returns.
var mw = [];
if (isMulti){
  var a = books[0].declaredWeight, b = books[1].declaredWeight;
  var tot = (a !== null && b !== null) ? (a + b) : 0;
  if (tot > 0 && Math.abs(tot - 100) <= 0.5){ mw = [a, b]; }
  else if (tot > 0){ mw = [ +(a / tot * 100).toFixed(2), +(b / tot * 100).toFixed(2) ]; }
  else { mw = [50, 50]; }
} else {
  mw = [100];
}

var mandates = {
  isMulti: isMulti,
  weightSource: isMulti
    ? ((books[0].declaredWeight !== null && books[1].declaredWeight !== null) ? 'sheet' : 'default 50/50')
    : 'single portfolio',
  portfolios: books.map(function(bk, i){
    return { name: bk.name, weight: mw[i], holdingsCount: bk.tickers.length };
  })
};
// Heaviest book first, so the engine and the agent never have to decide.
if (isMulti && mandates.portfolios[1].weight > mandates.portfolios[0].weight){
  mandates.portfolios.reverse();
  books.reverse();
  mw.reverse();
}

// ── the union that every per-ticker fetch consumes ──────────────────────
var holdings = [];
books.forEach(function(bk){ holdings = holdings.concat(bk.tickers); });
holdings = cleanTickers(holdings);

// Per-mandate maps for the prompt and the engine
var holdingsByMandate = {};
var holdingsWeightsByMandate = {};
books.forEach(function(bk, i){
  holdingsByMandate[mandates.portfolios[i].name] = bk.tickers.slice();
  holdingsWeightsByMandate[mandates.portfolios[i].name] = bk.weights;
});

// Combined weights: each position's weight inside its book, scaled by that
// book's share. Single portfolio leaves these byte-identical to v1.
var holdingsWeights = {};
books.forEach(function(bk, i){
  var share = (mw[i] || 100) / 100;
  for (var t in bk.weights){
    var w = bk.weights[t];
    var add = (w === null) ? null : w * share;
    if (holdingsWeights[t] === undefined || holdingsWeights[t] === null) holdingsWeights[t] = add;
    else if (add !== null) holdingsWeights[t] = holdingsWeights[t] + add;   // held in both books
  }
});

// ── the rest of the sheets, unchanged in behaviour ──────────────────────
var watchlist = cleanTickers(safeRows(NODE.watch).map(function(d){
  return pick(d, ['Ticker','ticker']);
}));

var earningsTickers = cleanTickers(safeRows(NODE.earn).map(function(d){
  return pick(d, ['Ticker','ticker']);
}));

var topics = safeRows(NODE.topic).map(function(d){
  return String(pick(d, ['Topic','topic'])).trim();
}).filter(function(t){ return t.length > 0; });

var people = safeRows(NODE.people).map(function(d){
  var name = String(pick(d, ['Name','name','Name '])).trim();
  var role = String(pick(d, ['Role','role','Role '])).trim();
  return name + (role ? ' (' + role + ')' : '');
}).filter(function(t){ return t.trim().length > 0; });

var situations = safeRows(NODE.sit).map(function(d){
  return String(pick(d, ['Situation','situation'])).trim();
}).filter(function(t){ return t.length > 0; });

var sensitivity = safeRows(NODE.sens).map(function(d){
  var nm = String(pick(d, ['Situation','situation','Situation '])).trim();
  var ds = String(pick(d, ['Description','description','Description '])).trim();
  var cr = pick(d, ['Concern Level (1-10)','Concern Level (1-10) ','Concern Level','concern']);
  var c = parseInt(cr, 10); if (!isFinite(c)) c = 5;
  return { name: nm, description: ds, concern: c };
}).filter(function(s){ return s.name.length > 0; });

// no em dash, this string used to inject one into the payload
var sensitivityFormatted = sensitivity.map(function(s){
  return '\u2022 ' + s.name + ' (Concern: ' + s.concern + '/10): ' + s.description;
}).join('\n');

var allTickers = cleanTickers(holdings.concat(watchlist).concat(earningsTickers));

// ── config ──────────────────────────────────────────────────────────────
var configObj = {};
safeRows(NODE.cfg).forEach(function(d){
  var f = String(pick(d, ['Field','field'])).trim();
  var v = pick(d, ['Value','value']);
  if (f) configObj[f] = v;
});

// ── mode, context, temperature ──────────────────────────────────────────
var advisorMode = 'hybrid', advisorContext = '', temperature = 7;
var modeRows = safeRows(NODE.mode);
for (var j = 0; j < modeRows.length; j++){
  var md = modeRows[j];
  var rawMode = String(pick(md, ['Mode','Mode ','mode'])).trim().toLowerCase();
  if (!rawMode.length) continue;
  if (rawMode === 'advisor') advisorMode = 'advisor';
  else if (rawMode === 'analyst') advisorMode = 'analyst';
  else advisorMode = 'hybrid';
  advisorContext = String(pick(md, ['Context','Context ','context'])).trim();
  var pt = parseInt(pick(md, ['Temperature','Temperature ','temperature','Temp','temp']), 10);
  temperature = isFinite(pt) ? Math.max(1, Math.min(10, pt)) : 7;
  break;
}
var effectiveTemperature = (advisorMode === 'advisor') ? Math.min(temperature, 6) : temperature;

// ── personalization, carried in the payload as well as read by name ─────
var personalization = safeRows(NODE.pers).map(function(d){
  return pick(d, ['Personalization','personalization','PERSONALIZATION']);
}).filter(function(s){ return String(s).trim(); }).join('\n\n');

// ── which nodes resolved, so a rename never fails silently again ────────
var _nodes = {};
for (var nk in NODE){ _nodes[nk] = whichNode(NODE[nk]); }

return [{ json: {
  _nodes: _nodes,
  Ticker: holdings,
  holdingsWeights: holdingsWeights,

  // multi-portfolio, all dormant and harmless when there is one book
  mandates: mandates,
  holdingsByMandate: holdingsByMandate,
  holdingsWeightsByMandate: holdingsWeightsByMandate,

  Watchlist: watchlist,
  EarningsTickers: earningsTickers,
  AllTickers: allTickers,
  Topics: topics,
  People: people,
  Situations: situations,
  Sensitivity: sensitivity,
  sensitivityFormatted: sensitivityFormatted,
  personalization: personalization,

  advisorName: configObj.advisor_name || 'Advisor',
  firm: configObj.firm || '',
  email: configObj.email || '',
  sheetUrl: configObj.sheet_url || '',

  ticker_count: holdings.length,
  watchlist_count: watchlist.length,
  earnings_ticker_count: earningsTickers.length,

  Mode: advisorMode,
  Context: advisorContext,
  Temperature: effectiveTemperature,
  TemperatureRaw: temperature
}}];

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  FMP STOCK NEWS — holdings-specific news for the current template's tickers    ║
// ║  Pulls the ticker list from the root object (no hard-coded symbols), fetches   ║
// ║  ticker-filtered news + press releases from FMP, appends stockNews. Pass-thru. ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

const FMP_KEY = 'REDACTED_FMP_KEY';

const MAX_ITEMS_PER_CALL = 50;   // cap news items pulled
const PER_TICKER_KEEP     = 3;   // keep top N most-recent per ticker in the digest
const INCLUDE_PRESS_RELEASES = true;

const root = $input.first().json;

// ── 1) Resolve tickers from the template (dynamic — never hard-coded) ───────────
function flat(a) { return Array.isArray(a) ? a.flat(Infinity) : []; }
const fromArrays = [
  ...flat(root.AllTickers),
  ...flat(root.Ticker),
  ...flat(root.EarningsTickers)
];
const fromQuotes = Array.isArray(root.quotes)
  ? root.quotes.map(q => q && q.symbol)
  : [];

// Only real single stocks are worth ticker-news (ETFs rarely have company news)
const profByT = (root.profiles && root.profiles.profilesByTicker) || {};
function isEtf(t) { const p = profByT[t]; return !!(p && p.isEtf === true); }

const tickers = Array.from(new Set(
  [...fromArrays, ...fromQuotes]
    .map(s => String(s || '').toUpperCase().trim())
    .filter(Boolean)
)).filter(t => !isEtf(t));   // drop ETFs; comment this line out to include them

// ── 2) Fetch ticker-filtered stock news (one batched call) ──────────────────────
async function getJson(url) {
  try {
    const resp = await this.helpers.httpRequest({ url, method: 'GET', json: true });
    return Array.isArray(resp) ? resp : [];
  } catch (e) { return []; }
}

let newsRaw = [];
if (tickers.length) {
  const url = 'https://financialmodelingprep.com/stable/news/stock?symbols='
    + encodeURIComponent(tickers.join(','))
    + '&limit=' + MAX_ITEMS_PER_CALL
    + '&apikey=' + FMP_KEY;
  newsRaw = await getJson.call(this, url);
}

// ── 3) Optional: press releases (primary-source disclosures) ────────────────────
let pressRaw = [];
if (INCLUDE_PRESS_RELEASES && tickers.length) {
  const purl = 'https://financialmodelingprep.com/stable/news/press-releases?symbols='
    + encodeURIComponent(tickers.join(','))
    + '&limit=' + MAX_ITEMS_PER_CALL
    + '&apikey=' + FMP_KEY;
  pressRaw = await getJson.call(this, purl);
}

// ── 4) Normalize + keep top N most-recent per ticker ────────────────────────────
function norm(item, kind) {
  const sym = String(item.symbol || item.ticker || '').toUpperCase().trim();
  return {
    symbol: sym,
    kind: kind,                                   // 'news' | 'press'
    title: item.title || item.headline || '',
    text: (item.text || item.snippet || '').slice(0, 400),
    site: item.site || item.publisher || item.source || '',
    url: item.url || item.link || '',
    published: item.publishedDate || item.date || item.published || '',
    sentiment: item.sentiment || null            // FMP sometimes tags this
  };
}

const all = [
  ...newsRaw.map(i => norm(i, 'news')),
  ...pressRaw.map(i => norm(i, 'press'))
].filter(i => i.symbol && (i.title || i.text));

// sort newest first
all.sort((a, b) => String(b.published).localeCompare(String(a.published)));

// group by ticker, keep top N each
const byTicker = {};
for (const it of all) {
  if (!byTicker[it.symbol]) byTicker[it.symbol] = [];
  if (byTicker[it.symbol].length < PER_TICKER_KEEP) byTicker[it.symbol].push(it);
}

// flat digest for the agent (already trimmed)
const digest = Object.keys(byTicker).flatMap(t => byTicker[t]);

// compact text summary the system prompt can read directly
const summaryLines = Object.keys(byTicker).map(t => {
  const items = byTicker[t];
  const heads = items.map(i => '• ' + i.title + (i.site ? ' (' + i.site + ')' : '')).join('\n');
  return t + ':\n' + heads;
});

// ── 5) Append + pass everything through ─────────────────────────────────────────
const stockNews = {
  byTicker: byTicker,             // { AMZN: [ {title,url,...}, ... ], ... }
  digest: digest,                 // flat, newest-first, trimmed
  summary: summaryLines.join('\n\n'),
  _meta: {
    tickersQueried: tickers,
    tickerCount: tickers.length,
    itemsReturned: all.length,
    pressIncluded: INCLUDE_PRESS_RELEASES,
    fetchedAt: new Date().toISOString()
  }
};

const output = Object.assign({}, root, { stockNews: stockNews });
return [{ json: output }];

// ─────────────────────────────────────────────────────────────
//  RSS AGGREGATE v3 - pull by node name · single emission · tiering
//  Mode: Run Once for All Items
//
//  v2 FIXED the right thing: $input.all() only sees ONE feed per run, so
//  pulling by node name is correct and stays.
//
//  v3 FIXES WHAT WAS LEFT: n8n executes this node ONCE PER INBOUND
//  CONNECTION, so with 13 RSS nodes wired in it runs thirteen times. On run 1
//  only one feed has executed and every other $('RSS ...') throws NODE NOT
//  FOUND, which is exactly what the payload reported: 61 items collected, all
//  from one publisher, eleven feeds missing. The node was not broken, it was
//  answering twelve times too early and something downstream read an early
//  answer. v3 emits NOTHING until every feed has resolved, so downstream sees
//  one complete payload instead of thirteen partial ones. No rewiring needed.
//
//  Also new in v3:
//    · Relevance filter. A fifteen-item macro feed spent slots on Dolly
//      Parton's catalog, the college enrollment crisis and the fall of Leon
//      Black while the Warsh story that drove the entire book sat at 14 of 15.
//    · Source tiering, so the prompt can demand a tier 1 or 2 outlet in the
//      Must-Read slots instead of taking whatever is newest.
//    · Opinion pieces labelled, not dropped: they carry a view, not a fact.
// ─────────────────────────────────────────────────────────────

const MAX_ITEMS       = 200;   // total handed to the agent
const MAX_PER_SOURCE  = 15;    // no publisher can dominate
const MAX_AGE_HOURS   = 72;

// Every RSS node feeding this one. EDIT THESE TO MATCH YOUR CANVAS EXACTLY.
const NODES = [
  'RSS WSJ Markets',
  'RSS WSJ Economy',
  'RSS WSJ Tech',
  'RSS FedFeeds',
  'RSS Oilprice1',
  'RSS FedRes1',
  'RSS Seeking Alpha',
  'RSS DOW/WSJ1',
  'RSS CNBC1',
  'RSS MARKETWATCH',
  'RSS FT',
  'RSS Googlenews',
];

// Content farms and non-finance junk. Dropped outright.
const BLOCKED_DOMAINS = [
  'defenseworld.net','marketbeat.com','insidermonkey.com','zacks.com',
  'simplywall.st','247wallst.com','theacquirersmultiple.com','etfdailynews.com',
  'facebook.com','aleteia.org','nobelprize.org','promarket.org',
];

// Auto-generated 13F filing spam.
const BLOCKED_TITLE_PATTERNS = [
  /(Purchases|Sells|Acquires|Trims|Boosts|Lowers|Raises|Buys)\s+[\d,]+\s+Shares/i,
  /Stake (Reduced|Increased|Boosted|Trimmed|Lifted)\s+by/i,
  /Position (Reduced|Increased|Boosted|Lifted|Trimmed)\s+by/i,
  /Has \$[\d.]+ (Million|Billion)\s+(Stock\s+)?(Holdings|Position)\s+in/i,
  /Shares (Sold|Bought|Acquired) by/i,
];

// Source tiers. 1 = primary or wire, 2 = major financial press, 3 = everything
// else. Carried through to the agent so the prompt can require a tier 1 or 2
// source in the Must-Read slots rather than reaching for an aggregator.
const TIER = {
  'reuters.com':1,'apnews.com':1,'federalreserve.gov':1,'sec.gov':1,'bls.gov':1,
  'treasury.gov':1,'bea.gov':1,'ecb.europa.eu':1,'imf.org':1,'stlouisfed.org':1,
  'wsj.com':2,'ft.com':2,'bloomberg.com':2,'economist.com':2,'cnbc.com':2,
  'marketwatch.com':2,'barrons.com':2,'nytimes.com':2,'washingtonpost.com':2,
  'oilprice.com':2,'calculatedriskblog.com':2,'axios.com':2,'politico.com':2,
  'businesswire.com':1,'globenewswire.com':1,'prnewswire.com':1,
};

// Deliberately conservative. Drops the obviously off-topic and keeps anything
// ambiguous, because a wrongly dropped rate story costs far more than a
// wasted slot.
const NOISE_PATTERNS = [
  /\b(dolly parton|taylor swift|kardashian|celebrity|royal family)\b/i,
  /\b(recipe|restaurant review|wine tasting|travel guide|vacation)\b/i,
  /\b(nfl|nba|mlb|nhl|premier league|olympics|super bowl|world cup)\b/i,
  /\bhoroscope|astrology|obituar/i,
  /\b(gift guide|best gifts|deals? of the day|black friday)\b/i,
  /\bcollege (enrollment|admissions)\b/i,
  /\b(divorce|custody battle|family feud)\b/i,
  // Personal-finance advice columns. First-person money-diary headlines are a
  // large share of the MarketWatch and DOW feeds and they displace rate and
  // earnings coverage in a book brief. Caught a live run's "I'm single, 74,
  // with $10 million burning a hole in my pocket. What should I do?".
  /^['"\u2018\u201c]?I(?:'m| am|'ve| have)\b/i,
  /\bmy (husband|wife|father|mother|parents|son|daughter|in-laws|boyfriend|girlfriend)\b/i,
  /\b(what should I do|should I|can I afford|am I being unreasonable)\b/i,
  /\b(money diary|advice column|dear (moneyist|penny|quentin))\b/i,
  // Human-interest disaster coverage with no market channel. Deliberately
  // requires the absence of any market term so a genuine supply-shock story
  // (a refinery fire, a port closure) still survives.
  /\b(death toll|rescuers|mourners|funeral|missing (hikers|climbers)|glacier collapse)\b/i,
];

// A story only counts as noise if it ALSO carries no market vocabulary. This
// keeps a disaster that moves a commodity, and drops the one that does not.
const MARKET_TERMS = /\b(stock|share|equit|bond|yield|treasur|fed|fomc|rate|inflation|cpi|ppi|earnings|revenue|guidance|merger|acquisition|ipo|oil|crude|opec|gold|dollar|index|s&p|nasdaq|dow|etf|credit|spread|tariff|sanction|export|supply chain|chip|semiconductor|bank|lending|deficit|treasury)\b/i;

const tierOf = (host) => {
  if (!host) return 3;
  if (TIER[host]) return TIER[host];
  for (const k of Object.keys(TIER)) if (host.endsWith('.' + k)) return TIER[k];
  return 3;
};

const isOpinion = (title) =>
  /^\s*(opinion|editorial|commentary|op-ed)\b/i.test(title) ||
  /\|\s*(opinion|commentary)\b/i.test(title);

const strip = (s) => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'")
  .replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ')
  .replace(/\s+/g,' ')
  .trim();

// n8n's Code sandbox does not reliably expose the URL constructor. When it is
// absent, new URL() throws, the catch returns an empty host, and EVERY item
// silently scores tier 3 while "source" falls back to the node name. A live
// run showed exactly that: 118 items, all tier 3, sources reading "RSS CNBC1".
// Regex extraction has no such dependency.
const hostOf = (url) => {
  const m = String(url || '').match(/^https?:\/\/([^/?#]+)/i);
  return m ? m[1].replace(/^www\./i, '').replace(/:\d+$/, '').toLowerCase() : '';
};

// Publication names for citation. The prompt requires a named publication and
// treats a bare domain as an invented source, so the friendly name travels
// with the item rather than being guessed at write time.
const PUBLISHER = {
  'wsj.com':'The Wall Street Journal','ft.com':'Financial Times','cnbc.com':'CNBC',
  'marketwatch.com':'MarketWatch','barrons.com':"Barron's",'bloomberg.com':'Bloomberg',
  'reuters.com':'Reuters','apnews.com':'The Associated Press','nytimes.com':'The New York Times',
  'washingtonpost.com':'The Washington Post','economist.com':'The Economist',
  'federalreserve.gov':'The Federal Reserve','stlouisfed.org':'The St. Louis Fed',
  'bls.gov':'The Bureau of Labor Statistics','treasury.gov':'The U.S. Treasury',
  'sec.gov':'The SEC','bea.gov':'The Bureau of Economic Analysis',
  'oilprice.com':'OilPrice','seekingalpha.com':'Seeking Alpha','fool.com':'The Motley Fool',
  'calculatedriskblog.com':'Calculated Risk','axios.com':'Axios','politico.com':'Politico',
  'businesswire.com':'Business Wire','globenewswire.com':'GlobeNewswire','prnewswire.com':'PR Newswire',
};
const publisherOf = (host) => {
  if (!host) return '';
  if (PUBLISHER[host]) return PUBLISHER[host];
  for (const k of Object.keys(PUBLISHER)) if (host.endsWith('.' + k)) return PUBLISHER[k];
  return host;
};

const cutoff = MAX_AGE_HOURS > 0 ? Date.now() - MAX_AGE_HOURS * 3600 * 1000 : 0;

// ── 1. Gather from every feed node ───────────────────────────
const collected = [];
const diag = { perNode: {}, dropped: { age: 0, blocked: 0, noise: 0, dupe: 0, capped: 0 } };

for (const name of NODES) {
  let items = [];
  try { items = $(name).all() || []; }
  catch (e) { diag.perNode[name] = 'NODE NOT FOUND'; continue; }

  diag.perNode[name] = items.length;

  for (const it of items) {
    const j = it.json || {};
    const title = strip(j.title);
    if (!title) continue;

    const link = String(j.link || j.guid || '');
    const host = hostOf(link);
    const summary = strip(j.contentSnippet || j.content || j.summary || '').slice(0, 400);
    const iso = j.isoDate || j.pubDate || null;
    const ts = iso ? Date.parse(iso) : NaN;

    collected.push({
      title, link, host, summary, publishedAt: iso, ts, feed: name,
      tier: tierOf(host),
      publisher: publisherOf(host),
      opinion: isOpinion(title),
      ageHours: Number.isFinite(ts) ? Math.round(((Date.now() - ts) / 3600000) * 10) / 10 : null,
    });
  }
}

// ── 1b. EMIT ONCE, AND ONLY WHEN EVERY FEED HAS RESOLVED ─────
// This is the v3 fix. Runs before the last one see a partial world, so they
// emit no items at all and downstream receives exactly one complete payload.
// The escape hatch matters: a genuinely dead feed never resolves, so once the
// node has run at least as many times as there are feeds, it ships what it
// has rather than shipping nothing.
const missingNodes = NODES.filter(n => diag.perNode[n] === 'NODE NOT FOUND');
const runIdx = (typeof $runIndex === 'number') ? $runIndex : 0;
if (missingNodes.length > 0 && runIdx < (NODES.length - 1)) {
  return [];
}

// ── 2. Filter ────────────────────────────────────────────────
const filtered = collected.filter((a) => {
  if (cutoff && Number.isFinite(a.ts) && a.ts < cutoff) { diag.dropped.age++; return false; }
  if (BLOCKED_DOMAINS.some(d => a.host.endsWith(d))) { diag.dropped.blocked++; return false; }
  if (BLOCKED_TITLE_PATTERNS.some(re => re.test(a.title))) { diag.dropped.blocked++; return false; }
  const blob = a.title + ' ' + a.summary.slice(0, 200);
  if (NOISE_PATTERNS.some(re => re.test(blob)) && !MARKET_TERMS.test(blob)) { diag.dropped.noise++; return false; }
  return true;
});

// ── 3. Dedup on normalized title ─────────────────────────────
const seen = new Set();
const deduped = [];
for (const a of filtered) {
  const key = a.title.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().slice(0, 90);
  if (seen.has(key)) { diag.dropped.dupe++; continue; }
  seen.add(key);
  deduped.push(a);
}

// ── 4. Newest first, then round-robin by source so no publisher dominates
deduped.sort((a, b) => {
  const d = (Number.isFinite(b.ts) ? b.ts : 0) - (Number.isFinite(a.ts) ? a.ts : 0);
  return d !== 0 ? d : a.tier - b.tier;   // same age: better source first
});

const buckets = new Map();
for (const a of deduped) {
  const k = a.host || a.feed;
  if (!buckets.has(k)) buckets.set(k, []);
  buckets.get(k).push(a);
}

const out = [];
let round = 0;
while (out.length < MAX_ITEMS && round < MAX_PER_SOURCE) {
  let added = false;
  for (const [, list] of buckets) {
    if (list[round]) {
      out.push(list[round]);
      added = true;
      if (out.length >= MAX_ITEMS) break;
    }
  }
  if (!added) break;
  round++;
}
diag.dropped.capped = deduped.length - out.length;

out.sort((a, b) => (Number.isFinite(b.ts) ? b.ts : 0) - (Number.isFinite(a.ts) ? a.ts : 0));

// ── 5. Emit ──────────────────────────────────────────────────
const sources = {};
for (const a of out) sources[a.host || a.feed] = (sources[a.host || a.feed] || 0) + 1;

return [{
  json: {
    newsContext: out.map(a => ({
      source: a.host || a.feed,
      title: a.title,
      url: a.link,
      publishedAt: a.publishedAt,
      summary: a.summary,
      feed: a.feed,
      publisher: a.publisher,
      tier: a.tier,
      opinion: a.opinion,
      ageHours: a.ageHours,
    })),
    newsMeta: {
      count: out.length,
      collected: collected.length,
      sources,
      tiers: out.reduce((m, a) => { m[a.tier] = (m[a.tier] || 0) + 1; return m; }, {}),
      feedsResolved: NODES.length - missingNodes.length,
      feedsMissing: missingNodes,
      emittedOnRun: runIdx,
      diagnostics: diag,
      generatedAt: new Date().toISOString(),
    },
  }
}];

// ─────────────────────────────────────────────────────────────
//  FMP VALUATION v5 — LEVELS + TRENDS + SECTOR-RELATIVE
//  v5 fix: Process Profiles emits profiles.sectorMapping, a flat
//  { TICKER: "Sector" } map. v4 looked for profilesByTicker with a
//  nested .sector, found nothing, and silently skipped every
//  sector comparison. vsSector now fires.
//  Mode: Run Once for All Items
// ─────────────────────────────────────────────────────────────

const API_KEY = 'REDACTED_FMP_KEY';
const BASE = 'https://financialmodelingprep.com/stable';

const cfg = $('O aggregate').first().json;
const holdings  = (cfg.Ticker    || []).flat().filter(Boolean);
const watchlist = (cfg.Watchlist || []).flat().filter(Boolean);
const tickers = [...new Set([...holdings, ...watchlist].map(s => String(s).toUpperCase()))];

const errors = [];
const n2  = (v) => (v === null || v === undefined || v === '' || isNaN(v)) ? null : +Number(v).toFixed(2);
const pc1 = (v) => (v === null || v === undefined || v === '' || isNaN(v)) ? null : +(Number(v) * 100).toFixed(1);
const first = (o, ...keys) => { for (const k of keys) if (o[k] !== undefined && o[k] !== null && o[k] !== '') return o[k]; return null; };

const get = async (path, qs, label) => {
  try {
    const raw = await this.helpers.httpRequest({
      method: 'GET', url: `${BASE}/${path}?${qs}&apikey=${API_KEY}`, json: true, timeout: 12000,
    });
    if (raw && (raw['Error Message'] || raw.message)) {
      errors.push(`${label}: ${String(raw['Error Message'] || raw.message).slice(0, 110)}`);
      return null;
    }
    return raw;
  } catch (e) {
    errors.push(`${label}: ${String(e.message).slice(0, 110)}`);
    return null;
  }
};

// ── Trend maths. Quarters arrive newest-first. ───────────────
const analyzeSeries = (vals) => {
  const s = vals.filter(v => v !== null && v !== undefined && !isNaN(v)).map(Number);
  if (s.length < 2) return null;

  const now = s[0];
  const prevQ = s[1] ?? null;
  const yearAgo = s[4] ?? s[s.length - 1];

  let run = 0;
  for (let i = 0; i < Math.min(4, s.length - 1); i++) { if (s[i] > s[i + 1]) run++; else break; }
  let declineRun = 0;
  for (let i = 0; i < Math.min(4, s.length - 1); i++) { if (s[i] < s[i + 1]) declineRun++; else break; }

  let direction = 'mixed';
  if (run >= 3) direction = `expanding for ${run} straight quarters`;
  else if (run === 2) direction = 'expanding two quarters';
  else if (declineRun >= 3) direction = `contracting for ${declineRun} straight quarters`;
  else if (declineRun === 2) direction = 'contracting two quarters';

  let flip = null;
  if (prevQ !== null) {
    if (prevQ < 0 && now >= 0) flip = 'turned positive this quarter';
    else if (prevQ >= 0 && now < 0) flip = 'turned negative this quarter';
  }

  let breakeven = null;
  if (now < 0 && prevQ !== null && now > prevQ) {
    const perQ = now - prevQ;
    if (perQ > 0) {
      const q = Math.ceil(Math.abs(now) / perQ);
      if (q <= 8) breakeven = `on the current pace, roughly ${q} quarter${q === 1 ? '' : 's'} to breakeven`;
    }
  }

  return {
    now: pc1(now),
    qoq: prevQ !== null ? +((now - prevQ) * 100).toFixed(1) : null,
    yoy: yearAgo !== null ? +((now - yearAgo) * 100).toFixed(1) : null,
    direction, flip, breakeven,
    quarters: s.length,
  };
};

// ── Per-ticker pull ──────────────────────────────────────────
const pull = async (ticker) => {
  const [ttm, keyM, quarters] = await Promise.all([
    get('ratios-ttm',      `symbol=${encodeURIComponent(ticker)}`, `${ticker} ratios-ttm`),
    get('key-metrics-ttm', `symbol=${encodeURIComponent(ticker)}`, `${ticker} key-metrics-ttm`),
    get('ratios',          `symbol=${encodeURIComponent(ticker)}&period=quarter&limit=8`, `${ticker} ratios-quarterly`),
  ]);

  const t = (Array.isArray(ttm) ? ttm[0] : ttm) || {};
  const k = (Array.isArray(keyM) ? keyM[0] : keyM) || {};
  const m = { ...k, ...t };

  const pe = n2(first(m, 'priceToEarningsRatioTTM', 'peRatioTTM', 'priceEarningsRatioTTM'));
  const gmNow = first(m, 'grossProfitMarginTTM');
  if (pe === null && gmNow === null) return null;   // ETF / crypto proxy

  const qs = Array.isArray(quarters) ? quarters : [];
  const seriesOf = (field) => qs.map(r => r?.[field]).filter(v => v !== undefined);

  const trends = qs.length >= 2 ? {
    gross: analyzeSeries(seriesOf('grossProfitMargin')),
    oper:  analyzeSeries(seriesOf('operatingProfitMargin')),
    net:   analyzeSeries(seriesOf('netProfitMargin')),
    latestQuarter: qs[0]?.period && qs[0]?.fiscalYear ? `${qs[0].period} ${qs[0].fiscalYear}` : null,
  } : null;

  return {
    ticker,
    pe,
    ps:          n2(first(m, 'priceToSalesRatioTTM')),
    pb:          n2(first(m, 'priceToBookRatioTTM')),
    evEbitda:    n2(first(m, 'enterpriseValueMultipleTTM', 'evToEBITDATTM', 'evToEbitdaTTM')),
    grossMargin: pc1(gmNow),
    operMargin:  pc1(first(m, 'operatingProfitMarginTTM')),
    netMargin:   pc1(first(m, 'netProfitMarginTTM')),
    roe:         pc1(first(m, 'returnOnEquityTTM')),
    trends,
  };
};

const sectorPESnapshot = async () => {
  const day = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  const raw = await get('sector-pe-snapshot', `date=${day}&exchange=NASDAQ`, 'sector-pe');
  const rows = Array.isArray(raw) ? raw : [];
  const map = {};
  for (const r of rows) if (r && r.sector) map[r.sector] = n2(r.pe);
  return map;
};

const [rows, sectorPE] = await Promise.all([
  Promise.all(tickers.map(t => pull(t))),
  sectorPESnapshot(),
]);

const valuation = rows.filter(Boolean);

// ── Sector-relative margin trend ─────────────────────────────
// v5 FIX: the map is profiles.sectorMapping, flat { TICKER: "Sector" }.
// Peer set is THIS BOOK, not the market: "your semis are all expanding
// while this one contracts" is the read that matters to this reader.
let sectorMap = {};
try {
  const p = $('Process Profiles').first().json;
  sectorMap = p?.profiles?.sectorMapping || p?.sectorMapping || {};
} catch (e) { errors.push('Process Profiles not readable: sector comparison skipped'); }

const bySector = {};
for (const v of valuation) {
  const sec = sectorMap[v.ticker];
  const q = v.trends?.oper?.qoq;
  if (!sec || q === null || q === undefined) continue;
  (bySector[sec] = bySector[sec] || []).push({ ticker: v.ticker, qoq: q });
}

const median = (arr) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return +(s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2).toFixed(1);
};

const sectorMarginTrend = {};
for (const [sec, list] of Object.entries(bySector)) {
  if (list.length < 2) continue;   // one name is not a peer group
  sectorMarginTrend[sec] = { medianOperQoQ: median(list.map(x => x.qoq)), n: list.length };
}

// Flag a name moving opposite its own sector peers.
for (const v of valuation) {
  const sec = sectorMap[v.ticker];
  const st = sec ? sectorMarginTrend[sec] : null;
  if (!st || !v.trends?.oper || v.trends.oper.qoq === null) continue;
  const mine = v.trends.oper.qoq;
  const theirs = st.medianOperQoQ;
  if (mine < 0 && theirs > 0.2) {
    v.trends.vsSector = `operating margin contracting ${Math.abs(mine).toFixed(1)} points while ${sec} peers in this book expanded a median ${theirs.toFixed(1)}`;
  } else if (mine > 0.2 && theirs < 0) {
    v.trends.vsSector = `operating margin expanding ${mine.toFixed(1)} points while ${sec} peers in this book contracted a median ${Math.abs(theirs).toFixed(1)}`;
  }
}

return [{
  json: {
    valuation,
    sectorPE,
    sectorMarginTrend,
    valuationMeta: {
      requested: tickers.length,
      returned: valuation.length,
      withTrends: valuation.filter(v => v.trends).length,
      withVsSector: valuation.filter(v => v.trends?.vsSector).length,
      sectorsMapped: Object.keys(sectorMarginTrend).length,
      noData: tickers.filter(t => !valuation.some(v => v.ticker === t)),
      errors: errors.slice(0, 20),
      note: 'Sector names here are RAW FEED NAMES (Consumer Cyclical, Financial Services, Healthcare, Basic Materials, Consumer Defensive). Translate to display names in prose. trends.direction counts consecutive quarters. trends.flip marks a sign change. trends.breakeven projects at the current pace and is an estimate, always framed as such. trends.vsSector fires only when a name moves opposite its own sector peers in this book.',
    },
  }
}];

// ============================================================================
//  SEC FILINGS + 8-K ITEM CODES  ·  NODE v1.0
//  n8n Code node · "Run Once for All Items"
//
//  WHAT THIS DOES
//  --------------
//  Two stages in one node:
//    STAGE 1  FMP sec-filings-search/symbol, one call per name you hold or
//             watch, filtered to the forms that carry signal.
//    STAGE 2  For 8-Ks on HOLDINGS only, fetch the filed document from
//             sec.gov via finalLink and extract the ITEM CODE. The item code
//             is the entire reason this node exists. "MU filed an 8-K" is
//             noise you cannot rank. "MU filed an 8-K, Item 5.02" says an
//             officer left, and Item 4.02 says the financials are being
//             restated, which is the single most negative routine filing a
//             company can make. No news feed hands you that as structured
//             data.
//
//  WHY IT IS SAFE TO RUN DAILY
//    · Document fetches are capped (DOC_FETCH_CAP) so an earnings-heavy day
//      cannot stall the pipeline.
//    · Only holdings get documents fetched. Watchlist names get metadata.
//    · Every stage degrades: FMP down means an empty block, sec.gov down
//      means filings with no item codes, never a thrown error and never a
//      placeholder rendered to an advisor.
//
//  SEC REQUIREMENT: sec.gov blocks requests without a declaring User-Agent.
//  Put a real contact address in SEC_UA or the document fetches all fail.
// ============================================================================

// API KEY RESOLUTION, n8n Cloud safe. $env THROWS on Cloud, so it is wrapped.
// Preferred: put the key in the Read Config sheet as Field = fmp_api_key.
const FMP_KEY = (function () {
  try { if ($env && $env.FMP_API_KEY) return $env.FMP_API_KEY; } catch (e) { /* blocked on Cloud */ }
  try {
    const rows = $('Read Config').all() || [];
    for (const r of rows) {
      const f = r && r.json ? String(r.json.Field || '').toLowerCase().trim() : '';
      if (f === 'fmp_api_key' && r.json.Value) return String(r.json.Value).trim();
    }
  } catch (e) { /* node not reachable from this branch */ }
  return 'REDACTED_FMP_KEY';
})();
const SEC_UA  = 'WAM Agentics will@wamagentics.com';   // required by sec.gov

const LOOKBACK_DAYS  = 5;    // filings window. 3 covers a weekend; 5 is safe.
const DOC_FETCH_CAP  = 8;    // hard ceiling on sec.gov document fetches
const CONCURRENCY    = 6;    // parallel FMP calls
const MAX_SYMBOLS    = 250;  // generous. Truncation is REPORTED, never silent.

// Forms worth pulling. Everything else is registration and housekeeping.
//   8-K     material events, the reason for this node
//   SC 13D  activist stake above 5%, filed within days, states its purpose
//   SC 13G  passive stake above 5%, mostly index funds, kept for completeness
//   4       insider transaction (you already get these from FMP insider data,
//           kept here only so the filing timeline is complete)
const KEEP_FORMS = ['8-K', '8-K/A', 'SC 13D', 'SC 13D/A', 'SC 13G', 'SC 13G/A'];

// ---------------------------------------------------------------------------
// 8-K ITEM DICTIONARY
// severity drives ranking in the brief: 3 is stop-everything, 1 is routine.
// ---------------------------------------------------------------------------
const ITEMS = {
  '1.01': { label: 'Entry into a material agreement',            sev: 2 },
  '1.02': { label: 'Termination of a material agreement',        sev: 2 },
  '1.03': { label: 'Bankruptcy or receivership',                 sev: 4 },
  '1.05': { label: 'Material cybersecurity incident',            sev: 4 },
  '2.01': { label: 'Completion of acquisition or disposition',   sev: 2 },
  '2.02': { label: 'Results of operations (earnings)',           sev: 3 },
  '2.03': { label: 'Material direct financial obligation',       sev: 2 },
  '2.04': { label: 'Triggering event accelerating an obligation',sev: 3 },
  '2.05': { label: 'Costs associated with exit or disposal',     sev: 2 },
  '2.06': { label: 'Material impairment',                        sev: 3 },
  '3.01': { label: 'Delisting notice or listing rule failure',   sev: 4 },
  '3.03': { label: 'Material modification to security holders',  sev: 2 },
  '4.01': { label: 'Change in certifying accountant',            sev: 4 },
  '4.02': { label: 'NON-RELIANCE on previously issued financials (restatement)', sev: 4 },
  '5.01': { label: 'Change in control of the registrant',        sev: 4 },
  '5.02': { label: 'Departure or appointment of officers/directors', sev: 3 },
  '5.03': { label: 'Amendment to articles or fiscal year change',sev: 1 },
  '5.07': { label: 'Submission of matters to a shareholder vote',sev: 1 },
  '7.01': { label: 'Regulation FD disclosure',                   sev: 1 },
  '8.01': { label: 'Other events',                               sev: 1 },
  '9.01': { label: 'Financial statements and exhibits',          sev: 0 },
};

// ---------------------------------------------------------------------------
// RESOLVE THE UNIVERSE
// Tries the incoming item first (it already carries Ticker / Watchlist /
// AllTickers once the sheets are aggregated), then falls back to the named
// Sheet nodes. Either wiring works, which is why this node can sit almost
// anywhere in the config fan-out.
// ---------------------------------------------------------------------------
function flatten(x) {
  const out = [];
  (function walk(v) {
    if (v == null) return;
    if (Array.isArray(v)) { v.forEach(walk); return; }
    const s = String(v).trim().toUpperCase();
    if (s) out.push(s);
  })(x);
  return out;
}

// UNION, NOT FIRST-WINS. A dual-mandate book splits its holdings across more
// than one sheet (Read Holdings1 is the Roth, Read Holdings2 the House), and
// returning on the first node that answered meant the second mandate was never
// queried. It went unnoticed only because that mandate happens to hold nothing
// but funds today; the first individual stock added there would have gone
// silently uncovered. Every source is read and the results are combined.
function fromNodes(names, field) {
  const out = [];
  for (const n of names) {
    try {
      const rows = $(n).all() || [];
      const vals = rows.map(r => (r && r.json ? (r.json[field] || r.json.Ticker || r.json.Symbol || r.json.symbol) : null));
      flatten(vals).forEach(t => { if (out.indexOf(t) === -1) out.push(t); });
    } catch (e) { /* node not reachable from this branch */ }
  }
  return out;
}

let incoming = {};
try { incoming = ($input.first() && $input.first().json) || {}; } catch (e) { incoming = {}; }

let holdings = flatten(incoming.Ticker || incoming.holdings || null);
let watchlist = flatten(incoming.Watchlist || null);

if (!holdings.length) {
  holdings = fromNodes(
    ['Read Holdings1', 'Read Holdings2', 'Read Holdings3', 'Read Holdings', 'Read Config'],
    'Ticker');
}
if (!watchlist.length) watchlist = fromNodes(['Read Watchlist', 'Read Watchlist2'], 'Watchlist');

// Deduplicate, drop anything that is not a plausible US ticker, and mark which
// list each symbol came from. Held names get documents fetched; watchlist
// names get metadata only, which matches the compliance separation everywhere
// else in this product.
// EXCLUDE FUNDS. An ETF or trust does not file 8-Ks, so every hit on one is a
// TICKER COLLISION with an operating company that happens to share the symbol.
// A live run proved it: "ETH" returned a Schedule 13D/A from Ethan Allen
// Interiors (CIK 0000896156), which trades as ETH, and the reader holds the
// Grayscale Ethereum trust. Publishing an activist stake in a furniture maker
// as news about a crypto position is the kind of error that ends a trial.
const isFundTicker = (function () {
  const map = {};
  const seen = {};
  function harvest(prof) {
    if (!prof) return false;
    let n = 0;
    Object.keys(prof).forEach(k => {
      const p = prof[k] || {};
      seen[String(k).toUpperCase()] = 1;          // profile covered this symbol
      if (p.isEtf === true || p.isFund === true) { map[String(k).toUpperCase()] = 1; n++; }
    });
    return Object.keys(prof).length > 0;
  }
  // 1. the incoming item, when this node sits after the config fan-out
  try { harvest((incoming.profiles && incoming.profiles.profilesByTicker) || null); } catch (e) {}
  // 2. by node name, for when it runs in series after FRED and the incoming
  //    item is the macro payload rather than the config payload
  try {
    for (const nm of ['Process Profiles', 'Profiles', 'sector look-through']) {
      try {
        const rows = $(nm).all() || [];
        for (const r of rows) {
          const j = r && r.json ? r.json : {};
          const prof = (j.profiles && j.profiles.profilesByTicker) || j.profilesByTicker || null;
          if (harvest(prof)) break;
        }
      } catch (e) { /* not reachable from this branch */ }
    }
  } catch (e) {}
  // Backstop ONLY, for runs where profiles are unreachable. This list can never
  // be complete, which is why it is not the primary mechanism: COMPANY PROFILES
  // carries isEtf/isFund for whatever this advisor actually holds, so a book
  // full of funds nobody anticipated is still classified correctly. A third
  // safety net (fund-form detection at query time) catches the remainder.
  ['GLD','IBIT','ETH','SCHD','SPYM','QQQM','QQQ','SPY','VOO','IVV','VTI','VTV','VUG','VEA','VWO','ARKK',
   'XLK','XLF','XLE','XLV','XLI','XLP','XLU','XLY','XLC','XLB','XLRE','SMH','SOXX','FTEC','JEPI','JEPQ',
   'TLT','IEF','SHY','AGG','BND','HYG','LQD','GBTC','BITO','IWM','DIA','EFA','EEM','GDX','SLV','USO']
    .forEach(t => { map[t] = 1; });
  map.__seen = Object.keys(seen).length ? seen : null;
  return map;
})();

// Which symbols we could NOT confirm either way. Reported so an unfamiliar
// fund in someone else's book is visible rather than silently trusted.
const noProfile = [];

const skippedFunds = [];
const profileSeen = isFundTicker.__seen || null;
// Symbols may carry digits (share classes, foreign listings), so the shape
// test allows them. Anything rejected is REPORTED, never dropped in silence.
const SYM_RE = /^[A-Z][A-Z0-9.\-]{0,6}$/;
const rejectedSymbols = [];
const heldSet = {};
holdings.forEach(t => {
  if (!SYM_RE.test(t)) { rejectedSymbols.push(t); return; }
  if (isFundTicker[t]) { skippedFunds.push(t); return; }
  if (profileSeen && !profileSeen[t]) noProfile.push(t);
  heldSet[t] = 1;
});
const watchSet = {};
watchlist.forEach(t => {
  if (!SYM_RE.test(t)) { rejectedSymbols.push(t); return; }
  if (heldSet[t]) return;
  if (isFundTicker[t]) { skippedFunds.push(t); return; }
  watchSet[t] = 1;
});

const fullUniverse = Object.keys(heldSet).concat(Object.keys(watchSet));
const universe = fullUniverse.slice(0, MAX_SYMBOLS);
// A book larger than the cap loses coverage, and losing it quietly is how a
// filing on a real holding goes missing with nothing in the output to explain
// it. Held names are ordered first, so any truncation eats watchlist names
// before it eats holdings.
const truncated = fullUniverse.length > universe.length
  ? { requested: fullUniverse.length, queried: universe.length, dropped: fullUniverse.slice(MAX_SYMBOLS) }
  : null;

// ---------------------------------------------------------------------------
// DATES
// FMP caps the range at 90 days; we want the last few days only.
// ---------------------------------------------------------------------------
const iso = d => d.toISOString().slice(0, 10);
const toDate = new Date();
const fromDate = new Date(toDate.getTime() - LOOKBACK_DAYS * 86400000);

// ---------------------------------------------------------------------------
// HTTP with graceful failure
// ---------------------------------------------------------------------------
const getJson = async (url) => {
  const raw = await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 15000 });
  return typeof raw === 'string' ? JSON.parse(raw) : raw;
};

const getText = async (url) => {
  return await this.helpers.httpRequest({
    method: 'GET', url, json: false, timeout: 20000,
    headers: { 'User-Agent': SEC_UA, 'Accept-Encoding': 'gzip, deflate' },
  });
};

// Run promises in bounded batches so 40 symbols do not open 40 sockets at once.
async function inBatches(items, size, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    const slice = items.slice(i, i + size);
    const res = await Promise.all(slice.map(fn));
    res.forEach(r => out.push(r));
  }
  return out;
}

// ---------------------------------------------------------------------------
// STAGE 1 · FILING METADATA PER SYMBOL
// ---------------------------------------------------------------------------
const errors = [];
// When the fund-form net fires, record WHY. A symbol dropped with no evidence
// is indistinguishable from a symbol that simply had no filings.
const fundFormEvidence = [];

const perSymbol = await inBatches(universe, CONCURRENCY, async (sym) => {
  const url = 'https://financialmodelingprep.com/stable/sec-filings-search/symbol'
    + `?symbol=${encodeURIComponent(sym)}`
    + `&from=${iso(fromDate)}&to=${iso(toDate)}`
    + `&page=0&limit=100&apikey=${FMP_KEY}`;
  try {
    const rows = await getJson(url);
    if (!Array.isArray(rows)) return { sym, filings: [] };
    // Registered funds file forms an operating company never files. Used as a
    // THIRD safety net for ETFs the profile data and the backstop list both
    // missed. TWO guards, because a loose version of this test dropped GOOGL
    // and INTC on a live run by prefix-matching something in their filing
    // history, which silently discarded 8-Ks on a real holding:
    //   (a) the form must be an UNAMBIGUOUS fund form, matched exactly, not by
    //       prefix. "424B5" and "4" are not fund forms; "485BPOS" is.
    //   (b) the symbol must file NO operating-company forms at all. A real
    //       company filing an 8-K is a real company, whatever else is in the
    //       list, so the presence of one vetoes the whole test.
    // N-PX is DELIBERATELY ABSENT. It is a proxy-voting record, filed by
    // institutional managers and operating-company benefit plans as well as by
    // funds, so it does not identify a fund. A live run classified INTC as a
    // fund on an N-PX alone because no operating form happened to fall inside
    // the five-day window to veto it.
    const FUND_FORM = /^(N-(CSR|CSRS|Q|MFP|CEN|VP|1A|2|14|18F|54A|54C|6F|8A|8B|8F)|NPORT-(P|EX|NP)|24F-2NT|485(A|B)(POS|XT)|497(K|J)?|N-1A)$/i;
    // The short ownership forms (3, 4, 5) MUST be matched exactly. As a bare
    // alternative in a prefix pattern, "4" matches any string starting with a
    // four, so "485BPOS" and "497" both registered as operating-company forms
    // and vetoed the fund test they were supposed to trigger.
    const OPERATING_FORM = /^(8-K|10-K|10-Q|S-1|S-3|S-4|S-8|DEF 14A|SC 13[DG]|11-K|20-F|40-F|6-K)/i;
    const OWNERSHIP_FORM = /^[345](\/A)?$/;
    const forms = rows.map(r => String((r && r.formType) || '').trim());
    const isOperating = f => OPERATING_FORM.test(f) || OWNERSHIP_FORM.test(f);
    const looksLikeFund = forms.some(f => FUND_FORM.test(f)) && !forms.some(isOperating);
    if (looksLikeFund) {
      skippedFunds.push(sym);
      fundFormEvidence.push({ symbol: sym, forms: forms.filter((f, i) => forms.indexOf(f) === i).slice(0, 6) });
      return { sym, filings: [] };
    }

    const filings = rows
      .filter(r => r && KEEP_FORMS.indexOf(String(r.formType || '').trim()) !== -1)
      .map(r => ({
        symbol: String(r.symbol || sym).toUpperCase(),
        cik: r.cik || null,
        formType: String(r.formType || '').trim(),
        // acceptedDate is when the SEC actually received it and is the right
        // field for "what just happened". filingDate can lag by days.
        acceptedDate: r.acceptedDate || null,
        filingDate: r.filingDate || null,
        link: r.link || null,
        finalLink: r.finalLink || null,
        held: !!heldSet[String(r.symbol || sym).toUpperCase()],
      }));
    return { sym, filings };
  } catch (e) {
    errors.push({ stage: 'filings', symbol: sym, reason: String(e && e.message ? e.message : e).slice(0, 140) });
    return { sym, filings: [] };
  }
});

let all = [];
perSymbol.forEach(p => { all = all.concat(p.filings); });

// Newest first by acceptedDate, falling back to filingDate.
function ts(f) {
  const d = f.acceptedDate || f.filingDate;
  const t = d ? Date.parse(String(d).replace(' ', 'T')) : NaN;
  return isNaN(t) ? 0 : t;
}
all.sort((a, b) => ts(b) - ts(a));

// ---------------------------------------------------------------------------
// STAGE 2 · ITEM CODES FROM THE FILED DOCUMENT
// Only 8-Ks, only holdings, only the newest DOC_FETCH_CAP of them.
// ---------------------------------------------------------------------------
function stripHtml(html) {
  return String(html)
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&#160;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&#8217;|&rsquo;/gi, "'").replace(/&#8220;|&#8221;|&ldquo;|&rdquo;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function parseItems(text) {
  const found = [];
  const re = /Item\s+(\d{1,2}\.\d{2})/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    const code = m[1];
    if (found.indexOf(code) === -1) found.push(code);
  }
  return found;
}

// The sentence or two after the item heading is the actual disclosure. Grab a
// bounded slice so the payload never balloons.
function itemContext(text, code) {
  const i = text.search(new RegExp('Item\\s+' + code.replace('.', '\\.'), 'i'));
  if (i === -1) return null;
  return text.slice(i, i + 420).trim();
}

const eightKs = all.filter(f => f.held && /^8-K/.test(f.formType) && f.finalLink);
const toFetch = eightKs.slice(0, DOC_FETCH_CAP);

// FMP's finalLink is often the EX-99 press release rather than the 8-K body,
// and item codes live only in the body. A live run returned Nvidia's earnings
// exhibit (q2fy27pr.htm), parsed zero items, and the biggest filing of the
// week fell out of the summary. When the first fetch yields no items, walk the
// filing index and take the primary document instead.
function primaryDocFrom(indexHtml, baseUrl) {
  const hrefs = [];
  const re = /href="([^"]+\.htm[l]?)"/gi;
  let m;
  while ((m = re.exec(indexHtml)) !== null) hrefs.push(m[1]);
  const cands = hrefs.filter(h =>
    !/-index/i.test(h) && !/^\/cgi-bin/i.test(h) && !/ex-?\d/i.test(h) && !/exhibit/i.test(h));
  if (!cands.length) return null;
  const pick = cands[0];
  if (/^https?:/i.test(pick)) return pick;
  if (pick.charAt(0) === '/') return 'https://www.sec.gov' + pick;
  return baseUrl.replace(/\/[^/]*$/, '/') + pick;
}

await inBatches(toFetch, 3, async (f) => {
  try {
    let html = await getText(f.finalLink);
    let text = stripHtml(html);
    let codes = parseItems(text);

    if (!codes.length && f.link) {
      try {
        const idx = await getText(f.link);
        const primary = primaryDocFrom(idx, f.link);
        if (primary && primary !== f.finalLink) {
          const html2 = await getText(primary);
          const text2 = stripHtml(html2);
          const codes2 = parseItems(text2);
          if (codes2.length) {
            f.primaryDoc = primary;
            html = html2; text = text2; codes = codes2;
          }
        }
      } catch (e) { /* index unreachable; keep what the exhibit gave us */ }
    }

    // Last resort: an earnings press release with no parsable body is still an
    // Item 2.02 event. Marked inferred so nothing downstream treats it as read
    // from the filing itself.
    if (!codes.length && /(announce[sd]?|report(s|ed)?)[^.]{0,60}(financial )?results|reported revenue of|second quarter|first quarter|third quarter|fourth quarter/i.test(text)) {
      codes = ['2.02'];
      f.itemsInferred = true;
    }
    f.items = codes;
    f.itemDetail = codes.map(c => ({
      code: c,
      label: ITEMS[c] ? ITEMS[c].label : 'Unclassified item',
      severity: ITEMS[c] ? ITEMS[c].sev : 1,
      context: itemContext(text, c),
    }));
    f.maxSeverity = f.itemDetail.reduce((m, x) => Math.max(m, x.severity), 0);
    f.excerpt = text.slice(0, 600);
    f.docFetched = true;
  } catch (e) {
    f.docFetched = false;
    errors.push({ stage: 'document', symbol: f.symbol, reason: String(e && e.message ? e.message : e).slice(0, 140) });
  }
  return true;
});

// Anything not fetched still renders as a filing, just without item codes.
all.forEach(f => {
  if (f.items === undefined) { f.items = null; f.itemDetail = null; f.maxSeverity = null; }
});

// ---------------------------------------------------------------------------
// RANK
// Severity first, then held before watchlist, then recency. This is the order
// the brief should read them in.
// ---------------------------------------------------------------------------
const ranked = all.slice().sort((a, b) => {
  const sa = a.maxSeverity == null ? -1 : a.maxSeverity;
  const sb = b.maxSeverity == null ? -1 : b.maxSeverity;
  if (sb !== sa) return sb - sa;
  if (a.held !== b.held) return a.held ? -1 : 1;
  return ts(b) - ts(a);
});

// ---------------------------------------------------------------------------
// SUMMARY FOR THE PROMPT
// Same shape as the other digest blocks: one line per filing, dated, with the
// direct link. Absent means absent, so an empty run emits an empty string and
// the dependent section simply does not appear.
// ---------------------------------------------------------------------------
function fmtLine(f) {
  const when = (f.acceptedDate || f.filingDate || '').slice(0, 16);
  const tag = f.held ? '[HOLDING]' : '[WATCHLIST, metadata only]';
  if (f.items && f.items.length) {
    const parts = f.itemDetail
      .filter(x => x.severity > 0)
      .map(x => `Item ${x.code} (${x.label})${f.itemsInferred ? ', inferred from the release, not read off the filing body' : ''}`);
    return `${f.symbol} ${tag} ${f.formType} filed ${when} · ${parts.join('; ') || 'items: ' + f.items.join(', ')} · ${f.finalLink}`;
  }
  return `${f.symbol} ${tag} ${f.formType} filed ${when} · ${f.finalLink || f.link || ''}`;
}

// Every filing on a HOLDING reaches the summary. v1 dropped anything scoring
// zero, which is how an Nvidia earnings 8-K disappeared. Only routine
// watchlist noise is filtered out now.
const material = ranked.filter(f => f.held || f.maxSeverity == null || f.maxSeverity >= 2);

const secFilingsSummary = material.length
  ? 'SEC FILINGS, LAST ' + LOOKBACK_DAYS + ' DAYS (primary source; the 8-K ITEM CODE is the signal. '
    + 'Item 4.02 is a restatement, 5.02 an officer change, 1.05 a cybersecurity incident, 2.02 earnings. '
    + 'Ranked by severity then recency. A watchlist filing may be described as an EVENT but never carries a target or valuation figure):\n'
    + material.slice(0, 12).map(f => '- ' + fmtLine(f)).join('\n')
  : '';

const highSeverity = ranked.filter(f => f.maxSeverity != null && f.maxSeverity >= 3);

// PASS-THROUGH BY DESIGN.
// n8n's Merge node caps at 10 inputs, and both merges in this workflow are
// full. Rather than add an eleventh branch, this node runs IN SERIES on an
// existing one (recommended: immediately after FRED Code) and carries whatever
// arrived on its input forward untouched, adding its own keys alongside. The
// upstream node's existing Merge slot then delivers both payloads.
// Object.assign, not a spread, per the house rule about load-bearing spreads
// in n8n Code nodes. Own keys are applied LAST so a name collision can never
// let upstream data overwrite this node's output.
const passthrough = Object.assign({}, incoming);

return [{
  json: Object.assign(passthrough, {
    secFilings: ranked,                 // full structured records
    secFilingsSummary: secFilingsSummary, // prose block for the prompt
    secFilingsCount: ranked.length,
    secHighSeverity: highSeverity.map(f => ({
      symbol: f.symbol, formType: f.formType,
      acceptedDate: f.acceptedDate,
      items: f.itemDetail ? f.itemDetail.map(x => x.code + ' ' + x.label) : null,
      link: f.finalLink,
    })),
    secDocsFetched: toFetch.filter(f => f.docFetched).length,
    secSkippedFunds: skippedFunds.filter((t, i) => skippedFunds.indexOf(t) === i),
    secUniverseSize: universe.length,
    secHeld: Object.keys(heldSet),        // exact operating companies queried as holdings
    secWatched: Object.keys(watchSet),    // watchlist names queried, metadata only
    secWindow: { from: iso(fromDate), to: iso(toDate) },
    secErrors: errors,
    secTruncated: truncated,   // non-null only when the book exceeds MAX_SYMBOLS
    secNoProfile: noProfile,   // queried without fund/ETF confirmation
    secRejectedSymbols: rejectedSymbols.filter((t, i) => rejectedSymbols.indexOf(t) === i),
    secFundFormEvidence: fundFormEvidence,   // why a symbol was treated as a fund at query time
  })
}];

// ============================================================================
//  MARKET PULSE · TWO CODE NODES
//  Node A: VALIDATOR   (place between the agent and Formatting2, then an IF node on {{ $json.ok }})
//  Node B: PRE-FLIGHT  (place between "analyst desk rollup" and the agent, then an IF node on {{ $json.ok }})
//  Both: Code node, JavaScript, mode "Run Once for All Items". No fetch, no axios, no $http.
// ============================================================================


// ────────────────────────────────────────────────────────────────────────────
//  NODE A · VALIDATOR
//  Reads the agent output whether it came from the n8n AI Agent node ($json.output)
//  or from a raw DeepSeek HTTP Request node ($json.choices[0].message.content).
//  Emits { ok, failures, warnings, stats, output } where output is the untouched brief.
// ────────────────────────────────────────────────────────────────────────────
const item = $input.first().json;
const text = String(
  item.output
  ?? (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content)
  ?? item.text
  ?? ''
);

const failures = [];
const warnings = [];
const count = (re) => (text.match(re) || []).length;

// 1. Eight sections, canonical order, exact ids.
const ids = ['desk','spotlight','situations','clients','analyst','people','scenarios','week'];
const positions = ids.map(id => text.indexOf('<div class="sec-num" id="' + id + '">'));
const missing = ids.filter((id, i) => positions[i] === -1);
// clients is legitimately absent in analyst mode; treat it as a warning, everything else as a failure.
missing.forEach(id => (id === 'clients' ? warnings : failures).push('missing section: ' + id));
const present = positions.filter(p => p !== -1);
for (let i = 1; i < present.length; i++) if (present[i] < present[i - 1]) { failures.push('sections out of canonical order'); break; }

// 2. The brief ends with the joke block. This is the truncation tripwire.
const jokes = count(/<div class="jokes">/g);
if (jokes !== 1) failures.push('joke block count = ' + jokes + ' (expected 1)');
const tail = text.slice(-600);
if (!/joke-a/.test(tail)) failures.push('output does not end at the joke block (probable truncation)');

// 3. Engine markers.
['perf-here', 'movers-here', 'sectors-here'].forEach(m => {
  if (text.indexOf('<div class="' + m + '"') === -1) failures.push('missing marker: ' + m);
});
if (text.indexOf('<div class="consensus-here"') === -1) warnings.push('missing marker: consensus-here (fine in advisor mode)');

// 4. Counted contracts.
const pbWrap = count(/<div class="pb">/g);
const pbItems = count(/<div class="pb-item">/g);
if (pbWrap !== 1) failures.push('pb wrapper count = ' + pbWrap + ' (expected 1)');
if (pbItems !== 5) failures.push('pb-item count = ' + pbItems + ' (expected 5)');
const mv = count(/<div class="mv-item">/g);
if (mv !== 3) warnings.push('mv-item count = ' + mv + ' (expected 3)');
const blind = count(/<div class="bsx-top-banner">/g);
if (blind !== 1) failures.push('blind spot count = ' + blind + ' (expected 1)');
const ap = count(/<div class="ap-item">/g);
if (ap !== 3) warnings.push('ap-item count = ' + ap + ' (expected 3)');
const secNews = count(/<div class="sec-news"/g);
if (secNews !== 2) warnings.push('sec-news count = ' + secNews + ' (expected 2)');
const onItems = count(/<div class="on-item">/g);
if (onItems < 3 || onItems > 8) warnings.push('on-item count = ' + onItems);
const s60 = count(/<x-dd class="dd s60">/g);
if (s60 !== 1) warnings.push('Section 01 drawer count = ' + s60 + ' (expected 1)');

// 5. Mechanical bans.
const emDash = count(/\u2014/g);
if (emDash > 0) failures.push('em dashes: ' + emDash);
const amp = count(/&amp;/g);
if (amp > 0) warnings.push('&amp; entities: ' + amp + ' (engine sweeps these; count is a quality signal)');
const dead = ['tactical-read', 'macro-overview', 'sec-lead', 'fd-b', '<details', '<script', '<style'];
dead.forEach(d => { if (text.indexOf(d) !== -1) failures.push('forbidden element: ' + d); });

// 6. Placeholders that reached the page.
const ph = text.match(/\[(TICKER|Tool|TBD|Name|Event|House|URL|Publication|Setup|Punchline|Claim|Step)[^\]]*\]/g);
if (ph) failures.push('placeholders on page: ' + [...new Set(ph)].slice(0, 5).join(', '));
if (/DIRECT_URL/.test(text)) failures.push('DIRECT_URL placeholder in a must-read');

// 7. Size sanity. A brief under 40k characters lost sections; over 140k means counts were ignored.
const chars = text.length;
if (chars < 40000) failures.push('output too short: ' + chars + ' chars');
if (chars > 140000) warnings.push('output long: ' + chars + ' chars');

// 8. Preamble check: the first characters must be the Section 01 marker.
if (!/^\s*<div class="sec-num" id="desk">01<\/div>/.test(text)) failures.push('output does not start at the Section 01 marker (preamble or narration present)');

const usage = item.tokenUsage || item.usage || null;

return [{
  json: {
    ok: failures.length === 0,
    failures,
    warnings,
    stats: {
      chars,
      sections: present.length,
      pbItems, mv, blind, ap, secNews, onItems, jokes, emDash, amp,
      promptTokens: usage ? (usage.promptTokens ?? usage.prompt_tokens ?? null) : null,
      completionTokens: usage ? (usage.completionTokens ?? usage.completion_tokens ?? null) : null,
      reasoningTokens: usage && usage.completion_tokens_details ? (usage.completion_tokens_details.reasoning_tokens ?? null) : null,
      checkedAt: new Date().toISOString()
    },
    output: text
  }
}];


// ────────────────────────────────────────────────────────────────────────────
//  NODE B · PRE-FLIGHT PAYLOAD CHECK
//  Paste as a SEPARATE Code node. Runs before the agent. If ok is false, route to
//  an alert email and stop: never spend fifteen minutes of generation on a broken payload.
// ────────────────────────────────────────────────────────────────────────────
/*
