// ── Inject Audio URL ─────────────────────────────────────────
// Last node before the email. Joins the brief html with the worker's
// dated url and the audio url, guards every link, and computes every
// value the email template needs so the template itself stays a plain
// template literal with ${$json.x} bindings only. n8n's expression
// parser cannot handle comments or multi-line functions inside {{ }},
// so ALL logic lives here.
const slug = (s) => String(s || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 40);

let advisorRaw = '';
try {
  advisorRaw = $('Read Config').all()
    .find(i => i.json.Field === 'advisor_name')?.json.Value || '';
} catch (e) { /* handled below */ }
const advisor = slug(advisorRaw);

const all = $input.all();

// ── audio link, from the merged stream ──
const audioItem = all.find(i => i.json.audioUrl) || {};
const audioUrl  = audioItem.json?.audioUrl || '';

// ── hosted brief link, if the worker returned one ──
const hostedItem = all.find(i => i.json.url) || {};
const hostedUrl  = hostedItem.json?.url || '';

// ── the brief html: try the stream first, then Formatting2 ──
let html = '';
let subject = '';
const inline = all.find(i => i.json.html);
if (inline) {
  html = inline.json.html || '';
  subject = inline.json.subject || '';
} else {
  try {
    const f = $('Formatting2').first().json;
    html = f.html || '';
    subject = f.subject || '';
  } catch (e) { /* handled by GUARD 1 */ }
}

// GUARD 1 — the brief itself must exist.
if (!html) {
  throw new Error('Inject Audio URL: no html on the input stream and none readable from Formatting2. Check that the Formatting2 node is named exactly that and emits an html field.');
}

// GUARD 2 — an empty audioUrl would write href="" and ship a dead link.
if (!audioUrl) {
  throw new Error('Inject Audio URL: audioUrl is empty. TTS or the R2 upload failed. Not sending a brief with a dead audio link.');
}

// GUARD 2b — the dated brief link must exist.
if (!hostedUrl) {
  throw new Error('Inject Audio URL: worker returned no url. Check that HTTP Request3 ran and responded with {ok, url}. Not sending.');
}

// GUARD 3 — the audio link must belong to THIS advisor.
if (advisor && !audioUrl.toLowerCase().includes(advisor)) {
  throw new Error(`Inject Audio URL: audio link does not contain this advisor's slug ("${advisor}"). URL was: ${audioUrl}. Refusing to send another client's audio.`);
}

// GUARD 4 — the brief link must belong to THIS advisor too.
if (advisor && !hostedUrl.toLowerCase().includes(advisor)) {
  throw new Error(`Inject Audio URL: hosted brief link does not contain this advisor's slug ("${advisor}"). URL was: ${hostedUrl}. Refusing to send another client's brief.`);
}

// split/join, not replace: a string pattern only swaps the FIRST match.
let updatedHtml = html.split('href="#" target="_blank"').join(`href="${audioUrl}" target="_blank"`);

// ── swap every /brief/ link in the brief html for the dated url ──
let briefLinksRewritten = 0;
updatedHtml = updatedHtml.replace(
  /https?:\/\/[^"'\s]*\/brief\/[^"'\s]*/g,
  () => { briefLinksRewritten++; return hostedUrl; }
);

// ── values for the email template ─────────────────────────────
const pt = (d) => new Date(d).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
const nowPT = new Date(pt(new Date()));
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const dateLine = `${days[nowPT.getDay()]}, ${months[nowPT.getMonth()]} ${nowPT.getDate()}, ${nowPT.getFullYear()}`;
let h = nowPT.getHours(); const ampm = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12;
const prepLine = `${h}:${String(nowPT.getMinutes()).padStart(2, '0')} ${ampm} Pacific`;

const advisorName = advisorRaw || 'your desk';
const initials = advisorName.split(/\s+/).filter(Boolean).slice(0, 2).map(w => w[0].toUpperCase()).join('') || 'MP';

const readMin = 10;

const audioMin = 5;

// ticker band: live quotes first, then the holdings list, then a generic line
let tape = '';
try {
  const q = $('Price Data').first().json;
  const rows = Array.isArray(q.quotes) ? q.quotes : (Array.isArray(q) ? q : []);
  tape = rows.slice(0, 14)
    .map(r => `${r.symbol || r.ticker || ''} ${Number(r.price).toFixed(2)}`)
    .filter(s => !/undefined|NaN|^ /.test(s))
    .join(' &nbsp;&middot;&nbsp; ');
} catch (e) { /* fall through */ }
if (!tape) {
  try { tape = $('Read Holdings1').all().map(i => i.json.Ticker).filter(Boolean).slice(0, 18).join(' &nbsp;&middot;&nbsp; '); } catch (e) { /* fall through */ }
}
if (!tape) tape = 'S&amp;P 500 &nbsp;&middot;&nbsp; NASDAQ &nbsp;&middot;&nbsp; 10Y &nbsp;&middot;&nbsp; GOLD &nbsp;&middot;&nbsp; WTI &nbsp;&middot;&nbsp; VIX';

const archiveUrl = `https://market-pulse.will-f84.workers.dev/archive/${advisor}`;

return [{
  json: {
    html: updatedHtml,
    subject,
    audioUrl,
    hostedUrl,
    archiveUrl,
    briefLinksRewritten,
    advisor: advisor || null,
    advisorName,
    initials,
    dateLine,
    prepLine,
    readMin,
    audioMin,
    tape,
  }
}];

// ── n8n Code node: "Prep Script for Inworld TTS" v2 ──
// Mode: Run Once for All Items
// Input:  the podcast script agent output (script string nested in the LLM response)
// Output: one item PER CHUNK, each with { chunkText, chunkIndex, chunkTotal }
//         — the HTTP node runs once per item automatically.
//
// v2 FIX: the old sentence regex treated periods inside decimals ("1.5%",
// "4.57%") and abbreviations ("U.S.") as sentence ends and DROPPED the
// fragment before them, which clipped the cold open and mangled numbers.
// New boundary: terminal punctuation + whitespace + capital/quote — which
// "1.5% this", "4.57%, and", and "U.S. widened" never produce.

// --- tuneables -------------------------------------------------------------
const MAX_CHARS = 1500;       // conservative cap per Inworld request
const BREAK_LONG  = '1200ms'; // ////  major transition
const BREAK_MED   = '700ms';  // ///   section break
const BREAK_SHORT = '300ms';  // //    in-sentence beat
// ---------------------------------------------------------------------------

// Pull the script string out of the agent output, wherever it sits.
function extractScript(json) {
  if (typeof json.podcastScript === 'string') return json.podcastScript;
  if (typeof json.text === 'string') return json.text;
  if (typeof json.output === 'string') return json.output;
  const out = json.output;
  if (Array.isArray(out)) {
    for (const o of out) {
      if (Array.isArray(o.content)) {
        const t = o.content.find(c => typeof c.text === 'string');
        if (t) return t.text;
      }
    }
  }
  if (Array.isArray(json.content)) {
    const t = json.content.find(c => typeof c.text === 'string');
    if (t) return t.text;
  }
  return '';
}

// Convert pacing markers to SSML breaks. Order matters: //// before /// before //.
function markersToSSML(text) {
  return text
    .replace(/\/{4,}/g, ` <break time="${BREAK_LONG}"/> `)
    .replace(/\/{3}/g,  ` <break time="${BREAK_MED}"/> `)
    .replace(/\/{2}/g,  ` <break time="${BREAK_SHORT}"/> `)
    .replace(/\\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Split into <= MAX_CHARS chunks WITHOUT breaking decimals/abbreviations.
// Sentence boundary = [.!?] + whitespace + (capital letter, quote, or <break).
// Decimals ("1.5%") have no space after the period; abbreviations mid-sentence
// ("U.S. widened") have no capital after; both survive intact.
function chunkText(text, max) {
  if (text.length <= max) return [text];
  const sentences = text.split(/(?<=[.!?])\s+(?=[A-Z"<])/);
  const chunks = [];
  let current = '';
  for (const s of sentences) {
    if (current && (current.length + 1 + s.length) > max) {
      chunks.push(current.trim());
      current = s;
    } else {
      current = current ? current + ' ' + s : s;
    }
    // Single sentence longer than max: hard-split on a break tag or space.
    while (current.length > max) {
      let cut = current.lastIndexOf('<break', max);
      if (cut < max * 0.5) cut = current.lastIndexOf(' ', max);
      if (cut < max * 0.5) cut = max;
      chunks.push(current.slice(0, cut).trim());
      current = current.slice(cut).trim();
    }
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks;
}

