  return '<div class="metrics" data-tiles="' + n + '" style="grid-template-columns:repeat(' + n + ',1fr)">'
    + y2Tile
    + bookTiles.join('')
    + y10Tile
    + '</div>';
}
function fmtBps(v){
  if (v===null||v===undefined) return null;
  if (typeof v === 'string' && /bp/i.test(v)) return v.replace(/\s+/g,' ');
  var n = num(v); if (n===null) return String(v);
  var bps = Math.abs(n) < 4 ? n*100 : n;
  return (bps>=0?'+':'−') + Math.abs(bps).toFixed(0) + 'bps';
}

// ── UPCOMING STRIPS ────────────────────────────────────────────
// Two compact rows between the tiles and the Fed strip. Both are built from
// payload fields the engine already receives and both return '' when their
// data block is empty, so the masthead simply closes up.
//
// Gold appears exactly once per strip: on the control that jumps to Section 08.
// The pills themselves are static, so they are not gold.
function stripJump(label){
  return '<a class="ustrip-go" href="#week">' + esc(label)
    + ' <span class="ustrip-arrow">\u2192</span></a>';
}
function buildEarningsStrip(){
  var rows = dv('earningsThisWeek', null);
  if (!Array.isArray(rows) || !rows.length) return '';
  var EARN_MAX = 4;
  var valid = [];
  rows.forEach(function(r){
    if (!r) return;
    var sym = String(r.symbol || r.ticker || '').toUpperCase().trim();
    if (!sym) return;
    // shortDay is in the payload; fall back to trimming dayOfWeek.
    var day = String(r.shortDay || r.dayOfWeek || '').trim().slice(0,3);
    // Soonest first. daysAway is the payload's own ordering key; the date
    // string is the fallback when a row predates that field.
    var k = num(r.daysAway);
    valid.push({ sym: sym, day: day, k: (k===null ? 9999 : k), d: String(r.date || '') });
  });
  if (!valid.length) return '';
  valid.sort(function(a,b){ return (a.k - b.k) || (a.d < b.d ? -1 : a.d > b.d ? 1 : 0); });
  var more = valid.length > EARN_MAX ? valid.length - EARN_MAX : 0;
  var pills = valid.slice(0, EARN_MAX).map(function(r){
    return '<span class="ustrip-pill">'
      + (r.day ? '<span class="ustrip-d">' + esc(r.day) + '</span>' : '')
      + '<span class="ustrip-n">' + esc(r.sym) + '</span></span>';
  });
  return '<div class="ustrip ustrip-lead"><span class="ustrip-k">Upcoming Earnings</span>'
    + '<span class="ustrip-row">' + pills.join('')
    + (more ? '<span class="ustrip-more">+' + more + '</span>' : '')
    + '</span>' + stripJump('Week Ahead') + '</div>';
}
// Long event names are unreadable at pill size. Map the ones that actually
// matter to the name a reader uses out loud; anything unmapped keeps its own
// words, trimmed of the trailing "(Aug)" period tag.
var ECON_SHORT = [
  [/fomc|interest rate decision/i, 'FOMC'],
  [/non[- ]?farm payrolls/i, 'Payrolls'],
  [/^(?!.*\bcore\b).*inflation rate/i, 'CPI'],
  [/core (?:inflation rate|cpi)/i, 'Core CPI'],
  [/producer price index/i, 'PPI'],
  [/ism (?:non-manufacturing|services) pmi/i, 'ISM Services'],
  [/ism manufacturing pmi/i, 'ISM Mfg'],
  [/unemployment rate/i, 'Unemployment'],
  [/retail sales/i, 'Retail Sales'],
  [/gdp/i, 'GDP'],
  [/jolts/i, 'JOLTS'],
  [/adp employment/i, 'ADP'],
  [/michigan consumer sentiment/i, 'Michigan'],
  [/existing home sales/i, 'Home Sales'],
  [/initial jobless claims/i, 'Claims']
];
// Rank, not just rename: returns the ECON_SHORT index so a day can be reduced
// to its headline print. Unmapped events sort last and keep their own words.
function econRank(name){
  var n = String(name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
  for (var i=0;i<ECON_SHORT.length;i++){ if (ECON_SHORT[i][0].test(n)) return i; }
  return ECON_SHORT.length;
}
function econShort(name){
  var r = econRank(name);
  if (r < ECON_SHORT.length) return ECON_SHORT[r][1];
  var n = String(name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
  return n.length > 13 ? n.slice(0,12).trim() + '\u2026' : n;
}
function buildDatesStrip(){
  var cal = dv('economicCalendar', null);
  var byDay = cal && cal.eventsByDay;
  if (!byDay || typeof byDay !== 'object') return '';
  var days = Object.keys(byDay).sort();
  if (!days.length) return '';
  var SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var today = new Date(days[0] + 'T12:00:00');
  // Four dates: the two soonest, then the two most important of what is left.
  // Soonest-first alone buries a payrolls print behind two days of filler;
  // importance-first alone drops what happens tomorrow. Taking both gives the
  // reader the near horizon and the events actually worth planning around.
  // Fewer than four only when the calendar genuinely holds fewer.
  var DATE_NEAR = 2, DATE_MAX = 4;
  var cand = [];
  days.forEach(function(d){
    var list = byDay[d];
    if (!Array.isArray(list)) return;
    // High impact only: this strip is the handful of prints that move the book.
    var hi = list.filter(function(e){ return e && /high/i.test(String(e.impact||'')); });
    if (!hi.length) return;
    var dt = new Date(d + 'T12:00:00');
    if (isNaN(dt.getTime())) return;
    var ahead = Math.round((dt - today) / 86400000);
    // Inside a week a weekday is the clearer reference; past that, a date is.
    var when = (ahead >= 0 && ahead <= 6) ? SHORT[dt.getDay()]
             : (MON[dt.getMonth()] + ' ' + dt.getDate());
    // One event per day: the headline print, not whatever the feed listed first.
    var lead = hi[0];
    hi.forEach(function(e){ if (econRank(e.event) < econRank(lead.event)) lead = e; });
    cand.push({ d: d, when: when, rank: econRank(lead.event), name: econShort(lead.event) });
  });
  if (!cand.length) return '';
  // Chronological. The rank-based fill below slices from this order.
  cand.sort(function(a,b){ return a.d < b.d ? -1 : a.d > b.d ? 1 : 0; });
  // cand is chronological here. Hold the near ones, rank the remainder.
  var picked = cand.slice(0, DATE_NEAR);
  var rest = cand.slice(DATE_NEAR).sort(function(a,b){
    return (a.rank - b.rank) || (a.d < b.d ? -1 : a.d > b.d ? 1 : 0);
  });
  for (var i = 0; i < rest.length && picked.length < DATE_MAX; i++) picked.push(rest[i]);
  picked.sort(function(a,b){ return a.d < b.d ? -1 : a.d > b.d ? 1 : 0; });
  var pills = picked.map(function(c){
    return '<span class="ustrip-pill"><span class="ustrip-d">' + esc(c.when) + '</span>'
      + '<span class="ustrip-n">' + esc(c.name) + '</span></span>';
  });
  return '<div class="ustrip ustrip-tight"><span class="ustrip-k">Big Upcoming Dates</span>'
    + '<span class="ustrip-row">' + pills.join('') + '</span>'
    + stripJump('Calendar') + '</div>';
}
function buildFed(){
  var items = [];
  var ffr = dv('fedFundsRate', null);
  if (ffr) items.push('🏦 Fed Funds <strong>' + esc(ffr) + '</strong>');
  items.push('Next FOMC <strong>' + nextFomc() + '</strong>');
  // 10Y and 2Y are masthead tiles now. Leaving them here as well would print
  // the same two rates twice on one screen: one metric, one number, one home.
  var s210 = dv('spread2s10s', null);
  var b = fmtBps(s210); if (b) items.push('2s10s <strong>' + b + '</strong>');
  return '<div class="fed">' + items.map(function(x){ return '<span class="fed-item">' + x + '</span>'; }).join('<span class="sep">|</span>') + '</div>';
}

// ═══════════════════════════════════════════════════════════════
// SLEEVE ENGINE - true blended per-sector performance
// ═══════════════════════════════════════════════════════════════
function holdingMoves(){
  var map = {};
  var hp = dv('holdingsPerf', null);
  if (Array.isArray(hp)){
    hp.forEach(function(h){
      var t = String(h.symbol||'').toUpperCase();
      if (t) map[t] = h.perf || {};
    });
  }
  var qs = dv('quotes', []) || [];
  qs.forEach(function(q){
    var t = String(q.symbol||'').toUpperCase(); if (!t) return;
    var today = num(q.changesPercentage); if (today===null) today = num(q.changePercent); if (today===null) today = num(q.changePct);
    if (!map[t]) map[t] = {};
    if ((map[t].today===null || map[t].today===undefined) && today!==null) map[t].today = today;
  });
  return map;
}
function fallbackContrib(){
  var profs = dv('profiles.profilesByTicker', {}) || {};
  var qs = dv('quotes', []) || [];
  var anyW = qs.some(function(q){ return num(q.weightPct)!==null; });
  var out = {};
  qs.forEach(function(q){
    var t = String(q.symbol||'').toUpperCase();
    var p = profs[t] || {};
    if (p.isEtf === true) return;
    var s = normSectorName(p.sector || null);
    if (!s) return;
    var w = anyW ? (num(q.weightPct)||0) : 1;
    if (!out[s]) out[s] = [];
    out[s].push({ symbol: t, w: w });
  });
  return { contrib: out, partial: true };
}
// Contribution lists, optionally scoped to one mandate. A null/absent mandate,
// or a payload that carries no per-mandate split, falls all the way back to the
// combined book — so a single-portfolio advisor takes the identical path it
// always did and never notices this parameter exists.
function getContrib(mandateName){
  if (mandateName){
    var byM = dv('sectorContribByMandate', null);
    if (byM && typeof byM === 'object'){
      var mine = byM[mandateName];
      if (mine && typeof mine === 'object' && Object.keys(mine).length) return { contrib: mine, partial: false };
    }
  }
  var sc = dv('sectorContrib', null);
  if (sc && typeof sc === 'object' && Object.keys(sc).length) return { contrib: sc, partial: false };
  return fallbackContrib();
}

// Sector exposure rows, same scoping rule as getContrib.
function getSectorExposure(mandateName){
  if (mandateName){
    var byM = dv('sectorExposureByMandate', null);
    if (byM && typeof byM === 'object' && Array.isArray(byM[mandateName]) && byM[mandateName].length){
      return byM[mandateName];
    }
  }
  return dv('sectorExposure', null);
}
function sleevePerf(contribList, moves, field){
  var wsum=0, used=0, acc=0;
  (contribList||[]).forEach(function(c){
    var w = num(c.w); if (w===null || w<=0) return;
    wsum += w;
    var m = moves[String(c.symbol||'').toUpperCase()];
    var v = m ? num(m[field]) : null;
    if (v===null) return;
    used += w; acc += w * v;
  });
  if (used <= 0 || wsum <= 0) return { v: null, cov: 0 };
  return { v: acc/used, cov: Math.round((used/wsum)*100) };
}

// ═══════════════════════════════════════════════════════════════
// SECTOR BLOCK - hypo strip + blended sleeve drawers
