  if (!cols.length) return '';
  function bench(f){ if (b && num(b[f])!==null) return num(b[f]); if (f==='today' && spxToday!==null) return spxToday; return null; }
  function cell(v){ var s = signedPct(v); if (s===null) return '<td class="cmp-c cmp-na">·</td>';
    return '<td class="cmp-c ' + updn(v) + '">' + s + '</td>'; }
  var out = '<div class="hist"><div class="hist-lbl">📐 Your Portfolio, Historically · Current Mix vs the S&amp;P 500</div>'
