function cmpTable(sleeveVals, benchPerf, benchLabel){
  var COLS = [['m1','1M'],['m3','3M'],['m6','6M'],['ytd','YTD'],['y1','1Y']];
  var cols = COLS.filter(function(c){
    var sv = sleeveVals[c[0]], bv = benchPerf ? num(benchPerf[c[0]]) : null;
    return (sv!==null && sv!==undefined) || (bv!==null);
  });
  if (!cols.length) return '';
