  }
  var h = '<table class="cmp"><tr><th class="cmp-h"></th>';
  cols.forEach(function(c){ h += '<th class="cmp-k">' + c[1] + '</th>'; });
  h += '</tr><tr><th class="cmp-h cmp-you">Your sleeve</th>';
  cols.forEach(function(c){ h += cell(sleeveVals[c[0]]); });
  h += '</tr><tr><th class="cmp-h">' + esc(benchLabel) + '</th>';
  cols.forEach(function(c){ h += cell(benchPerf ? num(benchPerf[c[0]]) : null); });
  h += '</tr></table>';
  return h;
}
// mandateName is optional. When given AND the payload carries a split for it,
// every figure in the block is that mandate's own. When absent — the ordinary
// single-book case — this is the combined-book builder it has always been.
function buildSectorRows(reads, mandateName){
  var rows = getSectorExposure(mandateName);
  if (!Array.isArray(rows) || !rows.length) return '';
  var cd = getContrib(mandateName);
  var moves = holdingMoves();

  function model(r){
    var name = r.sector || '-';
    var isOther = /^other$/i.test(name);
    var contribList = cd.contrib[name] || null;
    var benchToday = (r.move!==null && r.move!==undefined) ? Number(r.move) : (r.perf ? num(r.perf.today) : null);
    var spdrT = r.spdr || SECTOR_TO_SPDR[name] || null;
    var sToday = contribList ? sleevePerf(contribList, moves, 'today') : { v:null, cov:0 };
    var sleeveVals = {};
    ['m1','m3','m6','ytd','y1'].forEach(function(f){
      var sp = contribList ? sleevePerf(contribList, moves, f) : { v:null, cov:0 };
      sleeveVals[f] = sp.v===null ? null : Math.round(sp.v*100)/100;
    });
    var youV = sToday.v===null ? null : Math.round(sToday.v*100)/100;
    var gapBp = (youV!==null && benchToday!==null) ? Math.round((youV-benchToday)*100) : null;
    var relevance = 0;
    if (gapBp!==null) relevance += Math.abs(gapBp);
