      spdrT:spdrT, sToday:sToday, sleeveVals:sleeveVals, youV:youV, gapBp:gapBp,
      relevance:relevance, perf:r.perf||null, pct:r.pct };
  }
  var models = rows.map(model);

  function rowHtml(m, openDrawer){
    var cols;
    var etfLbl = m.spdrT ? 'Sector ETF (' + m.spdrT + ')' : 'Benchmark';
    if (m.youV!==null && m.benchToday!==null){
      var d = m.gapBp;
      var dTxt = (Math.abs(d) > 100)
        ? (d>=0?'+':'') + (d/100).toFixed(2) + '%'
        : (d>=0?'+':'') + d + 'bp';
      cols = '<div class="svs-cmp">'
        + '<div class="svs-cell svs-you"><span class="svs-k">Your sleeve</span><span class="svs-v ' + updn(m.youV) + '">' + signedPct(m.youV) + '</span></div>'
        + '<div class="svs-cell"><span class="svs-k">' + etfLbl + '</span><span class="svs-v ' + updn(m.benchToday) + '">' + signedPct(m.benchToday) + '</span></div>'
        + '<div class="svs-delta ' + (d>=0?'beat':'lag') + '"><span class="svs-k">Gap</span><span class="svs-v">' + dTxt + '</span></div>'
        + '</div>';
    } else if (m.benchToday!==null){
      cols = '<div class="svs-cmp"><div class="svs-cell"><span class="svs-k">' + (m.spdrT?etfLbl:'Today') + '</span><span class="svs-v ' + updn(m.benchToday) + '">' + signedPct(m.benchToday) + '</span></div></div>';
    } else {
