  }

  var seeAll = mandateName
    ? ('See all ' + esc(mandateName) + ' sectors + this mandate\'s mix vs the S&amp;P 500')
    : 'See all your sectors + your mix vs the S&amp;P 500';

  var html = '<div class="sector-box' + (mandateName ? ' sector-box-mandate' : '') + '"'
