// Sector reads, scoped to the mandate they were written about.
//
// The old map was keyed on sector alone and first-wins, so when two mandates
// both held a sector the second read was silently discarded: on this brief the
// House Technology read ("AAPL added 0.29%... 25% of the mandate") lost to the
// Roth IRA Technology read and never reached the page. A read is about one
// book, so it has to be keyed by (mandate, sector).
//
// svs-read carries no data-mandate of its own — it sits inside a mandate
// wrapper — so attribution is positional: a read belongs to the last mandate
// wrapper opened before it, and a wrapper's reach ends at the next wrapper or
// the next section header, whichever comes first. Reads outside any wrapper
// stay unscoped, which is every read in a single-portfolio brief.
function extractReads(html){
  var s = String(html);

  var regions = [];
  var wre = /<div class="mandate"[^>]*data-mandate="([^"]*)"[^>]*>/gi, wm;
  while ((wm = wre.exec(s)) !== null) regions.push({ name: wm[1].trim(), start: wm.index });
  regions.forEach(function(r, i){
    var next = (i + 1 < regions.length) ? regions[i + 1].start : s.length;
    var sec = s.indexOf('<div class="sec-num"', r.start + 1);
    r.end = (sec !== -1 && sec < next) ? sec : next;
  });
