  var re = /<div class="svs-read"[^>]*data-sector="([^"]*)"[^>]*>([\s\S]*?)<\/div>\s*/gi;
  var out = s.replace(re, function(m, sector, body, offset){
    var key = String(sector).trim().toLowerCase();
    if (!key) return '';
