// A mandate block prefers its own read and falls back to an unscoped one. A
// combined block uses unscoped reads only — lifting one mandate's read into the
// combined block would attribute it to the whole book.
function readFor(reads, mandateName, sectorName){
  if (!reads) return '';
  var key = String(sectorName == null ? '' : sectorName).trim().toLowerCase();
  if (!key) return '';
