    return reads.byMandate[mandateName][key];
  }
  if (reads.global && reads.global[key]) return reads.global[key];
  // On a dual-mandate brief the prompt forbids combined-level svs-read lines, so
  // every read the agent writes lives inside a mandate wrapper and lands in
  // byMandate. Building the combined table with mandateName=null and consulting
  // only reads.global silently deleted every sector read on a multi-book brief.
  // The combined table now surfaces the per-mandate reads: one read renders
  // plain; two render stacked, each under a small mandate chip, because the Roth
  // read on Technology and the House read on Technology are genuinely different
  // reads.
  if (!mandateName && reads.byMandate){
    var parts = [];
    Object.keys(reads.byMandate).forEach(function(mn){
      var t = reads.byMandate[mn] && reads.byMandate[mn][key];
      if (t) parts.push({ mn: mn, t: t });
    });
    if (parts.length === 1) return parts[0].t;
    if (parts.length > 1){
      return parts.map(function(pp){
        return '<div class="svs-mread"><span class="svs-mchip">' + esc(pp.mn) + '</span> ' + pp.t + '</div>';
