// 1 · MANDATE RESOLUTION
// Reads the future `mandates` payload if it exists. Returns a single
// synthetic mandate when it does not, so every function below has one
// code path instead of two.
// ══════════════════════════════════════════════════════════════════════
function v19Mandates(){
  var m = dv('mandates', null);
  if (m && m.isMulti === true && Array.isArray(m.portfolios) && m.portfolios.length > 1){
    return {
      isMulti: true,
      list: m.portfolios.map(function(p){
        return { name: String(p.name || 'Portfolio'), weight: num(p.weight) };
      }).sort(function(a,b){ return (b.weight||0) - (a.weight||0); })
    };
  }
  return { isMulti: false, list: [{ name: null, weight: null }] };
}

// Which tickers belong to a mandate. Null mandate means "everything".
function v19HoldingsFor(mandateName){
  var all = dv('holdingsPerf', null);
  if (!Array.isArray(all)) return [];
  if (!mandateName) return all;
  var byM = dv('holdingsByMandate', null);
  if (!byM || typeof byM !== 'object') return all;
  var syms = byM[mandateName];
  if (Array.isArray(syms) && syms.length && typeof syms[0] === 'object'){
    syms = syms.map(function(x){ return String(x.symbol || x.Ticker || '').toUpperCase(); });
  }
  if (!Array.isArray(syms) || !syms.length) return all;
  var set = {};
  syms.forEach(function(s){ set[String(s).toUpperCase()] = 1; });
  return all.filter(function(h){ return set[String(h.symbol||'').toUpperCase()]; });
}

// Per-mandate hypothetical return, when the payload carries one.
function v19HypoFor(mandateName){
  if (!mandateName) return dv('hypoBookReturn', null);
  var byM = dv('hypoBookReturnByMandate', null);
  if (byM && typeof byM === 'object' && byM[mandateName]) return byM[mandateName];
  return dv('hypoBookReturn', null);
}


