      + '</div>';
  });
  if (!live) return '';

  var title = mandateName
    ? ('Portfolio Performance Report · ' + esc(mandateName))
    : 'Portfolio Performance Report';
  // v20: today lives ONLY in the masthead Book Move. This board is trailing windows.

  var cov = (h.coveragePct != null)
    ? ' Covers ' + h.coveragePct + '% of the book.' : '';

  return '<div class="pscore">'
    + '<div class="pscore-bar">📊 ' + title + '</div>'
    + '<div class="pscore-grid">' + cards + '</div>'
    + '<div class="pscore-note">Current-weight hypothetical: today\'s exact mix applied backward. '
    + '<b>Not realized performance.</b>' + cov + '</div>'
    + buildPortfolioAnalytics(mandateName, h, hasQQQ ? q : null, b, qLabel)
    + '</div>';
}


// ══════════════════════════════════════════════════════════════════════
// 2b · MORE PORTFOLIO ANALYTICS
// The gold drawer under the report. Everything here is drawn from the
// payload — a grouped bar chart of book vs the two benchmarks, then the
// names actually driving it: best, worst, and the ones trailing their own
// sector. Numbers and bars, not paragraphs. Returns '' when the payload
// carries nothing to draw, so the button never opens onto an empty box.
// ══════════════════════════════════════════════════════════════════════

// Grouped bars, one group per window. Today is deliberately excluded: at
// well under a percent against a 1Y bar it renders as a 1px stub and reads
// as missing data. The cards above already lead with Today.
function paChart(h, b, q, qLabel){
  var W = [['m1','1M'],['m3','3M'],['m6','6M'],['ytd','YTD'],['y1','1Y']];
  var series = [{ k:'book', lbl:'Book', src:h, cls:'pac-book' },
                { k:'spx',  lbl:'S&P 500', src:b, cls:'pac-spx' }];
  if (q) series.push({ k:'qqq', lbl:qLabel, src:q, cls:'pac-qqq' });
  // Drop any series with nothing to draw in these windows. A payload can carry
  // a same-day index move but no history (no benchmarkPerfQQQ), which would
  // otherwise put a benchmark in the legend that has no bars anywhere.
  series = series.filter(function(s){
    return W.some(function(w){ return num(s.src ? s.src[w[0]] : null) !== null; });
  });
  if (series.length < 2) return '';

  var groups = [];
  W.forEach(function(w){
    var vals = series.map(function(s){ return num(s.src ? s.src[w[0]] : null); });
    if (vals.every(function(v){ return v === null; })) return;
    groups.push({ key:w[1], vals:vals });
  });
  if (!groups.length) return '';

  var peak = 0;
  groups.forEach(function(g){ g.vals.forEach(function(v){ if (v !== null && Math.abs(v) > peak) peak = Math.abs(v); }); });
  if (peak <= 0) return '';

  // Line chart: one polyline per series through the window points, with a dot
  // and a value at each. preserveAspectRatio is left at its default so the
  // strokes and text keep their proportions when the SVG is scaled to width.
  var VW = 620, VH = 210, PAD_L = 34, PAD_R = 14, PAD_B = 28, PAD_T = 22;
  var plotW = VW - PAD_L - PAD_R, plotH = VH - PAD_B - PAD_T;

  var minV = 0, maxV = 0;
  groups.forEach(function(g){ g.vals.forEach(function(v){ if (v===null) return; if (v<minV) minV=v; if (v>maxV) maxV=v; }); });
  var pad = (maxV - minV) * 0.12 || 1;
  minV -= pad; maxV += pad;
  var span = (maxV - minV) || 1;

  function xAt(i){ return PAD_L + (groups.length === 1 ? plotW/2 : (plotW * i) / (groups.length - 1)); }
  function yAt(v){ return PAD_T + ((maxV - v) / span) * plotH; }

  var zeroY = yAt(0);
  var lines = '', dots = '', labels = '';

  series.forEach(function(s, si){
    var pts = [];
    groups.forEach(function(g, gi){
      var v = g.vals[si];
      if (v === null) return;
      pts.push(xAt(gi).toFixed(1) + ',' + yAt(v).toFixed(1));
      dots += '<circle class="' + s.cls + '-dot" cx="' + xAt(gi).toFixed(1) + '" cy="' + yAt(v).toFixed(1) + '" r="3.5"></circle>';
    });
    if (pts.length > 1) lines += '<polyline class="' + s.cls + '-line" points="' + pts.join(' ') + '"></polyline>';
  });

  // Value labels for the book line only — three overlapping sets is noise.
  groups.forEach(function(g, gi){
    var v = g.vals[0];
    if (v !== null) labels += '<text class="pac-val" x="' + xAt(gi).toFixed(1) + '" y="' + (yAt(v) - 9).toFixed(1) + '" text-anchor="middle">' + signedPct(v, 1) + '</text>';
    labels += '<text class="pac-x" x="' + xAt(gi).toFixed(1) + '" y="' + (VH - 9) + '" text-anchor="middle">' + esc(g.key) + '</text>';
  });

  var legend = series.map(function(s){
    return '<span class="pac-key"><i class="' + s.cls + '"></i>' + esc(s.lbl) + '</span>';
  }).join('');

  return '<div class="pac">'
    + '<div class="pac-h">Book vs benchmarks — cumulative return by window</div>'
    + '<svg class="pac-svg" viewBox="0 0 ' + VW + ' ' + VH + '" role="img" aria-label="Book versus benchmarks by window">'
    +   (zeroY > PAD_T && zeroY < PAD_T + plotH
          ? '<line class="pac-zero" x1="' + PAD_L + '" y1="' + zeroY.toFixed(1) + '" x2="' + (VW - PAD_R) + '" y2="' + zeroY.toFixed(1) + '"></line>'
          : '')
    +   lines + dots + labels
    + '</svg>'
    + '<div class="pac-legend">' + legend + '</div>'
    + '</div>';
}

// One ranked list: ticker, weight, the ranking figure, and a bar.
function paRows(items, field, peak){
  return items.map(function(it){
    var v = it.v;
    var pct = peak > 0 ? Math.max(4, Math.min(100, (Math.abs(v) / peak) * 100)) : 4;
    var wt = (it.w === null || it.w === undefined) ? '' : '<span class="pal-w">' + (Math.round(it.w * 10) / 10) + '%</span>';
    return '<div class="pal-row">'
      + '<div class="pal-tk">' + esc(it.sym) + wt + '</div>'
      + '<div class="pal-track"><div class="pal-fill ' + updn(v) + '" style="width:' + pct.toFixed(1) + '%"></div></div>'
      + '<div class="pal-v ' + updn(v) + '">' + (it.txt || signedPct(v)) + '</div>'
      + (it.note ? '<div class="pal-note">' + it.note + '</div>' : '')
      + '</div>';
  }).join('');
}

// Best and worst position in EACH window, as one diverging bar chart. Three
// stacked boxes of ranked numbers answered "who won over one window"; this
// answers "who won and who lost, over every window", which is the question.
// Today is excluded — a single session says nothing about a position.
function paWinnersLosers(rows){
  var W = [['m1','1M'],['m3','3M'],['m6','6M'],['ytd','YTD'],['y1','1Y']];
  var out = [], peak = 0;

  W.forEach(function(w){
    var best = null, worst = null;
    rows.forEach(function(r){
      var v = num(r.perf ? r.perf[w[0]] : null);
      var sym = String(r.symbol || '').toUpperCase();
      if (v === null || !sym) return;
      if (!best  || v > best.v)  best  = { sym: sym, v: v };
      if (!worst || v < worst.v) worst = { sym: sym, v: v };
    });
    if (!best && !worst) return;
    if (best  && best.sym === (worst && worst.sym)) worst = null;   // only one name priced
    [best, worst].forEach(function(x){ if (x) peak = Math.max(peak, Math.abs(x.v)); });
    out.push({ k: w[1], best: best, worst: worst });
  });
  if (!out.length || peak <= 0) return '';

  function side(x, cls){
    if (!x) return '<div class="wlc-' + cls + '"></div>';
    // Cap at 74%: the longest bar is the peak by definition, and at 100% it
    // leaves no room for its own label, which then clips off the edge.
    var pct = Math.max(5, Math.min(74, (Math.abs(x.v) / peak) * 74));
    var lbl = '<span class="wlc-lbl">' + esc(x.sym) + ' <b class="' + updn(x.v) + '">' + signedPct(x.v, 1) + '</b></span>';
    var bar = '<div class="wlc-bar ' + updn(x.v) + '" style="width:' + pct.toFixed(1) + '%"></div>';
    return '<div class="wlc-' + cls + '">' + (cls === 'neg' ? lbl + bar : bar + lbl) + '</div>';
  }

  return '<div class="wlc">'
    + '<div class="pac-h">Best and worst position in each window</div>'
    + '<div class="wlc-rows">'
    + out.map(function(r){
        return '<div class="wlc-row">' + side(r.worst, 'neg')
          + '<div class="wlc-k">' + esc(r.k) + '</div>'
          + side(r.best, 'pos') + '</div>';
      }).join('')
    + '</div></div>';
}

function paList(title, sub, items, peak){
  if (!items.length) return '';
  return '<div class="pal">'
    + '<div class="pal-h">' + title + (sub ? '<span class="pal-sub">' + sub + '</span>' : '') + '</div>'
    + paRows(items, null, peak)
    + '</div>';
}

// Per-mandate comparison, drawer-only. Each portfolio and the blend as rows,
// windows as columns — the "Roth IRA vs House" view, without giving each book
// a whole section of its own out on the page.
function paMandateTable(b, q, qLabel){
  var mand = v19Mandates();
  if (!mand.isMulti) return '';
  var W = PERF_WINDOWS;

  var rows = mand.list.map(function(p){ return { name: p.name, src: v19HypoFor(p.name), cls: '' }; });
  rows.push({ name: 'Blended book', src: v19HypoFor(null), cls: 'pmt-blend' });
  rows.push({ name: 'S&P 500', src: b || {}, cls: 'pmt-bench' });
  if (q) rows.push({ name: qLabel, src: q, cls: 'pmt-bench' });

  var cols = W.filter(function(w){
    return rows.some(function(r){ return num(r.src ? r.src[w[0]] : null) !== null; });
  });
  if (!cols.length) return '';

  var head = '<tr><th class="pmt-h"></th>' + cols.map(function(w){
    return '<th class="pmt-k">' + w[1] + '</th>';
  }).join('') + '</tr>';

  var body = rows.map(function(r){
    return '<tr class="' + r.cls + '"><th class="pmt-h">' + esc(r.name) + '</th>'
      + cols.map(function(w){
          var v = num(r.src ? r.src[w[0]] : null);
          return v === null ? '<td class="pmt-c pmt-na">·</td>'
                            : '<td class="pmt-c ' + updn(v) + '">' + signedPct(v) + '</td>';
        }).join('')
      + '</tr>';
  }).join('');

  return '<div class="pmt-wrap"><div class="pac-h">Each portfolio against the benchmarks</div>'
    + '<table class="pmt">' + head + body + '</table></div>';
}

function buildPortfolioAnalytics(mandateName, h, q, b, qLabel){
  var rows = v19HoldingsFor(mandateName);
  var chart = paChart(h, b, q, qLabel);
  var mtable = paMandateTable(b, q, qLabel);

  // Movers boards removed entirely: three of them (combined + one per mandate)
  // restated today's move that the report already leads with, and the two
  // per-mandate ones were the last thing on the page still reading as a
  // "Roth IRA section" and a "House section".
  var movers = '';

  // Pick the longest window the data actually supports, so the ranking is not
  // dominated by a single session.
  var RANK = ['y1','ytd','m6','m3','m1'];
  var field = null;
  for (var i = 0; i < RANK.length; i++){
    var f = RANK[i];
    if (rows.some(function(r){ return r.perf && num(r.perf[f]) !== null; })) { field = f; break; }
  }
  var LBL = { y1:'1Y', ytd:'YTD', m6:'6M', m3:'3M', m1:'1M' };

  var best = [], worst = [], lag = [];
  if (field){
    var pool = rows.map(function(r){
      return { sym: String(r.symbol||'').toUpperCase(), v: num(r.perf ? r.perf[field] : null),
               w: num(r.weightPct), sector: r.sector || null };
    }).filter(function(x){ return x.sym && x.v !== null; });

    pool.sort(function(a,c){ return c.v - a.v; });
    best  = pool.slice(0, 3);
    worst = pool.slice(-3).reverse();

    // Trailing their own sector: holding return minus that sector's return over
    // the same window. Needs sectorExposure, which carries per-sector perf.
    var secPerf = {};
    var se = getSectorExposure(mandateName);
    if (Array.isArray(se)) se.forEach(function(s){
      var v = s.perf ? num(s.perf[field]) : null;
      if (s.sector && v !== null) secPerf[String(s.sector).toLowerCase()] = v;
    });
    lag = pool.map(function(x){
      var sv = x.sector ? secPerf[String(x.sector).toLowerCase()] : undefined;
      if (sv === undefined || sv === null) return null;
      // This is a GAP, in percentage points — not a return. Labelling it with a
      // % sign would read as "MSTR fell 117%", which is not what it says.
      var gap = Math.round((x.v - sv) * 100) / 100;
      return { sym: x.sym, w: x.w, v: gap,
               txt: (gap >= 0 ? '+' : '−') + Math.abs(gap).toFixed(1) + 'pp',
               note: esc(x.sector) + ' ' + signedPct(sv) + ' · ' + esc(x.sym) + ' ' + signedPct(x.v) };
    }).filter(Boolean).filter(function(x){ return x.v < 0; })
      .sort(function(a,c){ return a.v - c.v; }).slice(0, 3);
  }

  function peakOf(a){ var p = 0; a.forEach(function(x){ if (Math.abs(x.v) > p) p = Math.abs(x.v); }); return p; }
  var wl = paWinnersLosers(rows);
  var lists = paList('Trailing their sector', field ? (LBL[field] + ' gap') : '', lag, peakOf(lag));

  if (!chart && !lists && !mtable && !wl) return '';

  return '<details class="pa">'
    + '<summary><span class="pa-btn">More Portfolio Analytics <span class="pa-chev">▼</span></span></summary>'
    + '<div class="pa-body">'
    +   chart
    +   mtable
    +   wl
    +   (lists ? '<div class="pa-lists">' + lists + '</div>' : '')
    + '</div>'
    + '</details>';
}


// ══════════════════════════════════════════════════════════════════════
// 3 · MOVERS BOARD
// Biggest winners and losers today, as weighted horizontal bars. Bars are
// scaled to the largest absolute move on the board so the shape is honest.
// Weight badge appears only when the book is actually weighted.
// ══════════════════════════════════════════════════════════════════════
function buildMoversBoard(mandateName){
  var rows = v19HoldingsFor(mandateName);
  if (!rows.length) return '';

  var moves = [];
  rows.forEach(function(h){
    var sym = String(h.symbol || '').toUpperCase();
    var t = (h.perf && num(h.perf.today) !== null) ? num(h.perf.today) : null;
    if (!sym || t === null) return;
    moves.push({ sym: sym, v: t, w: num(h.weightPct), etf: h.isEtf === true });
  });
  if (moves.length < 2) return '';

  moves.sort(function(a,b){ return b.v - a.v; });

  var N = moves.length >= 8 ? 3 : 2;
  var ups = moves.filter(function(m){ return m.v > 0; }).slice(0, N);
  var downs = moves.filter(function(m){ return m.v < 0; }).slice(-N).reverse();
  if (!ups.length && !downs.length) return '';

  var peak = 0;
  ups.concat(downs).forEach(function(m){ if (Math.abs(m.v) > peak) peak = Math.abs(m.v); });
  if (peak <= 0) peak = 1;

  var weighted = /weight/i.test(String(dv('bookMoveBasis','') || ''));

  function bar(m, dir){
    var pct = Math.max(6, Math.min(100, (Math.abs(m.v) / peak) * 100));
    var wtxt = (weighted && m.w !== null) ? '<span class="mvb-w">' + (Math.round(m.w * 10) / 10) + '%</span>' : '';
    return '<div class="mvb-row">'
      + '<div class="mvb-tk">' + esc(m.sym) + wtxt + '</div>'
      + '<div class="mvb-track"><div class="mvb-fill ' + dir + '" style="width:' + pct.toFixed(1) + '%"></div></div>'
      + '<div class="mvb-v ' + dir + '">' + signedPct(m.v) + '</div>'
      + '</div>';
  }

  var body = '';
  if (ups.length){
    body += '<div class="mvb-side mvb-up"><div class="mvb-h">▲ Carrying the day</div>'
      + ups.map(function(m){ return bar(m, 'up'); }).join('') + '</div>';
  }
  if (downs.length){
    body += '<div class="mvb-side mvb-dn"><div class="mvb-h">▼ Costing the day</div>'
      + downs.map(function(m){ return bar(m, 'dn'); }).join('') + '</div>';
  }

  var title = mandateName
    ? ('Movers in ' + esc(mandateName))
    : 'Today\'s Movers in Your Book';

  return '<div class="mvb">'
    + '<div class="mvb-bar">📈 ' + title + '</div>'
    + '<div class="mvb-body">' + body + '</div>'
    + (weighted ? '<div class="mvb-note">Bars scale to the largest move shown. Badge is the position\'s weight.</div>'
                : '<div class="mvb-note">Bars scale to the largest move shown.</div>')
    + '</div>';
}


// ══════════════════════════════════════════════════════════════════════
// 4 · MARKER PLACEMENT
// Replaces every <div class="perf-here"> and <div class="movers-here">,
// honouring an optional data-mandate. Unmatched markers are deleted so a
// stray one never renders as an empty box.
// ══════════════════════════════════════════════════════════════════════
function placeScoreboards(html){
  var out = String(html);
  var placed = 0;

  // ONE Performance Report for the whole book. The first bare marker wins; a
  // mandate-scoped marker no longer builds a second full report, because giving
  // each portfolio its own section was the single biggest consumer of space in
  // Portfolio Spotlight. Every per-portfolio figure now lives one click down,
  // inside More Portfolio Analytics.
  out = out.replace(/<div class="perf-here"(?:\s+data-mandate="([^"]*)")?\s*>\s*<\/div>/gi,
    function(m, mn){
      if (placed) return '';                       // already have the report
      var block = buildPerfScoreboard(null);       // always the combined book
      if (block) placed++;
      return block;
    });

  // The Movers Board is no longer a section of its own — it is inside the
  // analytics drawer. Drop every marker the agent wrote for it.
  out = out.replace(/<div class="movers-here"(?:\s+data-mandate="([^"]*)")?\s*>\s*<\/div>/gi, '');

  // Fallback: the agent forgot the markers entirely. Inject the report at the
  // top of Portfolio Spotlight so the reader never loses it.
  if (!placed){
    var pair = buildPerfScoreboard(null);
    if (pair){
      if (/<div class="sec-title">Portfolio Spotlight<\/div>/i.test(out)){
        out = out.replace(/(<div class="sec-title">Portfolio Spotlight<\/div>\s*)/i,
          function(_, g1){ return g1 + pair; });   // function form: pair is inert
        placed++;
      } else if (/<div class="sector-box">/i.test(out)){
        out = out.replace(/<div class="sector-box">/i,
          function(){ return pair + '<div class="sector-box">'; });   // function form
        placed++;
      }
    }
  }

  // Kill any leftover markers.
  out = out.replace(/<div class="(?:perf-here|movers-here)"[^>]*>\s*<\/div>/gi, '');

  return placed ? '<div class="has-scoreboard">' + out + '</div>' : out;
}


// ══════════════════════════════════════════════════════════════════════
// 5 · MANDATE HEADERS
// Turns <div class="mandate" data-mandate data-weight> into a titled panel.
// Does nothing at all when the agent emitted no mandate wrappers, which is
// every single-portfolio run.
// ══════════════════════════════════════════════════════════════════════
function decorateMandates(html){
  var s = String(html);
  if (!/<div class="mandate"/i.test(s)) return s;

  return s.replace(/<div class="mandate"([^>]*)>/gi, function(m, attrs){
    var nm = (attrs.match(/data-mandate="([^"]*)"/i) || [null,''])[1];
    var wt = (attrs.match(/data-weight="([^"]*)"/i) || [null,''])[1];
    if (!nm) return m;
    var w = num(wt);
    var badge = (w !== null)
      ? '<span class="mnd-w">' + (Math.round(w * 10) / 10) + '% of the combined book</span>'
      : '';
    return '<div class="mandate"' + attrs + '>'
      + '<div class="mnd-bar"><span class="mnd-nm">' + esc(nm) + '</span>' + badge + '</div>';
  });
}


// ══════════════════════════════════════════════════════════════════════
// 6 · WATCHLIST VALUATION SCRUBBER
// The last line of defence against the failure that shipped a 450% implied
// upside. Any consensus target, implied upside, or price attached to a name
// that is NOT in the holdings list gets deleted at render time, whatever the
// model wrote and whatever the prompt said.
// ══════════════════════════════════════════════════════════════════════
function scrubWatchlistValuation(html){
  // ---- who is actually held ----
  var held = {};
  (function(){
    function flat(x){
      var out = [];
      if (Array.isArray(x)) x.forEach(function(el){
        if (Array.isArray(el)) el.forEach(function(s){ if (s) out.push(String(s).toUpperCase().trim()); });
        else if (el) out.push(String(el).toUpperCase().trim());
      });
      return out;
    }
    flat(dv('Ticker', null)).forEach(function(t){ held[t] = 1; });
    var hp = dv('holdingsPerf', null);
    if (Array.isArray(hp)) hp.forEach(function(h){
      var s = String(h.symbol||'').toUpperCase(); if (s) held[s] = 1;
    });
  })();
  if (!Object.keys(held).length) return String(html);

  var NOT_TICKERS = { AI:1, CEO:1, CFO:1, COO:1, CTO:1, ETF:1, GDP:1, CPI:1, PPI:1, PCE:1,
    FOMC:1, SEC:1, OAS:1, RSI:1, EPS:1, YTD:1, IPO:1, USD:1, USA:1, EU:1, UK:1, US:1, PMI:1,
    ISM:1, HY:1, IG:1, TBD:1, AND:1, THE:1, FOR:1, NOT:1, BUT:1, ONE:1, TWO:1, ALL:1, NEW:1 };

  function badTickersIn(text){
    var t = text.match(/\b[A-Z]{2,5}\b/g) || [];
    var bad = [];
    t.forEach(function(x){ if (!NOT_TICKERS[x] && !held[x] && bad.indexOf(x) === -1) bad.push(x); });
    return bad;
  }

  // Valuation language that may never attach to a name this reader does not hold.
  var VAL_RE = /(consensus target|price target consensus|implied upside|to consensus|% upside|percent upside|target of \$|upside to consensus)/i;

  // Decimal-safe sentence split: a period only ends a sentence when the next
  // visible character is a capital letter or a tag. $110.41 stays one sentence.
  function sentences(text){
    return text.split(/(?<=[.!?])(\s+)(?=[A-Z<"'\u201c])/).reduce(function(acc, part, i){
      if (i % 2 === 1) { acc[acc.length-1] += part; } else { acc.push(part); }
      return acc;
    }, []);
  }

  var s = String(html);

  // Work block by block so a ticker named in one sentence still governs the next.
  // ONLY p and li: those never nest, so the block stays tight. Matching div here
  // would swallow a whole card and let one bad ticker delete good sentences about
  // held names sitting in the same container.
  s = s.replace(/(<(p|li)[^>]*>)([\s\S]*?)(<\/\2>)/gi, function(m, open, tag, body, close){
    if (!VAL_RE.test(body)) return m;
    var plain = body.replace(/<[^>]*>/g, ' ');
    var bad = badTickersIn(plain);
    if (!bad.length) return m;

    // Drop only the sentences carrying the valuation language. Keep the rest.
    var kept = sentences(body).filter(function(sent){ return !VAL_RE.test(sent); });
    var out = kept.join('').replace(/\s{2,}/g, ' ').trim();

    // Tidy anything the removal left dangling.
    out = out.replace(/^[,;:\s]+/, '').replace(/[,;:]\s*$/, '.');
    if (!out || out.replace(/<[^>]*>/g, '').trim().length < 12) return '';
    return open + out + close;
  });

  // Second pass for valuation language that lives OUTSIDE a p or li, for example
  // loose text inside a desk-block. Works sentence by sentence with a lookback
  // window, so a ticker named just before the figure still governs it.
  s = s.replace(/([^<>]{0,220})/g, function(chunk){
    if (!VAL_RE.test(chunk)) return chunk;
    var kept = sentences(chunk).filter(function(sent){
      if (!VAL_RE.test(sent)) return true;
      var ctxStart = Math.max(0, chunk.indexOf(sent) - 140);
      var ctx = chunk.slice(ctxStart, chunk.indexOf(sent) + sent.length);
      return badTickersIn(ctx).length === 0;
    });
    return kept.join('');
  });

  // Belt and braces: any surviving "NNN% upside" or "+NNN% to consensus" that
  // still sits beside a non-held ticker gets the figure removed outright.
  s = s.replace(/[^<>]{0,160}?(?:\d{1,4}(?:\.\d+)?%\s*(?:implied\s*)?upside|implied upside[^<>]{0,24}?\d{1,4}(?:\.\d+)?%|[+\-\u2212]?\d{1,4}(?:\.\d+)?%\s*to consensus)[^<>]{0,60}/gi,
    function(chunk){
      return badTickersIn(chunk).length ? '' : chunk;
    });

  // Round-number price guard: "$20.00" is nearly always a parse failure.
  s = s.replace(/\bis \$(\d{1,4})\.00\b/g, 'is trading');
  s = s.replace(/\bat \$(\d{1,4})\.00\b/g, 'at current levels');

  // Clean empty shells the removals may have left.
  s = s.replace(/<p[^>]*>\s*<\/p>/gi, '');

  return s;
}

