.po-role{font-size:10.5px;color:#999;font-style:italic;margin-left:2px}
.po-body{font-size:13.5px;color:#333b47;line-height:1.65}
.people-minor{display:grid;grid-template-columns:1fr 1fr;gap:10px}

/* premortem */
.premortem{background:linear-gradient(135deg,#1a0e0e,#1c1215);border:1px solid rgba(201,42,42,.3);border-radius:13px;padding:22px 24px;margin-bottom:13px;color:rgba(238,242,252,.9)}
.premortem .pm-label{font-size:9.5px;font-weight:800;letter-spacing:2.5px;color:#f87171;text-transform:uppercase;margin-bottom:6px;display:block}
.premortem .pm-title{font-family:var(--serif);font-size:20px;color:#fff;margin-bottom:15px;font-weight:600;line-height:1.3}
.pm-foot{margin-top:14px;padding-top:12px;border-top:1px solid rgba(201,42,42,.2);font-size:12.5px;color:rgba(238,242,252,.72);line-height:1.58}.pm-foot b{color:#fca5a5}

/* scenarios */
.scen{border-radius:13px;overflow:hidden;margin-bottom:12px;border:1px solid var(--line);box-shadow:0 1px 6px rgba(20,24,40,.06)}
.scen[open]{box-shadow:0 6px 22px rgba(20,24,40,.1)}
.scen summary{list-style:none;cursor:pointer;user-select:none}
.scen summary::-webkit-details-marker{display:none}
.scen-head{background:linear-gradient(135deg,#1a1a2e,#0d1628);padding:16px 22px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px}
.scen-head .nm{font-family:var(--serif);font-size:17.5px;color:#fff;font-weight:600}
.scen-head .nm .star{color:var(--gold)}
.scen-head .cc{font-size:9.5px;letter-spacing:1.5px;color:var(--gold);text-transform:uppercase;font-weight:700;display:flex;align-items:center;gap:8px}
.scen-chev{color:var(--gold);font-size:12px;transition:transform .25s}
.scen[open] .scen-chev{transform:rotate(180deg)}
.scen-preview{padding:16px 22px;background:var(--card)}
.scen-more{padding:0 22px 18px;background:var(--card);animation:fade .3s}
.scen-more .dl{font-size:9px;font-weight:800;letter-spacing:2px;color:#a5842a;text-transform:uppercase;margin:14px 0 8px;padding-top:12px;border-top:1px dashed #e2dac6}
.scen-more p{font-size:13px;color:#333b47;line-height:1.65;margin-bottom:.6em}
.prob-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px}

/* week ahead */
.week-card{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);padding:4px 24px;margin-bottom:13px}
.wk-row{padding:13px 0;border-bottom:1px solid #f2ede3}.wk-row:last-child{border-bottom:none}
.wk-top{display:flex;justify-content:space-between;align-items:baseline;gap:10px}
.wk-ev{font-family:var(--serif);font-size:15px;font-weight:600;color:var(--ink)}
.wk-meta{font-family:var(--mono);font-size:10.5px;color:#999;white-space:nowrap}
.wk-why{font-size:12.5px;color:#4a5260;margin-top:4px;line-height:1.5}
.wk-flag{color:var(--down)}

.footer{background:#050912;padding:26px 46px 30px;text-align:center;font-size:10px;color:rgba(240,237,232,.34);line-height:1.7}
.footer strong{color:rgba(201,168,76,.5)}
@media(max-width:680px){
  .mast,.body,.fed{padding-left:18px;padding-right:18px}
  .snap{grid-template-columns:repeat(3,1fr)}.metrics{grid-template-columns:1fr 1fr}
  .bb-split,.empathy-grid,.reads,.people-minor{grid-template-columns:1fr}
  .mhead h1{font-size:28px}
}

/* EARNINGS ON DECK */
.earn-card{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);padding:4px 24px;margin-bottom:13px}
.earn-row{display:flex;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid #f2ede3}
.earn-row:last-child{border-bottom:none}
.earn-row.headline{background:var(--gold-ghost);margin:0 -24px;padding:14px 24px;border-bottom:1px solid #f2ede3}
.earn-when{flex-shrink:0;text-align:center;width:54px}
.earn-when .day{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--ink)}
.earn-when .ampm{font-size:8px;letter-spacing:.5px;color:var(--ink3);text-transform:uppercase;font-weight:700;margin-top:2px}
.earn-when .ampm.bmo{color:#b45309}.earn-when .ampm.amc{color:#1d4ed8}
.earn-body{flex:1;min-width:0}
.earn-tk{font-family:var(--mono);font-size:15px;font-weight:700;color:var(--ink)}
.earn-tk .badge{font-size:8px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;padding:2px 6px;border-radius:4px;margin-left:8px;vertical-align:middle}
.earn-tk .badge.hold{background:var(--gold-ghost);color:#a5842a}
.earn-what{font-size:13px;color:var(--ink2);margin-top:4px;line-height:1.5}.earn-what b{color:var(--ink)}
.earn-nums{flex-shrink:0;text-align:right;font-family:var(--mono)}
.earn-nums .est{font-size:12px;color:var(--ink2);font-weight:700}
.earn-nums .k{font-size:7.5px;letter-spacing:.5px;color:var(--ink3);text-transform:uppercase;font-weight:700}

/* three-part desk item */
.desk3{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);margin-bottom:12px;overflow:hidden}
.desk3[open]{box-shadow:0 6px 22px rgba(20,24,40,.1)}
.desk3 summary{list-style:none;cursor:pointer;padding:18px 22px;display:flex;gap:17px;align-items:flex-start;user-select:none}
.desk3 summary::-webkit-details-marker{display:none}
.desk3 .dn3{flex-shrink:0;width:38px;height:38px;border-radius:11px;background:linear-gradient(135deg,var(--navy),var(--navy-mid));color:var(--gold-b);font-family:var(--serif);font-size:21px;font-weight:700;display:flex;align-items:center;justify-content:center;border:1px solid rgba(201,168,76,.3)}
.desk3 .dt3{flex:1;min-width:0}
.desk3 .dh3{font-family:var(--serif);font-size:20px;font-weight:600;color:var(--ink);line-height:1.28;letter-spacing:-.2px}
.desk3 .dchev{flex-shrink:0;width:32px;height:32px;border-radius:9px;background:linear-gradient(135deg,var(--gold-b),var(--gold));display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;transition:transform .25s;font-weight:700}
.desk3[open] .dchev{transform:rotate(180deg)}
.desk3-body{padding:0 22px 20px 77px;animation:fade .3s}
.d3block{margin-top:14px}
.d3block .lbl{font-size:8.5px;font-weight:800;letter-spacing:1.8px;text-transform:uppercase;margin-bottom:6px;display:flex;align-items:center;gap:7px}
.d3block p{font-size:13.5px;color:#333b47;line-height:1.68;margin:0}
.d3block.why{background:rgba(26,38,68,.05);border-left:2px solid var(--panel-hi);border-radius:0 8px 8px 0;padding:11px 15px}
.d3block.why p{color:var(--navy-text)}

/* drivers */
.drivers{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:13px}
.driver{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);overflow:hidden}
.driver[open]{box-shadow:0 6px 20px rgba(20,24,40,.1)}
.driver summary{list-style:none;cursor:pointer;padding:16px 18px;user-select:none}
.driver summary::-webkit-details-marker{display:none}
.driver-tk{font-family:var(--mono);font-size:16px;font-weight:700;color:var(--ink)}
.driver-mv{font-family:var(--mono);font-size:15px;font-weight:700}
.driver-sec{margin-left:auto;font-size:10px;color:var(--ink3);font-weight:600}
.driver-more{padding:0 18px 16px;animation:fade .3s}

/* AI Pulse */
.ai-pulse{background:linear-gradient(135deg,#0a1428,#0d1c3a);border:1px solid rgba(96,165,250,.35);border-left:4px solid #3b82f6;border-radius:13px;padding:22px 26px;margin-bottom:13px;color:rgba(235,242,255,.9)}
.ai-pulse .ap-label{font-size:9.5px;font-weight:800;letter-spacing:2.5px;color:#60a5fa;text-transform:uppercase;margin-bottom:12px;display:flex;align-items:center;gap:8px}
.ai-pulse p{font-size:14px;line-height:1.7;color:rgba(235,242,255,.82);margin-bottom:10px}.ai-pulse p b{color:#bfdbfe}
.prod-tool{margin-top:16px;padding-top:16px;border-top:1px solid rgba(96,165,250,.2)}
.prod-tool .pt-label{font-size:9px;font-weight:800;letter-spacing:2px;color:#93c5fd;text-transform:uppercase;margin-bottom:8px;display:flex;align-items:center;gap:7px}
.prod-tool .pt-name{font-family:var(--serif);font-size:17px;color:#fff;font-weight:600;margin-bottom:6px}
.prod-tool p{font-size:13px;color:rgba(235,242,255,.78);line-height:1.62;margin:0}

/* analyst desk blocks */
.desk-block{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);padding:20px 24px;margin-bottom:13px}
.dbk-sub{padding:14px 0;border-bottom:1px solid #f2ede3}
.dbk-sub:first-of-type{padding-top:6px}.dbk-sub:last-child{border-bottom:none;padding-bottom:0}
.dbk-h{font-size:9px;font-weight:800;letter-spacing:1.5px;color:#a5842a;text-transform:uppercase;margin-bottom:7px}
.dbk-sub p{font-size:13.5px;color:#333b47;line-height:1.68;margin:0}.dbk-sub p b{color:var(--ink)}
.rfocus{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 1px 4px rgba(20,24,40,.05);margin-bottom:11px;overflow:hidden}
.rfocus[open]{box-shadow:0 6px 20px rgba(20,24,40,.1)}
.rfocus summary{list-style:none;cursor:pointer;padding:16px 22px;user-select:none}
.rfocus summary::-webkit-details-marker{display:none}
.rf-kick{font-size:9px;font-weight:800;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px}
.rf-risk .rf-kick{color:#a32020}.rf-res .rf-kick{color:#7c5c0a}
.rf-name{font-family:var(--serif);font-size:19px;font-weight:600;color:var(--ink);margin-bottom:10px;display:flex;align-items:center;justify-content:space-between}
.rf-body{padding:0 22px 16px;animation:fade .3s}
.rf-body p{font-size:13.5px;color:#333b47;line-height:1.68}
.rf-note{font-size:10.5px;color:var(--ink3);font-style:italic;margin-top:8px}

/* risk expand */
.risk-expand{margin-top:14px;border-top:1px solid rgba(255,255,255,.12);padding-top:4px}
.risk-expand summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;padding:12px 0 4px;user-select:none}
.risk-expand summary::-webkit-details-marker{display:none}
.risk-expand .re-lbl{font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold-b)}
.re-body{padding-top:10px;animation:fade .3s}
.re-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0}
.re-box{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:9px;padding:13px 15px}
.re-box .k{font-size:8px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold-b);margin-bottom:6px}
.re-box .big{font-family:var(--mono);font-size:22px;font-weight:800;color:#fff;line-height:1;margin-bottom:5px}
.re-box p{font-size:12px;color:rgba(238,242,252,.72);line-height:1.55;margin:0}
.re-chain{margin:12px 0}
.re-step{display:flex;gap:11px;align-items:flex-start;padding:7px 0}
.re-step .n{flex-shrink:0;width:20px;height:20px;border-radius:50%;background:rgba(239,68,68,.2);color:#fca5a5;font-family:var(--mono);font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center}
.re-step p{font-size:12.5px;color:rgba(238,242,252,.82);line-height:1.5;margin:0}.re-step p b{color:#fff}
.re-pos{font-size:12.5px;color:rgba(238,242,252,.8);line-height:1.6;margin-top:8px}
.re-pos b.hurt{color:#fca5a5}.re-pos b.help{color:#86efac}
