// ═══════════════════════════════════════════════════════════════
// STRUCTURAL TRANSFORMS
// ═══════════════════════════════════════════════════════════════
function wrapWatchlistTabs(html){
  return String(html).replace(/(?:<details class="wl-tab"[^>]*>[\s\S]*?<\/details>\s*)+/g, function(run){
    if (/<div class="wl-tabs">/.test(run)) return run;
    return '<div class="wl-tabs">' + run.replace(/\s+$/, '') + '</div>';
  });
}
function collapseDesk3(html){
  return String(html).replace(/(<details class="desk3[^"]*")\s+open(?=[\s>])/g, '$1');
}
// ── FACTOR X-RAY: bars stay visible, the prose folds into a drawer ──────
// The agent emits every factor's bar AND its full note inline, which makes the
// X-Ray the longest block on the page. Keep the bars (they are the scannable
// part), move each note plus the blunt-read warning into one drawer. Ported
// from the v18 engine; no payload dependency, so it is inert whenever the
// agent emits no <div class="xray"> block.
function formatXray(html){
  return String(html).replace(
    // Global: a multi-mandate brief carries one X-Ray per mandate, and the v18
    // original was non-global, so the second mandate's block kept its inline
    // notes while the first got a drawer. Single-book briefs have one block and
    // are unaffected.
    /<div class="xray">([\s\S]*?)<\/div>\s*(?=<div class="wlx"|<div class="sec-num"|<div class="secbar"|<div class="mandate"|$)/gi,
    function(m, inner){
      var notes = [];
      var re = /<div class="factor">([\s\S]*?)<\/div>\s*(?=<div class="factor">|<div class="xray-warn">|$)/gi, fm;
      while ((fm = re.exec(inner)) !== null){
        var fb = fm[1];
        var nm = (fb.match(/<span class="factor-name">([\s\S]*?)<\/span>/i) || [])[1] || '';
        nm = nm.replace(/<span class="dir[\s\S]*?<\/span>/i, '').replace(/<[^>]*>/g, '').trim();
        var note = (fb.match(/<div class="factor-note">([\s\S]*?)<\/div>/i) || [])[1];
        if (note) notes.push('<div class="fx-note"><div class="fx-note-k">' + esc(nm) + '</div><div class="fx-note-b">' + note + '</div></div>');
      }
      if (!notes.length) return m;   // nothing to fold away: leave the block untouched
      var blunt = (inner.match(/<div class="xray-warn">[\s\S]*?<\/div>/i) || [])[0] || '';
      var bars = inner.replace(/<div class="factor-note">[\s\S]*?<\/div>/gi, '')
                      .replace(/<div class="xray-warn">[\s\S]*?<\/div>/i, '');
      var drawer = '<details class="fx-more"><summary><span class="fx-more-btn">Open the full factor read <span class="fx-more-chev">▼</span></span></summary>'
        + '<div class="fx-more-body">' + notes.join('') + blunt + '</div></details>';
      return '<div class="xray">' + bars + drawer + '</div>';
    }
  );
}

function mergeFactorTitle(html){
  return String(html).replace(
    /<div class="subbar"><span class="subbar-q">What bets is[^<]*<\/span><\/div>\s*(<div class="xray">)/i,
