function styleWatchlistBanner(html){
  html = String(html).replace(/<div class="subbar"><span class="subbar-t">\s*Your Watchlist\s*<\/span><\/div>/i, '');
  if (/class="subsec-wl"/.test(html)) return html.replace(/<div class="wl-bar">[\s\S]*?<\/div>/i, '');
