function formatPremortem(html){
  return String(html).replace(/<div class="premortem">([\s\S]*?)(<(?:x-dd|details) class="risk-expand">\s*<(?:x-sum|summary)>[\s\S]*?<\/(?:x-sum|summary)>\s*<div class="re-body">)/i, function(m, top, ddOpen){
    var label = (top.match(/<span class="pm-label">[\s\S]*?<\/span>/i) || [''])[0];
    var title = (top.match(/<div class="pm-title">[\s\S]*?<\/div>/i) || [''])[0];
    var foot  = (top.match(/<div class="pm-foot">[\s\S]*?<\/div>/i) || [''])[0];
    var paras = top.match(/<p\b[\s\S]*?<\/p>/gi) || [];
    return '<div class="premortem">' + label + title + (paras[0] || '') + foot + ddOpen + paras.slice(1).join('');
  });
}
function highlightWatchBest(html){
  var fr = String(html).match(/Further Research\s*·\s*([A-Za-z.]{1,6})/i);
  if (!fr) return html;
  var tk = fr[1].toUpperCase().replace(/[^A-Z.]/g, '');
  if (!tk) return html;
  var re = new RegExp('<details class="wl-tab">((?:(?!<\\/details>)[\\s\\S])*?<span class="wl-tk">\\s*' + tk + '\\b)', 'i');
  return html.replace(re, '<details class="wl-tab wl-best">$1');
}
function formatPositions(html){
  var moves = holdingMoves();
  return String(html).replace(/<div class="on-tk">([\s\S]*?)<\/div>/g, function(m, inner){
    var tkm = inner.match(/^\s*([A-Za-z.]{1,6})/);
    var tk = tkm ? tkm[1].toUpperCase() : '';
    var mv = (tk && moves[tk]) ? num(moves[tk].today) : null;
    var badge = (mv !== null)
      ? '<span class="on-move ' + (mv>=0?'up':'dn') + '">' + (mv>=0?'▲':'▼') + ' ' + Math.abs(mv).toFixed(2) + '%</span>'
      : '';
    var next = inner.replace(/<span class="on-flag[^"]*">[\s\S]*?<\/span>/i, badge);
    if (badge && !/on-move/.test(next)) next = next.trim() + badge;
    return '<div class="on-tk">' + next + '</div>';
  });
}
function positionsFirst(html){
  var m = String(html).match(/<div class="onx">[\s\S]*?(?=<div class="xray">|<div class="subbar"><span class="subbar-q">|<div class="sec-num")/i);
  if (!m || !/<div class="sec-title">Portfolio Spotlight<\/div>/i.test(html)) return html;
  html = html.replace(m[0], '');
  // Function form, not a replacement string. The moved block contains dollar
  // figures; "$1" inside "$165" or "$1,300" is a live backreference in a
  // replacement string, which is how "$1,300" shipped as ",300".
  return html.replace(/(<div class="sec-title">Portfolio Spotlight<\/div>\s*)/i,
    function(_, g1){ return g1 + m[0]; });
}
function relocateWatchlist(html){
  var re = /<div class="subbar"><span class="subbar-t">\s*Your Watchlist\s*<\/span><\/div>[\s\S]*?(?=<div class="subbar"><span class="subbar-q">|<div class="sec-num")/i;
  var m = String(html).match(re);
  if (!m || !/<div class="rf-pair">/i.test(html)) return html;
  var tabs = (m[0].match(/<x-dd class="wl-tab">[\s\S]*?<\/x-dd>/g) || []).join('');
  if (!tabs) return html;
  html = html.replace(m[0], '');
  var block = '<div class="subsec subsec-wl">Your Watch List and Key Standouts</div>' + tabs;
  return html.replace(/<div class="rf-pair">/i,
    function(){ return block + '<div class="rf-pair">'; });   // block may carry $ figures
}
function splitSpotlight(html){
  if (/id="spotlight"/i.test(html)) return html;
  return String(html).replace(/<div class="sector-box">/i,
      '<div class="sec-num" id="spotlight">02</div>\n'
    + '<div class="sec-title">Portfolio Spotlight</div>\n'
    + '<div class="subsec subsec-sector">Sector Analysis</div>\n'
