}
function formatSituations(html){
  html = String(html)
    .replace(/<span class="reader-tag tag-act">[^<]*<\/span>/g, '')
    .replace(/<span class="horizon">[^<]*<\/span>/g, '');
  return html.replace(
    /<span class="thread">([\s\S]*?)<\/span>\s*(<div class="dd-top">)([\s\S]*?)<b>/g,
    function(m, rawLabel, ddOpen, mid){
      var label = rawLabel.replace(/🧵/g, '').replace(/\s+/g, ' ').trim();
      if (!label) return m;
      var keep = mid.replace(/^(?:\s|&nbsp;)+/, '').replace(/(?:\s|&nbsp;)+$/, '');
      return ddOpen + (keep ? keep + ' ' : '') + '<span class="sit-topic">' + esc(label) + ':</span> <b>';
    }
  );
}
function formatHedgeFundFlow(html){
  return String(html).replace(
    /<div class="hff-rows">([\s\S]*?)<\/div>\s*(<div class="hff-net">)/i,
    function(m, inner, netOpen){
      var rows = (inner.match(/<div class="hff-row">[\s\S]*?<\/div>/g) || []).slice(0, 6);
      if (!rows.length) return m;
      var rebuilt = rows.map(function(r){
        return r.replace(/\s*\u2014\s*/g, ', ').replace(/\s*\u2013\s*/g, ', ');
      }).join('');
      return '<div class="hff-rows">' + rebuilt + '</div>' + netOpen;
    }
  );
}
function formatAnalystDesk(html){
  html = String(html).replace(
    /(<div class="pt-preview">)([\s\S]*?)(<\/div>\s*<div class="dbk-sub")/i,
    function(m, open, inner, tail){
      var rows = inner.match(/<div class="pt-row">[\s\S]*?<\/div>/g) || [];
      if (!rows.length) return m;
      var best = 0, bestVal = -Infinity;
      rows.forEach(function(r, i){
        var mm = r.match(/pt-chg [^"]*">\s*[+\-−]?\s*(\d+(?:\.\d+)?)%/);
        var v = mm ? parseFloat(mm[1]) : 0;
        if (v > bestVal){ bestVal = v; best = i; }
      });
      var out = rows.map(function(r, i){
        return i === best ? r.replace('<div class="pt-row">', '<div class="pt-row pt-top">') : r;
      }).join('');
      return open + out + tail;
    }
  );
  html = html.replace(/<details class="dd pt-more">[\s\S]*?<\/details>/i, '');
  html = html.replace(/(<span class="card-label[^"]*">🏦 Fixed Income[^<]*<\/span>)[^<]*/i, '$1');
  return html;
}
function formatRiskResearch(html){
  return String(html).replace(/<details class="rfocus([^"]*)">([\s\S]*?)<\/details>/g, function(m, cls, inner){
    var sum = (inner.match(/<summary>([\s\S]*?)<\/summary>/i) || [null, inner])[1] || '';
    sum = sum.replace(/<span class="chev">[\s\S]*?<\/span>/i, '');
    var body = (inner.match(/<div class="rf-body">([\s\S]*?)<\/div>/i) || [null, ''])[1] || '';
    var text = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    var sentences = text.split(/(?<=[.!?])\s+/).map(function(s){ return s.trim(); }).filter(Boolean);
    if (!sentences.length) return m;
    // Every sentence, not the first three. The block is a drawer now, so
    // length costs nothing until the reader asks for it.
    var bullets = sentences.map(function(s, i){
      return (i === sentences.length - 1)
        ? '<li class="rf-watch"><b class="rf-watch-lbl">Keep an eye on</b> ' + s + '</li>'
        : '<li>' + s + '</li>';
    }).join('');
    return '<details class="rfocus' + cls + '">'
      + '<summary><div class="rf-head">' + sum + '</div>'
      + '<span class="rf-chev">\u25bc</span></summary>'
      + '<div class="rf-body"><ul>' + bullets + '</ul></div></details>';
  });
}
function formatWhyMoving(html){
  return String(html).replace(/<(x-dd|details) class="dd wm">[\s\S]*?<\/\1>/i, function(block){
    if (/keep-eye/.test(block)) return block;
    var ps = block.match(/<p>[\s\S]*?<\/p>/gi);
    if (!ps || !ps.length) return block;
    var last = ps[ps.length - 1];
    var swapped = '<p class="keep-eye"><b class="keep-eye-lbl">Keep an eye on</b> ' + last.replace(/^<p>/, '').replace(/<\/p>$/, '') + '</p>';
    var idx = block.lastIndexOf(last);
    return block.slice(0, idx) + swapped + block.slice(idx + last.length);
  });
}
// Split prose into sentences without breaking on abbreviations or currency.
// Shares LEAD_ABBR with the Section 01 lead-sentence bolding.
function splitSentences(text){
  var t = String(text).replace(/\s+/g, ' ').trim();
  var out = [], start = 0;
  for (var i = 0; i < t.length; i++){
    var ch = t.charAt(i);
    if (ch !== '.' && ch !== '!' && ch !== '?') continue;
    if (!/^\s[A-Z"'\u201c(]/.test(t.slice(i + 1, i + 3))) continue;
    if (ch === '.' && LEAD_ABBR.test(t.slice(0, i + 1))) continue;
    out.push(t.slice(start, i + 1).trim());
    start = i + 1;
  }
  var tail = t.slice(start).trim();
  if (tail) out.push(tail);
  return out.filter(Boolean);
}
function formatFixedIncome(html){
  // Three bullets, no drawer. Rule: the two opening sentences carry the
  // mechanism, the last carries the portfolio tell. The dated-catalyst sentence
  // is the one dropped, and it is the safest to lose because the masthead's
  // Big Upcoming Dates strip already names payrolls and CPI.
  //
  // Note on length: the bullets are the agent's sentences, whole. Making each
  // one SHORTER means cutting inside a sentence, and on this block the insight
  // lives in the second clause ("...so this is a hawkish-Fed and term-premium
  // story, not an inflation-expectations story"). Trimming to the first clause
  // keeps the number and throws away the reasoning. Short-and-deep has to be
  // written that way upstream; see SYSTEM_PROMPT_TODO.md.
  return String(html).replace(/<details class="dd fi">([\s\S]*?)<\/details>/i, function(m, inner){
    var means = inner.match(/<div class="dl">What it means for you<\/div>\s*<p>([\s\S]*?)<\/p>/i);
    var text = String(means ? means[1] : '')
      .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (!text) return m;                       // nothing to bullet: leave it be
    var sent = splitSentences(text);
    if (!sent.length) return m;
    var picked = (sent.length <= 3)
      ? sent
      : sent.slice(0, 2).concat([sent[sent.length - 1]]);
    return '<ul class="fi-bullets">'
      + picked.map(function(b, i){
          return '<li>' + (i === 0 ? '<b class="fi-watch">Keep an eye out for:</b> ' : '') + b + '</li>';
        }).join('')
      + '</ul>';
  });
}
function formatWeekAhead(html){
  return String(html).replace(/<span class="wk-ev([^"]*)">((?:<span\b[^>]*>[\s\S]*?<\/span>|[^<])*)<\/span>/g, function(m, cls, inner){
    var dm = inner.match(/·\s*([A-Za-z]{3,})\s+(\d{1,2})\/(\d{1,2})\s*$/);
    if (!dm) return m;
    // dm[2] is the month, dm[3] the day. Both, so "Fri 9/4" not "Fri 4".
    var box = '<span class="wk-date"><span class="wk-d">' + dm[1] + '</span>'
      + '<span class="wk-n">' + dm[2] + '/' + dm[3] + '</span></span>';
    var name = inner.replace(/\s*·\s*[A-Za-z]{3,}\s+\d{1,2}\/\d{1,2}\s*$/, '').trim();
    return '<span class="wk-ev' + cls + '">' + box + ' ' + name + '</span>';
  });
}
function formatInsiderEdge(html){
  // The FULL signal read stays. v19.1 cut every one to its first sentence,
  // which turned "why this trade matters to this book" into a fragment.
  return String(html).replace(/<div class="ins-sig">([\s\S]*?)<\/div>/g, function(m, body){
    var t = body.replace(/^\s*Signal\s*[:\--]?\s*/i, '').trim();
    return '<div class="ins-sig"><b class="ins-sig-lbl">Analysis</b> ' + t + '</div>';
  });
}
function maybeHideWatchlist(html){
  var wp = dv('watchlistPerf', null);
  var raw = String(dv('Watchlist','') || '').trim();
  var hasWl = (Array.isArray(wp) && wp.length) || raw.length > 0;
  if (hasWl) return html;
  html = html.replace(/<div class="wl">[\s\S]*?<\/div>\s*(?=<div class="[^"]*mv|<div class="drivers|<div class="sec-num|$)/i, '');
  return html + '<style>.wl{display:none !important}</style>';
}
var JOKE_QA = [
  ['My financial advisor told me to invest in something that keeps me up at night.', 'So technically the espresso machine counts as fixed income.'],
  ['I asked my advisor what the market did today.', 'He said "priced in." I asked priced into what. He said "exactly."'],
  ['A recession is when your neighbor loses his job.', 'A depression is when the guy who sold you the dip loses his.'],
  ['My portfolio is officially all-weather.', 'It loses money in every season.'],
  ['I finally beat the S&P 500 this quarter.', 'It went down 4% and I only went down 3.8%. Dinner is on me.'],
  ['An economist is someone who will know tomorrow', 'why the thing he predicted yesterday did not happen today.'],
  ['My two biggest positions are diversification and denial.', 'Denial is outperforming.'],
  ['What do you call a stock that goes up on no news, down on good news, and sideways on earnings?', 'Held. You call it held.'],
  ['I told my client the market hates uncertainty.', 'He asked what it loves. I have been thinking about it for eleven years.'],
  ['Past performance is no guarantee of future results.', 'Which is also what I tell my golf partners on the first tee.']
];
var JOKE_KNOCK = [
  ['Knock knock.', 'Who\u2019s there?', 'Priced.', 'Priced who?', 'Priced in. It was priced in before you even opened the door.'],
  ['Knock knock.', 'Who\u2019s there?', 'Soft landing.', 'Soft landing who?', 'Exactly. Nobody has ever actually seen one either.'],
  ['Knock knock.', 'Who\u2019s there?', 'Diversification.', 'Diversification who?', 'All eleven of my tech funds would like a word.'],
  ['Knock knock.', 'Who\u2019s there?', 'The Fed.', 'The Fed who?', 'Data-dependent. Might open the door, might not, watch the dots.'],
  ['Knock knock.', 'Who\u2019s there?', 'Volatility.', 'Volatility who?', 'ITS ME AGAIN. OPEN UP. I KNOW THURSDAY IS EARNINGS.'],
  ['Knock knock.', 'Who\u2019s there?', 'Long-term investor.', 'Long-term investor who?', 'It has been four hours, is it up yet.'],
  ['Knock knock.', 'Who\u2019s there?', 'Guidance.', 'Guidance who?', 'Withdrawn. Management no longer answers the door.'],
  ['Knock knock.', 'Who\u2019s there?', 'Cash.', 'Cash who?', 'Finally yielding something, so I am allowed at the party again.']
];
function buildJoke(){
  var d = dv('windowTo', null) || dv('rateDate', null) || '';
  var seed = 0;
  var s = String(d);
  if (!s) s = String(new Date().getUTCDate());
  for (var i=0;i<s.length;i++) seed = (seed*31 + s.charCodeAt(i)) >>> 0;
  var qa = JOKE_QA[seed % JOKE_QA.length];
  var kn = JOKE_KNOCK[(seed >> 3) % JOKE_KNOCK.length];
  var knHtml = '<div class="joke-q">' + esc(kn[0]) + ' <span style="font-weight:600">' + esc(kn[1]) + '</span> ' + esc(kn[2]) + ' <span style="font-weight:600">' + esc(kn[3]) + '</span></div>'
    + '<div class="joke-a">' + esc(kn[4]) + '</div>';
  return '<div class="jokes"><div class="jokes-label">😂 Finance Jokes of the Day · to tell your coworkers</div>'
    + '<div class="joke-item"><div class="joke-q">' + esc(qa[0]) + '</div><div class="joke-a">' + esc(qa[1]) + '</div></div>'
    + '<div class="joke-item">' + knHtml + '</div>'
    + '</div>';
}
function appendJoke(html){
  if (/class="jokes"/.test(html)) return html;
  return html + buildJoke();
}
function oneJoke(html){
  var n = 0;
  return String(html).replace(/<div class="joke-item"><div class="joke-q">[\s\S]*?<\/div><div class="joke-a">[\s\S]*?<\/div><\/div>/gi, function(m){
    return (++n === 1) ? m : '';
  });
}
// ── SPOTLIGHT NARRATION ────────────────────────────────────────
// The agent opens Portfolio Spotlight with a prose sub-bar restating the day's
// book move. The Performance Report directly above now states the same thing in
// numbers, per mandate and blended, so the paragraph is a duplicate sitting in
// a box on its own. Drop it — but only long prose, and only in that opening
// region. Short sub-bars there are section headers ("Sector Analysis") and stay.
// A subbar is a HEADER element — a label above a block. Anything long enough to
// be a paragraph is prose that landed in the wrong container, and by the time
// the reader reaches it the Performance Report above has already said the same
// thing in numbers. Length is the test, so no ticker or figure is hardcoded and
// real headers ("Sector Analysis", "Read These Two Articles Today") are safe.
// Position-independent on purpose: later passes relocate these bars.
function dropSpotlightNarration(html){
  return String(html).replace(/<div class="subbar"><span class="subbar-t">([\s\S]*?)<\/span><\/div>\s*/gi,
    function(m, inner){
      var txt = String(inner).replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
      if (txt.length <= 120) return m;
      // Prose that landed in a header container is RE-HOUSED, not deleted. The
      // long subbar in Section 02 is the mandated performance read line, the one
      // sentence that interprets the scoreboard. v19.1 deleted it for being over
      // 120 characters, which removed the only interpretation the section had.
      // Real headers stay headers; long prose becomes a styled read line.
      return '<div class="s2-read"><span class="s2-read-k">The read</span> ' + inner + '</div>';
    });
}

// ── ANALYST DESK TRIMS ─────────────────────────────────────────
// Hedge Fund Flow: drop the "net read" summary. The rows above already say who
// bought and who sold; the paragraph restated them at length.
function dropHedgeFundNetRead(html){
  return String(html).replace(/<div class="hff-net">[\s\S]*?<\/div>\s*/gi, '');
}

// Insider Edge: only the FIRST item keeps its analysis box. The rest are the
// fact and nothing else — one read is the point, five is a wall.
function trimInsiderSignals(html){
  var seen = 0;
  return String(html).replace(/<div class="ins-item">([\s\S]*?)(?=<div class="ins-item">|<\/div>\s*<div class="desk-block"|<div class="sec-num"|<div class="secbar"|$)/gi,
    function(m, inner){
      seen++;
      if (seen === 1) return m;                       // keep the most notable
      return m.replace(/<div class="ins-sig">[\s\S]*?<\/div>\s*/i, '');
    });
}

// ── PORTFOLIO SPOTLIGHT: ONE SECTION, FIXED ORDER ──────────────
// Earlier passes (splitSpotlight, positionsFirst, the relocators) each move one
// piece, and on a two-mandate brief the result interleaves: news, House's
// sectors, more news, the report, Roth's sectors, then the factor block. The
// reader meets the Performance Report fourth.
//
// This pass takes the whole section apart and lays it back down in one order:
//   1. Performance Report (with its analytics drawer)
//   2. Latest Position-Specific News — one block, capped
//   3. Sector analysis
//   4. anything else the agent wrote
//   5. "What bets is the book making?" + the factor X-Ray, last
//
// Mandate wrappers are unwrapped on the way through, so there is no "Roth IRA
// section" followed by a "House section" — the per-portfolio comparison lives
// in the analytics drawer instead. Single-book briefs have no wrappers and no
// duplicate blocks, so they fall through this almost untouched.
function cutBlocks(region, opener){
  var blocks = [], out = region, m;
  var re = new RegExp(opener, 'i');
  while ((m = re.exec(out)) !== null){
    var e = endOfDiv(out, m.index);
    if (e === -1) break;
    blocks.push(out.slice(m.index, e));
    out = out.slice(0, m.index) + out.slice(e);
  }
  return { region: out, blocks: blocks };
}

function unwrapMandates(region){
  var out = region;
  var re = /<div class="mandate"[^>]*>/i;
  var guard = 0;
  for (;;){
    var m = re.exec(out);
    if (!m || guard++ > 24) break;
    var e = endOfDiv(out, m.index);
    if (e === -1){
      // No matching close: earlier passes moved this wrapper's content out and
      // left the opener orphaned. Dropping the opener alone RESTORES balance —
      // and must not abort the loop, or every later wrapper survives too.
      out = out.slice(0, m.index) + out.slice(m.index + m[0].length);
    } else {
      var inner = out.slice(m.index + m[0].length, e - 6);   // minus the closing </div>
      out = out.slice(0, m.index) + inner + out.slice(e);
    }
  }
  // The title bar goes with the wrapper wherever it ended up.
  return out.replace(/<div class="mnd-bar">[\s\S]*?<\/div>\s*/gi, '');
}

// Merge every news column into one and keep at most NEWS_KEEP items.
function mergeNewsBlocks(blocks){
  if (!blocks.length) return '';
  var items = [], label = '', sub = '';
  blocks.forEach(function(b){
    if (!label) label = (b.match(/<div class="onx-label">([\s\S]*?)<\/div>/i) || [])[1] || '';
    if (!sub)   sub   = (b.match(/<div class="onx-sub">([\s\S]*?)<\/div>/i) || [])[1] || '';
    var re = /<details class="on-dd">[\s\S]*?<\/details>/gi, m;
    while ((m = re.exec(b)) !== null) items.push(m[0]);
  });
  if (!items.length) return '';
  // Drop any book qualifier — one merged column covers the whole book.
  label = label.replace(/\s*·\s*[^·<]*$/, '').trim() || '🔔 Latest Position-Specific News';
  return '<div class="onx"><div class="onx-label">' + label + '</div>'
    + (sub ? '<div class="onx-sub">' + sub + '</div>' : '')
    + items.slice(0, NEWS_KEEP).join('')
    + '</div>';
}

function restructureSpotlight(html){
  var s = String(html);
  var start = s.search(/<div class="(?:sec-num|secbar)" id="spotlight"/i);
  if (start === -1) return s;
  var rel = s.slice(start + 6).search(/<div class="(?:sec-num|secbar)"/i);
  var end = rel === -1 ? s.length : start + 6 + rel;

  var head = s.slice(0, start), region = s.slice(start, end), tail = s.slice(end);

  // Keep the section heading exactly where it is.
  var hm = region.match(/^<div class="(?:sec-num|secbar)"[^>]*>[\s\S]*?<\/div>(?:\s*<div class="sec-title">[\s\S]*?<\/div>)?/i);
  var heading = hm ? hm[0] : '';
  var body = region.slice(heading.length);

  body = unwrapMandates(body);

  // Collected before the block extraction so they are found wherever the agent
  // put them — on the v20.1 run they landed next to the X-Ray, well below the
  // rows they describe.
  var si = cutSectorInsights(body);
  body = si.region;

  var r1 = cutBlocks(body, '<div class="pscore">');
  var r2 = cutBlocks(r1.region, '<div class="onx">');
  var r3 = cutBlocks(r2.region, '<div class="sector-box[^"]*"');
  var r4 = cutBlocks(r3.region, '<div class="xray">');
  var rest = r4.region;

  // "What bets is X making?" sub-bars travel with the X-Ray to the bottom.
  // Dropped, not relocated: the Subsector Bets card carries its own header, so
  // these announced a block that already announces itself.
  var bets = [];
  rest = rest.replace(/<div class="subbar"><span class="subbar-q">[\s\S]*?<\/span><\/div>\s*/gi, '');
  rest = rest.replace(/<div class="subbar"><span class="subbar-t">\s*Sector Analysis\s*<\/span><\/div>\s*/gi, '');

  // Take the orphaned sector header out of the leftovers; it is re-emitted at
  // the top of the sector block below.
  rest = rest.replace(/<div class="subsec subsec-sector">[\s\S]*?<\/div>\s*/i, '');

  var report  = r1.blocks.join('');
  rest = rest.replace(/<div class="s2-read">([\s\S]*?)<\/div>\s*/i, function(m, inner){
    var pi = report.indexOf('<div class="pscore">');
    if (pi === -1) return m;                    // no report this run: leave it be
    var pe = endOfDiv(report, pi);
    if (pe === -1) return m;
    var txt = inner.replace(/<span class="s2-read-k">[\s\S]*?<\/span>\s*/i, '').trim();
    if (!txt) return m;
    var plain = txt.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (plain.length > 190){
      var cuts = [], cre = /,\s(and|which|so that|because)\s/g, cm;
      while ((cm = cre.exec(plain)) !== null) cuts.push(cm.index);
      var at = null;
      for (var ci = cuts.length - 1; ci >= 0; ci--){
        if (cuts[ci] >= 120){ at = cuts[ci]; break; }   // keep the claim intact
      }
      if (at !== null){
        txt = plain.slice(0, at).trim().replace(/[,;:]$/, '') + '.';
      }
    }
    var line = '<div class="pscore-read"><span class="pscore-read-k">The read</span>'
      + '<span class="pscore-read-b">' + txt + '</span></div>';
    report = report.slice(0, pe - 6) + line + report.slice(pe - 6);
    return '';
  });
  var news    = mergeNewsBlocks(r2.blocks);
  // Insights sit between the banner and the rows they read on. With no rows to
  // sit above they still render, rather than being silently dropped.
  // One header, above the rows it describes. The sd-banner and the Sector
  // Analysis bar were two headers for one block, on opposite sides of it.
  var sectors = r3.blocks.length
    ? '<div class="subsec subsec-sector">Sector Analysis</div>' + si.html + r3.blocks[0]
    : si.html;
  var xray    = r4.blocks.join('');

  // ── DORMANT SLOTS ────────────────────────────────────────────
  // Two openers the agent may write; both render nothing at all when absent,
  // which is every brief until the system prompt emits them. They lead the
  // section because they answer "what is driving this book today" before any
  // number is shown. See SYSTEM_PROMPT_TODO.md for the contract.
  // The opener answers two questions in one card: what moved the market, then
  // what moved THIS book. The second half is the performance read line, which
  // dropSpotlightNarration has already re-housed as .s2-read by the time this
  // runs. Both halves are optional; the card only renders what exists.
  var opener = buildSpotStats(), mkt = '';
  rest = rest.replace(/<div class="macro-overview">([\s\S]*?)<\/div>\s*/i, function(m, inner){
    mkt = inner.trim(); return '';
  });
  // Section 01 owns the market story. Its card is in head, already built by
  // fixMovedHeading, so the macro paragraph joins it there as a lead-in and
  // the heading is renamed to match what it actually holds.
  head = head.replace(/(<div class="mv-head">)([\s\S]*?)(<\/div>)/i, function(m, open, inner, close){
    var glyph = (inner.match(/^\s*(\S+)\s/) || [null,''])[1] || '';
    return open + glyph + ' What moved the markets' + close;
  });
  // mkt is deliberately unused: the macro paragraph is dropped here because the
  // position news below it tells the same story name by name.
  rest = rest.replace(/<div class="tactical-read">([\s\S]*?)<\/div>\s*/i, function(m, inner){
    opener += '<div class="mo-card mo-tac"><div class="mo-k">Tactical read</div><div class="mo-b">' + inner + '</div></div>';
    return '';
  });

  // Order: opener, then the names that moved, then the numbers, then sectors.
  return head + heading + opener + news + report + sectors + rest + bets.join('') + xray + tail;
}

// ── WATCHLIST + RISK MOVE UP UNDER THE PORTFOLIO ───────────────
// "Your Watch List & Key Standouts" and the Review-Your-Risk / Further-Research
// pair are written inside Analyst Desk, but they are about the reader's own
// book, so they belong directly under Portfolio Spotlight. Runs after
// reorderSections, when sections are secbars and the boundary is stable.
// The Watch List stays at the end of Portfolio Spotlight: it is a list of
// names the reader is considering for THIS book. Review Your Risk and Further
// Research are advisor workflow, not portfolio content, so they move to the
// end of the Analyst Desk and sit immediately above Fixed Income.
function relocateWatchRisk(html){
  var s = String(html);

  function lift(open){
    var i = s.indexOf(open);
    if (i === -1) return null;
    var e = endOfDiv(s, i);
    if (e === -1) return null;
    var block = s.slice(i, e);
    s = s.slice(0, i) + s.slice(e);
    return block;
  }
  var watch = lift('<div class="watch">');
  var risk  = lift('<div class="rf-pair">');

  // Watch List -> end of Portfolio Spotlight, where it already lived.
  if (watch){
    var sp = s.search(/<div class="secbar" id="spotlight"/i);
    if (sp === -1){ s = s + watch; }
    else {
      var rel = s.slice(sp + 6).search(/<div class="secbar"/i);
      var at = rel === -1 ? s.length : sp + 6 + rel;
      s = s.slice(0, at) + watch + s.slice(at);
    }
  }

  // Review Your Risk + Further Research -> Analyst Desk, just above Fixed
  // Income. Anchored on the Fixed Income card so it lands in the right place
  // even after the desk is reordered upstream.
  if (risk){
    var fi = s.search(/<div class="desk-block">\s*<span class="card-label[^"]*">\s*\uD83C\uDFE6/i);
    if (fi === -1) fi = s.search(/<div class="desk-block">\s*<span class="card-label[^"]*">[^<]*Fixed Income/i);
    if (fi !== -1){
      // After the Fixed Income card, not before it: these close the desk.
      var fiEnd = endOfDiv(s, fi);
      var at3 = (fiEnd === -1) ? fi : fiEnd;
      s = s.slice(0, at3) + risk + s.slice(at3);
    } else {
      // No Fixed Income block this run: fall back to the end of the desk.
      var an = s.search(/<div class="secbar" id="analyst"/i);
      if (an === -1) return s + risk;
      var rel2 = s.slice(an + 6).search(/<div class="secbar"/i);
      var at2 = rel2 === -1 ? s.length : an + 6 + rel2;
      s = s.slice(0, at2) + risk + s.slice(at2);
    }
  }
  return s;
}

// ── BLIND SPOTS (dormant until the prompt emits them) ──────────
// Contract:
//   <div class="blindspot" data-kind="general|targeted">
//     <div class="bs-title">the sharp claim, reads standalone</div>
//     <div class="bs-why">why it matters — the drawer body</div>
//   </div>
// The title stays visible so the reader gets the point without opening
// anything; the body goes behind a gold "Why that matters" button. Renders
// nothing when the agent writes no blindspot, which is every brief today.
var BS_BTN = 'Why you can\'t be blind to this';

function bsCard(kind, title, why){
  if (!String(title).trim()) return '';
  var tag = kind === 'targeted' ? '🕶 Extremely Niche Blind Spot' : '🕶 You Might Be Blind To';

  // The agent writes one run-on line. Only the CLAIM should be underlined; the
  // clause that explains it reads underneath, unadorned. Split at the first
  // semicolon, else the first sentence end.
  var flat = String(title).trim();
  var cut = flat.indexOf(';');
  if (cut === -1){
    var sm = flat.match(/^[\s\S]*?[.!?](?=\s)/);
    cut = sm ? sm[0].length - 1 : -1;
  }
  var headTxt = cut > 20 ? flat.slice(0, cut).trim() : flat;
  var subTxt  = cut > 20 ? flat.slice(cut + 1).replace(/^[\s,;]+/, '').trim() : '';

  return '<div class="bs-card' + (kind ? ' bs-' + esc(kind) : '') + '">'
    + '<div class="bs-tag">' + tag + '</div>'
    + '<div class="bs-head">' + headTxt + '</div>'
    + (subTxt ? '<div class="bs-sub">' + subTxt + '</div>' : '')
    + (String(why).trim()
        ? '<details class="bs-dd"><summary><span class="bs-btn">' + BS_BTN + ' <span class="bs-chev">▼</span></span></summary>'
          + '<div class="bs-body">' + why + '</div></details>'
        : '')
    + '</div>';
}

function formatBlindSpots(html){
  var s = String(html);

  // Shape the agent already writes today: one banner at the top of Situations.
  // Treated as the general blind spot so this gets the gold drawer now rather
  // than waiting for the prompt to switch to the newer contract.
  // Depth-matched, not regex-matched: the banner holds three nested divs, so a
  // non-greedy close lands on bs-body's </div> and orphans the banner's own,
  // which then ends a parent card early.
  var bi = s.indexOf('<div class="bsx-top-banner">');
  if (bi !== -1){
    var be = endOfDiv(s, bi);
    if (be !== -1){
      var inner = s.slice(bi, be);
      var title = (inner.match(/<div class="bs-title">([\s\S]*?)<\/div>/i) || [])[1] || '';
      var body  = (inner.match(/<div class="bs-body">([\s\S]*?)<\/div>\s*<\/div>\s*$/i) || [])[1]
               || (inner.match(/<div class="bs-body">([\s\S]*?)<\/div>/i) || [])[1] || '';
      var card = bsCard('general', title, body);
      if (card) s = s.slice(0, bi) + card + s.slice(be);
    }
  }

  // Newer contract, one card per blind spot, kind-tagged.
  s = s.replace(/<div class="blindspot"([^>]*)>([\s\S]*?)<\/div>\s*<\/div>/gi,
    function(m, attrs, inner){
      var kind  = (String(attrs).match(/data-kind="([^"]*)"/i) || [null, ''])[1].toLowerCase();
      var title = (inner.match(/<div class="bs-title">([\s\S]*?)<\/div>/i) || [])[1] || '';
      var why   = (inner.match(/<div class="bs-why">([\s\S]*?)$/i) || [])[1] || '';
      return bsCard(kind, title, why) || m;
    });

  return s;
}

// ── NEVER RENDER AN EMPTY CARD ─────────────────────────────────
// A container whose contents got filtered away still draws its border, padding
// and background — a blank card with no explanation. Rather than chase each
// producer, sweep at the end: any card-shaped container holding no visible
// content and no graphic is removed. Runs last so it sees the final state.
// Containers only. Label elements are NOT listed here — a label is content in
// its own right, and sweeping one would delete real section headings.
var EMPTY_SWEEP = ['card','desk-block','sector-box','onx','watch','watch-grid','rf-pair',
  'pal','pa-lists','pac','wlc','wlc-rows','mo-card','bs-card','si-bubble','premortem',
  'xray','ledger','prod-tool','ai-pulse','reads-card','reads','empathy-grid','pmt-wrap',
  'week-card','jokes','sit','firmwatch','sflags','pt-preview','dbk-sub'];

// Elements that only ANNOUNCE content. A container holding nothing but these is
// a heading with nothing under it, which is exactly what the never-empty rule
// is about — so they are stripped before deciding whether anything is left.
var LABEL_ONLY = ['card-label','dbk-h','dbk-sub','onx-label','onx-sub','pt-label',
  'subsec','sd-banner','pal-h','pac-h','si-k','bs-tag','mvb-bar','pscore-bar','wk-h'];

function hasVisibleContent(block){
  var s = String(block);

  // Drop the announcing elements and any marker the engine left unfilled.
  LABEL_ONLY.forEach(function(cls){
    s = s.replace(new RegExp('<(div|span)[^>]*class="[^"]*\\b' + cls + '\\b[^"]*"[^>]*>[\\s\\S]*?<\\/\\1>', 'gi'), '');
  });
  s = s.replace(/<div class="[a-z-]*-here"[^>]*>\s*<\/div>/gi, '');

  // Anything that draws on its own still counts, even with no text.
  if (/<(?:svg|img|canvas|table|input|hr)\b/i.test(s)) return true;
  if (/<div class="[^"]*(?:-bar|-fill|-track|bar|fill)\b/i.test(s)) return true;

  var text = s.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  return text.length > 0;
}

function dropEmptyContainers(html){
  var s = String(html);
  var re = /<div class="([^"]*)"[^>]*>/gi;
  var i = 0, guard = 0;

  while (i < s.length && guard++ < 20000){
    re.lastIndex = i;
    var m = re.exec(s);
    if (!m) break;

    var cls = ' ' + m[1] + ' ';
    var isCard = EMPTY_SWEEP.some(function(c){ return cls.indexOf(' ' + c + ' ') !== -1; });
    if (!isCard){ i = m.index + m[0].length; continue; }

    var e = endOfDiv(s, m.index);
    if (e === -1){ i = m.index + m[0].length; continue; }

    var block = s.slice(m.index, e);
    if (hasVisibleContent(block)){ i = m.index + m[0].length; continue; }

    s = s.slice(0, m.index) + s.slice(e);   // drop it, re-check from here
    i = m.index;
  }

  // A Sector Detail banner with nothing under it is itself an empty card.
  // Matched as [^<]* — the banner holds no nested tags. A [\s\S]*? here plus a
  // negative lookahead backtracks until the lookahead passes, which swallowed
  // the entire sector box that the banner was supposed to be introducing.
  return s.replace(/<div class="sd-banner">[^<]*<\/div>\s*/gi, function(m, off, str){
    var after = str.slice(off + m.length, off + m.length + 48);
    return /^<div class="(?:si-bubble|sector-box)/.test(after) ? m : '';
  });
}

// ── SECTOR INSIGHT BUBBLES ─────────────────────────────────────
// Contract: <div class="sector-insight"> one or two sentences </div>
// The agent may write several; they are collected and rendered as bubbles
// directly above the sector rows, because they are the read ON those rows.
// Left alone they render as bare unstyled prose wherever the agent put them.
// data-sector is optional and becomes a small caption when present.
function siBubble(sector, body){
  var txt = String(body).trim();
  if (!txt) return '';
  return '<div class="si-bubble">'
    + (sector ? '<div class="si-k">' + esc(sector) + '</div>' : '')
    + '<div class="si-b">' + txt + '</div>'
    + '</div>';
}

// Pull every sector-insight out of a region and return {region, html}.
function cutSectorInsights(region){
  var bubbles = [], out = String(region), guard = 0;
  var re = /<div class="sector-insight"([^>]*)>/i, m;
  for (;;){
    m = re.exec(out);
    if (!m || guard++ > 24) break;
    var e = endOfDiv(out, m.index);
    var inner, cutEnd;
    if (e === -1){                       // unbalanced: take to the next close
      var close = out.indexOf('</div>', m.index);
      if (close === -1) break;
      inner = out.slice(m.index + m[0].length, close);
      cutEnd = close + 6;
    } else {
      inner = out.slice(m.index + m[0].length, e - 6);
      cutEnd = e;
    }
    var sector = (String(m[1]).match(/data-sector="([^"]*)"/i) || [null, ''])[1];
    bubbles.push(siBubble(sector, inner));
    out = out.slice(0, m.index) + out.slice(cutEnd);
  }
  return { region: out, html: bubbles.join('') };
}

// Factors that escaped their card. On a two-mandate brief one X-Ray block loses
// its wrapper upstream, so its factor rows end up sitting loose in the section,
// after the sector card and before the box — visibly outside the panel they
// belong to. Gather every stray one back inside.
function consolidateFactors(html){
  var s = String(html);
  var xi = s.indexOf('<div class="xray">');
  if (xi === -1) return s;
  var xe = endOfDiv(s, xi);
  if (xe === -1) return s;

  var orphans = [], out = '', pos = 0, guard = 0;
  var re = /<div class="factor">/gi, m;
  while ((m = re.exec(s)) !== null && guard++ < 32){
    var e = endOfDiv(s, m.index);
    if (e === -1) break;
    if (m.index > xi && m.index < xe){ re.lastIndex = e; continue; }   // already home
    orphans.push(s.slice(m.index, e));
    out += s.slice(pos, m.index);
    pos = e;
    re.lastIndex = e;
  }
  if (!orphans.length) return s;

  s = out + s.slice(pos);
  xi = s.indexOf('<div class="xray">');
  xe = xi === -1 ? -1 : endOfDiv(s, xi);
  if (xi === -1 || xe === -1) return s;
  return s.slice(0, xe - 6) + orphans.join('') + s.slice(xe - 6);
}

// ── FACTOR X-RAY: keep the bullets, drop the prose ─────────────
// The factor notes and the blunt-read warning were an unformatted grey wall
// under the bars. The factor name and its weight ARE the bullet; the reasoning
// belongs in the premortem, which already runs through the same chain.
function compactXray(html){
  // Stripped globally, not per X-Ray block. On a two-mandate brief one of the
  // two blocks loses its wrapper upstream, leaving its factors loose in the
  // section — scoping to <div class="xray"> silently missed exactly those.
  // Both classes only ever appear inside this block, so a global strip is safe.
  // This pass no longer deletes anything. v19.1 stripped every factor-note
  // and every xray-warn globally, which erased the blunt read (the thesis
  // verdict the system prompt calls the single most important fact about how
  // this book behaves) plus all six factor rationales, on every brief it ever
  // shipped. The prose was a grey wall because it was UNSTYLED, not because it
  // was wrong, and the stylesheet already carries real treatments for both
  // classes. The thinking stays on the page.
  // The blunt read is removed at the reader's instruction. Factor notes stay:
  // only xray-warn is dropped, not the six factor rationales.
  return String(html).replace(/<div class="xray-warn">[\s\S]*?<\/div>\s*/gi, '');
}

// ── PREMORTEM ──────────────────────────────────────────────────
// The one-sentence claim stays visible and becomes the headline: gold and
// underlined, so it reads as the point rather than as an intro to two dense
// paragraphs. Everything after it — the mechanism, the trigger, the chain —
// moves behind a gold "How this matters to your portfolio" drawer.
function formatPremortemDrawer(html){
  var s = String(html);
  var i = s.indexOf('<div class="premortem">');
  if (i === -1) return s;
  var end = endOfDiv(s, i);
  if (end === -1) return s;

  var block = s.slice(i, end);
  var inner = block.replace(/^<div class="premortem">/, '').replace(/<\/div>$/, '');

  // Split at the end of the title: label + title stay out, the rest goes in.
  var tm = inner.match(/<div class="pm-title">[\s\S]*?<\/div>/i);
  if (!tm) return s;
  var cut = inner.indexOf(tm[0]) + tm[0].length;
  var head = inner.slice(0, cut), rest = inner.slice(cut).trim();
  if (!rest) return s;

  // One click shows everything. Any nested drawer inside (the step-by-step
  // chain) is flattened to its contents — a drawer inside a drawer means the
  // reader opens twice to reach the part that explains the risk.
  rest = rest.replace(/<(details|x-dd)[^>]*class="[^"]*risk-expand[^"]*"[^>]*>/gi, '<div class="risk-open">')
             .replace(/<\/(?:details|x-dd)>/gi, '</div>')
             .replace(/<(summary|x-sum)[^>]*>[\s\S]*?<\/\1>/gi, '');

  var rebuilt = '<div class="premortem pm-flat">' + head
    + '<details class="pmw">'
    +   '<summary><span class="pmw-btn">How this matters to your portfolio <span class="pmw-chev">▼</span></span></summary>'
    +   '<div class="pmw-body">' + rest + '</div>'
    + '</details>'
    + '</div>';
  return s.slice(0, i) + rebuilt + s.slice(end);
}

// ── PEOPLE WATCH ───────────────────────────────────────────────
// The lead person keeps their full read. The next two get their claim promoted
// out of the drawer — the first sentence carries the point, so the reader gets
// it without opening anything — behind a gold "Read the full story" button.
// Everyone after that keeps the compact box they already have.
// People Watch has two tiers already: person-open blocks (the ones that matter)
// and small pm-row bubbles (everyone else). The LEAD person keeps their full
// read. Persons 2 and 3 keep their name and bold claim visible and move the
// prose behind a gold "Read the full story" button. The pm-row bubbles are left
// exactly as they are — they are already the compact form.
function promotePerson(block){
  var inner = block.replace(/^<div class="person-open">/i, '').replace(/<\/div>\s*$/, '');
  var head  = (inner.match(/<div class="po-head">[\s\S]*?<\/div>/i) || [])[0] || '';
  var claim = (inner.match(/<div class="po-claim">[\s\S]*?<\/div>/i) || [])[0] || '';
  if (!head && !claim) return block;
  var body = inner;
  if (head)  body = body.replace(head, '');
  if (claim) body = body.replace(claim, '');
  if (!body.replace(/\s|&nbsp;/g, '')) return block;      // nothing to tuck away
  return '<div class="person-open po-major">' + head + claim
    + '<details class="po-dd">'
    +   '<summary><span class="po-btn">Read the full story <span class="po-chev">▼</span></span></summary>'
    +   '<div class="po-body">' + body + '</div>'
    + '</details></div>';
}

function leadPerson(block){
  var b = String(block);
  var m = b.match(/<p class="po-read">([\s\S]*?)<\/p>/i);
  if (!m) return b;
  var text = m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  var sent = splitSentences(text);
  if (sent.length < 2) return b;                  // one sentence: leave it
  var lead = sent.slice(0, 2);
  var bullets = '<ul class="po-bullets">'
    + lead.map(function(x){ return '<li>' + x + '</li>'; }).join('')
    + '</ul>';
  var full = '<details class="po-dd"><summary>'
    + '<span class="po-btn">The full read <span class="po-chev">\u25bc</span></span>'
    + '</summary><div class="po-body">' + m[0] + '</div></details>';
  return b.replace(m[0], function(){ return bullets + full; });
}
function formatPeopleWatch(html){
  var s = String(html), out = '', pos = 0, n = 0, guard = 0;
  var re = /<div class="person-open">/gi, m;
  while ((m = re.exec(s)) !== null && guard++ < 12){
    var e = endOfDiv(s, m.index);
    if (e === -1) break;
    n++;
    var block = s.slice(m.index, e);
    if (n === 1) block = leadPerson(block);
    else if (n === 2 || n === 3) block = promotePerson(block);
    out += s.slice(pos, m.index) + block;
    pos = e;
    re.lastIndex = e;
  }
  return out + s.slice(pos);
}

// ── CLIENT TYPES ───────────────────────────────────────────────
// The drawer under the three client questions. Retitled to say plainly what it
// is, and the "Pre-loaded:" peek dropped — the title now carries that meaning,
// and the line was describing the drawer rather than telling the reader
// anything. Located by the empathy grid it wraps, not by its wording, so a
// reworded header still finds it. Dormant when the agent emits no grid.
function formatClientTypes(html){
  var s = String(html);
  var g = s.indexOf('class="empathy-grid"');
  if (g === -1) return s;
  var open = Math.max(s.lastIndexOf('<x-dd', g), s.lastIndexOf('<details', g));
  if (open === -1) return s;

  var pre = s.slice(0, open), head = s.slice(open, g), tail = s.slice(g);

  // Mark the wrapper so it can be shaded differently from the client questions
  // above it. It answers a different kind of question and should not read as a
  // fourth item in that list.
  head = head.replace(/^(<(?:x-dd|details))([^>]*)>/i, function(m, tag, attrs){
    return /class="/i.test(attrs)
      ? tag + attrs.replace(/class="([^"]*)"/i, 'class="$1 ctypes"') + '>'
      : tag + attrs + ' class="ctypes">';
  });
  // Everything before the first letter is the icon. Do NOT use a single-char
  // class — the emoji is a surrogate pair and [^\w\s] captures half of it.
  var icon = ((head.match(/<div class="dd-top">\s*<b>\s*([\s\S]*?)(?=[A-Za-z])/i) || [])[1] || '').trim();

  head = head.replace(/<div class="dd-top">[\s\S]*?<\/div>/i,
    '<div class="dd-top"><b>' + (icon ? icon + ' ' : '')
    + 'What are your different client types thinking about today?</b></div>');
  head = head.replace(/<div class="dd-peek">[\s\S]*?<\/div>\s*/i, '');
  return pre + head + tail;
}

// Two client questions, not three — the two the agent ranked highest. Keeping
// the count down is the point: the section is a prompt for the phone, not a FAQ.
var CLIENT_QA_KEEP = 2;
function capClientQuestions(html){
  var kept = 0;
  return String(html).replace(/<(x-dd|details) class="dd qa"[\s\S]*?<\/\1>\s*/gi, function(m){
    kept++;
    return kept <= CLIENT_QA_KEEP ? m : '';
  });
}

// ── POSITION NEWS: THREE ITEMS, SPREAD ACROSS SENTIMENT ────────
// Keep the column at three: the best bullish item, the best bearish one, and
// one more — the most interesting thing left. Sentiment comes from the tag
// class the agent already writes (on-tag pos / neg / neu), so nothing here
// reads prose. Original order is preserved, so "best" means the one the agent
// ranked first. A column with three or fewer items is left untouched.
var NEWS_KEEP = 4;                       // plus one sector item, see inlineSectorNews

// Walk forward from an opening <div ...> and return the index just past its
// matching </div>. A non-greedy regex cannot do this: the block is full of
// nested divs and would close on the first one.
function endOfDiv(s, start){
  var i = s.indexOf('>', start);
  if (i === -1) return -1;
  var depth = 1;
  i++;
  while (i < s.length && depth > 0){
    if (s.startsWith('<div', i)) { depth++; i += 4; }
    else if (s.startsWith('</div>', i)) { depth--; i += 6; }
    else i++;
  }
  return depth === 0 ? i : -1;
}

function capPositionNews(html){
  var s = String(html), out = '', pos = 0;
  var re = /<div class="onx">/gi, m;
  while ((m = re.exec(s)) !== null){
    var end = endOfDiv(s, m.index);
    if (end === -1) continue;
    var block = s.slice(m.index, end);
    var replaced = capOneNewsBlock(block);
    out += s.slice(pos, m.index) + replaced;
    pos = end;
    re.lastIndex = end;
  }
  return out + s.slice(pos);
}

function capOneNewsBlock(block){
  return (function(inner){
      // Split the block into its leading labels and the item list.
      var firstItem = inner.search(/<details class="on-dd">/i);
      if (firstItem === -1) return inner;
      var head = inner.slice(0, firstItem);
      var rest = inner.slice(firstItem);

      var items = [], re = /<details class="on-dd">[\s\S]*?<\/details>/gi, im;
      while ((im = re.exec(rest)) !== null) items.push({ html: im[0], idx: items.length });
      var trailing = rest.replace(re, '');
      if (items.length <= NEWS_KEEP) return inner;

      items.forEach(function(it){
        var t = it.html.match(/<span class="on-tag ([a-z]+)"/i);
        it.tone = t ? t[1].toLowerCase() : 'neu';
      });
      function firstOf(tone){
        for (var i = 0; i < items.length; i++){
          if (!items[i].used && items[i].tone === tone){ items[i].used = true; return items[i]; }
        }
        return null;
      }
      var picked = [];
      var p = firstOf('pos'); if (p) picked.push(p);
      var n = firstOf('neg'); if (n) picked.push(n);
      // Fill the rest with whatever is left, in the agent's own order.
      for (var i = 0; i < items.length && picked.length < NEWS_KEEP; i++){
        if (!items[i].used){ items[i].used = true; picked.push(items[i]); }
      }
      picked.sort(function(a, b){ return a.idx - b.idx; });
      return head + picked.map(function(x){ return x.html; }).join('') + trailing;
  })(block);
}

// ── PLAYBOOK TAGS ──────────────────────────────────────────────
// Three fixed labels, chosen by the tag's CLASS rather than whatever prose the
// agent put inside it. Left alone, the same slot reads "Roth IRA" on a
// two-mandate brief and "Your position" on a single-book one, so the column
// never looks like the same column twice.
// The position-news column. The agent titles it "The Latest in <book>"; the
// standing name is "Latest Position-Specific News". Whatever book qualifier the
// agent wrote is kept as a suffix so a two-mandate reader can still tell the
// two columns apart — on a single-book brief there is no qualifier to keep.
function renamePositionNews(html){
  return String(html).replace(/<div class="onx-label">([\s\S]*?)<\/div>/gi, function(m, inner){
    var txt = String(inner).replace(/<[^>]*>/g, '').trim();
    // Split on the phrase, keeping everything before it as the prefix. Do NOT
    // pick the icon out character by character — the bell is a surrogate pair
    // and [^\w\s] grabs half of it, which renders as a replacement glyph.
    var parts = txt.match(/^([\s\S]*?)the\s+latest\s+(?:in|on|for)\s+(.+)$/i);
    if (!parts) return m;                                  // not the pattern: leave alone
    var prefix = parts[1].trim(), book = parts[2].trim();
    return '<div class="onx-label">' + (prefix ? esc(prefix) + ' ' : '')
      + 'Latest Position-Specific News' + (book ? ' · ' + esc(book) : '') + '</div>';
  });
}

var PB_TAGS = {
  't-mkt':   'The Big Story',
  't-book':  'Your Position',
  't-niche': 'The Niche Read',
  't-cli':   'Tell Clients Today',
  't-ai':    'What\u2019s New in AI'
};
function normalizePlaybookTags(html){
  return String(html).replace(/<span class="pb-tag ([a-z-]+)"[^>]*>([\s\S]*?)<\/span>/gi,
    function(m, cls, inner){
      var label = PB_TAGS[cls];
      if (!label) return m;                    // unknown tag class: leave it alone
      return '<span class="pb-tag ' + cls + '">' + label + '</span>';
    });
}

// ── SIXTY-SECOND READ: TWO GROUPS, NOT FIVE ROWS ───────────────
// The first three items are a sequence: the story, what it did to this book,
// then the read underneath it. Numbering them says "read these in order".
// Items 4 and 5 are a different kind of thing (a client line, an AI note), so
// they keep a plain dot and sit below a rule rather than continuing the count.
function numberPlaybook(html){
  var s = String(html);
  if (s.indexOf('class="pb-item"') === -1) return s;
  var n = 0;
  return s.replace(/<div class="pb-item">\s*<span class="pb-dot">\s*<\/span>/gi, function(m){
    n++;
    if (n <= 3){
      return '<div class="pb-item pb-numbered">'
        + '<span class="pb-num">' + n + '</span>';
    }
    // First item past the sequence carries the divider.
    var cls = (n === 4) ? 'pb-item pb-break' : 'pb-item';
    return '<div class="' + cls + '"><span class="pb-dot"></span>';
  });
}
// ── "WHAT MOVED YOUR PORTFOLIO" IS A HEADING, NOT A BUTTON ─────
// It shipped as a centred pill with a gold border, which is the exact shape
// this brief uses for things you can press. Nothing happens when you press it.
// Matched by what follows it (the mv-list) rather than by its text, so the
// wording can change without silently losing the fix.
function fixMovedHeading(html){
  var s = String(html);
  var re = /<div class="subbar">\s*<span class="subbar-q">([\s\S]*?)<\/span>\s*<\/div>\s*(?=<div class="mv-list">)/i;
  var m = re.exec(s);
  if (!m) return s;
  // The list holds mv-item divs, so it needs balanced matching, not a regex.
  var listStart = m.index + m[0].length;
  var listEnd = endOfDiv(s, listStart);
  if (listEnd === -1){
    // Cannot wrap safely. Still kill the fake button, which is the actual bug.
    return s.slice(0, m.index) + '<div class="mv-head">' + m[1].trim() + '</div>' + s.slice(listStart);
  }
  var card = '<div class="mv-card">'
    + '<div class="mv-head">\uD83E\uDDED ' + m[1].trim() + '</div>'
    + s.slice(listStart, listEnd)
    + '</div>';
  return s.slice(0, m.index) + card + s.slice(listEnd);
}
// ── SECTION 01: ONE SEQUENCE, THEN THREE SEPARATE THINGS ───────
// The Sixty-Second Read card holds the numbered sequence and nothing else.
// "Why this matters to you" belongs to item 1, so it moves inside item 1 as a
// slim full-width bar rather than floating under the whole card as a loose
// drawer. The client line and the AI note are not part of the sequence, so
// they leave the navy card entirely and become their own light cards, each
// with its own header the way the sequence has one.
var DESK_CARDS = [
  { cls: 't-cli', title: 'Tell Clients Today', mod: 'micro-cli', ico: '',            quote: true  },
  { cls: 't-ai',  title: 'Quick AI Update',    mod: 'micro-ai',  ico: '\uD83E\uDD16', quote: false }
];
function splitDeskCards(html){
  var s = String(html);
  var pbStart = s.indexOf('<div class="pb">');
  if (pbStart === -1) return s;
  var pbEnd = endOfDiv(s, pbStart);
  if (pbEnd === -1) return s;
  var pb = s.slice(pbStart, pbEnd);
  var after = s.slice(pbEnd);

  // A pb-item holds spans only, so the first </div> closes it.
  var ITEM = /<div class="pb-item[^"]*">[\s\S]*?<\/div>/gi;
  var cards = '';
  DESK_CARDS.forEach(function(spec){
    var found = null;
    pb = pb.replace(ITEM, function(m){
      if (found) return m;
      if (m.indexOf('pb-tag ' + spec.cls) === -1) return m;
      found = m;
      return '';                                   // lift it out of the card
    });
    if (!found) return;
    var tx = (found.match(/<span class="pb-tx">([\s\S]*?)<\/span>/i) || [null,''])[1];
    if (!tx || !tx.trim()) return;
    cards += '<div class="micro ' + spec.mod + '">'
      + '<div class="micro-h">'
      +   (spec.ico ? '<span class="micro-ico">' + spec.ico + '</span>' : '')
      +   '<span class="micro-h-t">' + spec.title + '</span>'
      + '</div>'
      + (spec.quote
          ? '<blockquote class="micro-q">' + tx.trim() + '</blockquote>'
          : '<div class="micro-tx"><span class="micro-arrow">\u2192</span>' + tx.trim() + '</div>')
      + '</div>';
  });

  // The break rule was there to divide the two groups inside one card. They
  // are separate cards now, so it has nothing left to divide.
  pb = pb.replace(/<div class="pb-item pb-break"/g, '<div class="pb-item"');

  // Move the drawer inside item 1 and let it open on demand, not on arrival.
  var dd = null;
  after = after.replace(/<details class="dd s60"[^>]*>[\s\S]*?<\/details>\s*/i, function(m){
    dd = m.replace(/^<details class="dd s60"[^>]*>/i, '<details class="dd s60">');
    return '';
  });
  if (dd){
    var placed = false;
    pb = pb.replace(/(<div class="pb-item pb-numbered">[\s\S]*?)<\/div>/i, function(m, inner){
      if (placed) return m;
      placed = true;
      return inner + dd + '</div>';
    });
    if (!placed) after = dd + after;               // never drop the drawer
  }
  return s.slice(0, pbStart) + pb + cards + after;
}
// ── WATCH LIST: ONE CARD SHAPE ─────────────────────────────────
// Every card carries the same three facts, so none of them looks more
// important than another because it happened to have more data. YTD comes
// from watchlistPerf, which already ships a full window set per symbol.
function watchlistYtd(html){
  var wp = dv('watchlistPerf', null);
  if (!Array.isArray(wp) || !wp.length) return html;
  var byS = {};
  wp.forEach(function(r){
    if (!r) return;
    var sym = String(r.symbol || r.ticker || '').toUpperCase().trim();
    var y = r.perf ? num(r.perf.ytd) : num(r.ytd);
    if (sym && y !== null) byS[sym] = y;
  });
  return String(html).replace(
    /<span class="wi-tk">([^<]*)<\/span>([\s\S]{0,120}?)<span class="wi-mv"([^>]*)>([^<]*)<\/span>/gi,
    function(m, sym, mid, attrs, mv){
      var y = byS[String(sym).toUpperCase().trim()];
      var figs = '<span class="wi-fig"><span class="wi-fig-k">1D</span>'
        + '<span class="wi-mv"' + attrs + '>' + mv + '</span></span>';
      if (y !== undefined && y !== null){
        figs += '<span class="wi-fig"><span class="wi-fig-k">YTD</span>'
          + '<span class="wi-ytd-v ' + updn(y) + '">' + signedPct(y) + '</span></span>';
      }
      return '<span class="wi-tk">' + sym + '</span>' + mid
        + '<span class="wi-figs">' + figs + '</span>';
    });
}
// ── SECTOR NEWS, INLINE ────────────────────────────────────────
// sec-news blocks land below the whole sector block as unstyled prose, which
// puts a sector's explanation several rows away from the numbers it explains.
// Each one moves inside its own sector's drawer, directly under the
// sleeve/ETF/gap table, as a bubble. A block whose sector matches no row stays
// where it is rather than being dropped.
function inlineSectorNews(html){
  var s = String(html);
  if (s.indexOf('class="sec-news"') === -1) return s;

  // A block is only lifted once a home is proven to exist. Nothing is removed
  // speculatively, so a sector the book does not hold (Energy on a book with
  // no energy sleeve) keeps its block exactly where the agent put it.
  function homeFor(key){
    var found = false;
    String(s).replace(/<details class="svs-dd"[^>]*>[\s\S]*?<\/details>/gi, function(row){
      if (found) return row;
      var nm = (row.match(/<span class="svs-nm-t">([^<]*)<\/span>/i) || [null,''])[1];
      if (normSectorName(String(nm).trim()).toLowerCase() === key && row.indexOf('</table>') !== -1) found = true;
      return row;
    });
    return found;
  }

  var pending = [], homeless = [];
  s = s.replace(/<div class="sec-news"[^>]*data-sector="([^"]*)"[^>]*>([\s\S]*?)<\/div>\s*<\/div>\s*/gi,
    function(m, sector, inner){
      var key = normSectorName(String(sector).trim()).toLowerCase();
      var body = (inner.match(/<div class="sn-b">([\s\S]*?)$/i) || [null,''])[1];
      if (!homeFor(key)){
        var lbl = (inner.match(/<div class="sn-h">([\s\S]*?)<\/div>/i) || [null,''])[1] || sector;
        if (body && body.trim()){
          homeless.push({ label: String(lbl).replace(/<[^>]*>/g,'').trim(), body: body.trim() });
          return '';
        }
        return m;
      }
      if (!body || !body.trim()) return m;
      pending.push({ key: key, body: body.trim() });
      return '';
    });
  if (!pending.length) return s;

  // Anything that found no home is the sector of the day. It becomes the fifth
  // position-news item, styled like the others but marked as a sector.
  if (homeless.length && s.indexOf('<div class="onx">') !== -1){
    var extra = homeless.map(function(n){
      var lead = firstSentence(n.body);
      var what = lead && lead.indexOf('<') === -1
        ? '<b>' + lead + '</b>' + n.body.slice(lead.length)
        : n.body;
      return '<details class="on-dd on-sector"><summary>'
        + '<div class="on-tk">' + esc(n.label) + '</div>'
        + '<div class="on-what">' + what + '</div>'
        + '<span class="on-tag neu">Sector</span>'
        + '<span class="on-chev">\u25bc</span>'
        + '</summary><div class="on-body2">' + n.body + '</div></details>';
    }).join('');
    var at = endOfDiv(s, s.indexOf('<div class="onx">'));
    if (at !== -1) s = s.slice(0, at - 6) + extra + s.slice(at - 6);
  }

  pending.forEach(function(n){
    var placed = false;
    s = s.replace(/<details class="svs-dd"[^>]*>[\s\S]*?<\/details>/gi, function(row){
      if (placed) return row;
      var nm = (row.match(/<span class="svs-nm-t">([^<]*)<\/span>/i) || [null,''])[1];
      if (normSectorName(String(nm).trim()).toLowerCase() !== n.key) return row;
      // Under the sleeve / ETF / gap table, which is what the bubble explains.
      var at = row.indexOf('</table>');
      if (at === -1) return row;
      placed = true;
      return row.slice(0, at + 8) + '<div class="sn-bubble">' + n.body + '</div>' + row.slice(at + 8);
    });
  });
  return s;
}
// ── SPOTLIGHT STAT BUBBLES ─────────────────────────────────────
// Five compact facts, each carrying the same two windows: what it did today
// and what it has done year to date. Everything is computed, so nothing here
// can drift from the Performance Report. A bubble whose figures are missing is
// omitted rather than guessed at.
// ── THE LEAD SENTENCE OF EACH NUMBERED ITEM ────────────────────
// Bold only. The reasoning is not touched, reordered or split: the reader
// gets the topic at a glance and the argument underneath it unchanged.
// Sentence detection has to survive the prose this brief actually contains,
// which opens "The U.S. struck..." and carries "$1,300." and "2.42%" inline.
var LEAD_ABBR = /(?:^|\s)(?:[A-Z]|U\.S|U\.K|E\.U|D\.C|Inc|Corp|Co|Ltd|LLC|Dr|Mr|Mrs|Ms|St|Jr|Sr|vs|etc|No|approx|a\.m|p\.m|Sept|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Oct|Nov|Dec)\.$/;
function firstSentence(text){
  var t = String(text);
  for (var i = 0; i < t.length; i++){
    var ch = t.charAt(i);
    if (ch !== '.' && ch !== '!' && ch !== '?') continue;
    if (!/^\s[A-Z"'\u201c(]/.test(t.slice(i + 1, i + 3))) continue;
    if (ch === '.' && LEAD_ABBR.test(t.slice(0, i + 1))) continue;
    return t.slice(0, i + 1);
  }
  return '';                                   // one sentence: bold nothing
}
function boldPlaybookLead(html){
  return String(html).replace(
    /(<div class="pb-item pb-numbered">[\s\S]*?<span class="pb-tx">)([\s\S]*?)(<\/span>)/gi,
    function(m, open, body, close){
      if (/^\s*<b[\s>]/i.test(body)) return m;      // agent already led with bold
      var lead = firstSentence(body);
      if (!lead || lead.indexOf('<') !== -1) return m;
      return open + '<b class="pb-lead">' + lead + '</b>' + body.slice(lead.length) + close;
    });
}
function buildSpotStats(){
  var cells = [];

  function fig(lbl, v){
    if (v === null || v === undefined) return '';
    return '<div class="sstat-r"><span class="sstat-lb">' + lbl + '</span>'
      + '<span class="sstat-n ' + updn(v) + '">' + signedPct(v) + '</span></div>';
  }
  function cell(k, name, today, ytd, cls){
    if (today === null && ytd === null) return '';
    return '<div class="sstat' + (cls ? ' ' + cls : '') + '">'
      + '<div class="sstat-k">' + esc(k) + '</div>'
      + '<div class="sstat-v">' + name + '</div>'
      + fig('1D', today) + fig('YTD', ytd)
      + '</div>';
  }

  // 1. The book itself.
  var bm = parseBookMove();
  var h = dv('hypoBookReturn', null) || {};
  cells.push(cell('Your book', 'Blended', bm.v, num(h.ytd)));

  // 2 and 3. The names at the edges of the day.
  var hp = dv('holdingsPerf', null);
  if (Array.isArray(hp)){
    var names = hp.map(function(r){
      var sym = String(r && (r.symbol || r.ticker) || '').toUpperCase().trim();
      var mv = r && r.perf ? num(r.perf.today) : null;
      if (!sym || mv === null) return null;
      return { sym: sym, mv: mv, ytd: r.perf ? num(r.perf.ytd) : null };
    }).filter(Boolean).sort(function(a,b){ return b.mv - a.mv; });
    if (names.length){
      var top = names[0], bot = names[names.length - 1];
      if (top.mv > 0) cells.push(cell('Biggest gainer', esc(top.sym), top.mv, top.ytd));
      if (bot.mv < 0) cells.push(cell('Biggest loser', esc(bot.sym), bot.mv, bot.ytd));
    }
  }

  // 4 and 5. The sectors at the edges of the day.
  var sx = dv('sectorExposure', null);
  if (Array.isArray(sx)){
    var secs = sx.map(function(r){
      var nm = String(r && r.sector || '').trim(), mv = num(r && r.move);
      if (!nm || mv === null) return null;
      return { nm: nm, mv: mv, ytd: r.perf ? num(r.perf.ytd) : null };
    }).filter(Boolean).sort(function(a,b){ return b.mv - a.mv; });
    if (secs.length){
      var sTop = secs[0], sBot = secs[secs.length - 1];
      if (sTop.mv > 0) cells.push(cell('Top sector', esc(sTop.nm), sTop.mv, sTop.ytd, 'sstat-wide'));
      if (sBot.mv < 0) cells.push(cell('Weakest sector', esc(sBot.nm), sBot.mv, sBot.ytd, 'sstat-wide'));
    }
  }

  cells = cells.filter(Boolean);
  if (!cells.length) return '';
  return '<div class="sstats">' + cells.join('') + '</div>';
}
// ── BLIND SPOT: THE LOUDEST THING IN THE SECTION ───────────────
// One rename and one class. The expander says what it does ("Open Your Eyes")
// and the first card is marked so it can outrank the situations under it.
// Nothing is reordered and no card is dropped.
function formatBlindSpotCards(html){
  var s = String(html);
  s = s.replace(/(<span class="bs-btn">)[\s\S]*?(<span class="bs-chev">)/gi,
    function(m, open, chev){ return open + 'Open Your Eyes ' + chev; });

  // One blind spot, the first the agent wrote, which is the one it ranked
  // highest. Any additional card is dropped at the reader's instruction.
  var seen = 0, guard = 0;
  for (;;){
    var at = s.indexOf('<div class="bs-card', guard);
    if (at === -1) break;
    var end = endOfDiv(s, at);
    if (end === -1) break;
    seen++;
    if (seen === 1){
      s = s.slice(0, at) + s.slice(at).replace('<div class="bs-card', '<div class="bs-card bs-lead');
      guard = at + 30;
      continue;
    }
    s = s.slice(0, at) + s.slice(end);       // drop the extra card
    guard = at;
  }
  return s;
}

// Walk past a <details> to its matching close, so nested drawers do not end
// the block early the way a non-greedy regex would.
function endOfDetails(str, start){
  var i = str.indexOf('>', start);
  if (i === -1) return -1;
  var depth = 1;
  i++;
  while (i < str.length && depth > 0){
    if (str.startsWith('<details', i)) { depth++; i += 8; }
    else if (str.startsWith('</details>', i)) { depth--; i += 10; }
    else i++;
  }
  return depth === 0 ? i : -1;
}

// ── SITUATIONS: RANKED, NUMBERED, ONE BAR EACH ─────────────────
// Severity first (an escalating situation outranks everything), then the
// agent's own order, which already puts its lead first. Each card opens with a
// navy bar carrying its rank and its topic, and the explanation sits under it.
function formatSituationCards(html){
  var s = String(html);
  var blocks = [], i = 0, guard = 0;
  for (;;){
    var at = s.indexOf('<details class="dd sit', i);
    if (at === -1 || guard++ > 40) break;
    var end = endOfDetails(s, at);
    if (end === -1) break;
    blocks.push({ at: at, end: end, html: s.slice(at, end) });
    i = end;
  }
  if (!blocks.length) return s;

  function severity(b){
    if (/reader-tag tag-esc/i.test(b.html)) return 2;
    if (/class="dd sit lead/i.test(b.html)) return 1;
    return 0;
  }
  var order = blocks.map(function(b, idx){ return { idx: idx, sev: severity(b) }; })
    .sort(function(a, b){ return (b.sev - a.sev) || (a.idx - b.idx); });

  var rebuilt = order.map(function(o, rank){
    var b = blocks[o.idx];
    var one = b.html;
    one = one.replace(/<div class="dd-top">([\s\S]*?)<\/div>/i, function(m, inner){
      var tag   = (inner.match(/<span class="reader-tag[^"]*">[\s\S]*?<\/span>/i) || [''])[0];
      var topic = (inner.match(/<span class="sit-topic">([\s\S]*?)<\/span>/i) || [null, ''])[1];
      var rest  = inner
        .replace(/<span class="reader-tag[^"]*">[\s\S]*?<\/span>\s*/i, '')
        .replace(/<span class="sit-topic">[\s\S]*?<\/span>\s*/i, '')
        .trim();
      var title = String(topic).replace(/\s*:\s*$/, '').trim();
      return '<div class="sit-bar"><span class="sit-n">' + (rank + 1) + '</span>'
        + (title ? '<span class="sit-t">' + title + '</span>' : '')
        + (tag ? '<span class="sit-bar-tag">' + tag + '</span>' : '')
        + '</div><div class="dd-top">' + rest + '</div>';
    });
    return one;
  });

  // Back to front, so the offsets collected above stay valid.
  var out = s;
  for (var k = blocks.length - 1; k >= 0; k--){
    out = out.slice(0, blocks[k].at) + '@@SIT' + k + '@@' + out.slice(blocks[k].end);
  }
  for (var j = 0; j < blocks.length; j++){
    out = out.replace('@@SIT' + j + '@@', function(){ return ''; });
  }
  // Reinsert the whole ranked run where the first one started.
  return out.slice(0, blocks[0].at) + rebuilt.join('') + out.slice(blocks[0].at);
}

// ── WIDEST GAPS WEAR THEIR READ ON THE OUTSIDE ─────────────────
// A gap is the number a reader stops on, so the two biggest get the agent's
// explanation surfaced under the row instead of behind a chevron. The read is
// moved, not copied, and every other sector is untouched.
function surfaceGapReads(html){
  var s = String(html);
  var rows = s.match(/<details class="svs-dd"[^>]*>[\s\S]*?<\/details>/gi);
  if (!rows || !rows.length) return s;

  function gapBp(row){
    var m = row.match(/<span class="svs-k">Gap<\/span><span class="svs-v[^"]*">([^<]*)</i);
    if (!m) return null;
    var raw = String(m[1]).replace(/\u2212/g, '-').replace(/[+\s]/g, '');
    var v = parseFloat(raw);
    if (isNaN(v)) return null;
    return /bp/i.test(raw) ? Math.abs(v) : Math.abs(v) * 100;   // % to basis points
  }

  var ranked = rows.map(function(r, i){ return { i: i, row: r, bp: gapBp(r) }; })
    .filter(function(x){ return x.bp !== null && /svs-readout/.test(x.row); })
    .sort(function(a, b){ return b.bp - a.bp; })
    .slice(0, 2);
  if (!ranked.length) return s;

  ranked.forEach(function(x){
    var ri = x.row.indexOf('<div class="svs-readout">');
    if (ri === -1) return;
    var re2 = endOfDiv(x.row, ri);
    if (re2 === -1) return;
    var inner = x.row.slice(ri + 25, re2 - 6);

    // Drop the mandate wrapper and its chip. At sector level the reader does
    // not need to be told which book the position sits in.
    inner = inner.replace(/<span class="svs-mchip">[\s\S]*?<\/span>\s*/gi, '')
                 .replace(/<div class="svs-mread">/gi, '')
                 .replace(/<\/div>/gi, '');

    // One bullet, not the whole read. The full read stays in the drawer.
    var seg = inner.split('\u25b8').map(function(t){ return t.trim(); })
                   .filter(function(t){ return t.length > 0; });
    if (!seg.length) return;
    var one = seg[0];

    // Inside the summary so it sits in the same card as the row it explains
    // and stays visible when the drawer is shut.
    var withBubble = x.row.replace(/<\/summary>/i, function(){
      return '<div class="gap-read">' + one + '</div></summary>';
    });
    if (withBubble === x.row) return;
    s = s.replace(x.row, function(){ return withBubble; });
  });
  return s;
}
// ── SUBSECTOR BETS: TWO EXPLAINED, THE REST AS BARS ────────────
// Relevance is the tilt, not the size. A 50% index-beta sleeve is the biggest
// line and the least interesting thing on the page, so ranking runs on how
// hard the book is leaning (heavily overweight beats overweight beats
// neutral) with weight only as the tiebreaker. The top two keep their note;
// the rest render as name, weight and bar.
function compactFactors(html){
  var s = String(html);
  var out = [], i = 0, guard = 0;
  var found = [];
  for (;;){
    var at = s.indexOf('<div class="factor">', i);
    if (at === -1 || guard++ > 60) break;
    var end = endOfDiv(s, at);
    if (end === -1) break;
    found.push({ at: at, end: end, html: s.slice(at, end) });
    i = end;
  }
  if (found.length < 3) return s;               // nothing to compact

  function tilt(block){
    var load = (block.match(/factor-load">([^<]*)</i) || [null, ''])[1] || '';
    if (/heavily\s+(?:over|under)weight/i.test(load)) return 3;
    if (/(?:over|under)weight/i.test(load)) return 2;
    return 1;                                    // neutral, or unstated
  }
  function weight(block){
    var load = (block.match(/factor-load">([^<]*)</i) || [null, ''])[1] || '';
    var m = load.match(/(\d+(?:\.\d+)?)\s*%/);
    return m ? parseFloat(m[1]) : 0;
  }

  var ranked = found.map(function(f, idx){
    return { idx: idx, t: tilt(f.html), w: weight(f.html) };
  }).sort(function(a, b){ return (b.t - a.t) || (b.w - a.w); });

  var keep = {};
  ranked.slice(0, 2).forEach(function(r){ keep[r.idx] = 1; });

  // Rebuild back to front so earlier offsets stay valid.
  for (var k = found.length - 1; k >= 0; k--){
    if (keep[k]) continue;
    var f = found[k];
    var lean = f.html.replace(/<div class="factor-note">[\s\S]*?<\/div>\s*/i, '')
                     .replace('<div class="factor">', '<div class="factor factor-lean">');
    s = s.slice(0, f.at) + lean + s.slice(f.end);
  }
  return s;
}
// ── PRICE TARGETS: TWO LABELLED HALVES, ONE CARD ───────────────
// The moves and the consensus gaps already share a card; what was missing was
// any label saying which is which. pt-sub is deliberately not dbk-sub: that
// class sits in both EMPTY_SWEEP and LABEL_ONLY, so a label-only dbk-sub is
// always swept as empty.
function labelPriceTargets(html){
  var s = String(html);
  if (s.indexOf('<div class="pt-preview">') === -1) return s;
  s = s.replace(/<div class="pt-preview">/i, function(m){
    return '<div class="pt-sub">Newest target adjustments</div>' + m;
  });
  s = s.replace(/<div class="cg-wrap">/i, function(m){
    return '<div class="pt-sub pt-sub-2">Gaps to consensus</div>' + m;
  });
  return s;
}
// ── BIGGEST RISK: CAUSE, THEN RESULT ───────────────────────────
// The claim is already written as trigger-then-consequence in one sentence,
// which is a lot to hold in one line. Split at the clause boundary and show it
// as cause, arrow, result. No words are added, removed or reordered: the only
// edits are the connector itself and the capital letter that starts the second
// half. If no clean boundary exists, the sentence is left exactly as written.
function splitRiskClaim(html){
  return String(html).replace(/<div class="pm-title">([\s\S]*?)<\/div>/i, function(m, inner){
    var text = String(inner).trim();
    if (!text || text.indexOf('pm-cause') !== -1) return m;
    // Only split on a connector far enough in that both halves say something.
    var re = /,\s(and|so|which means|and then)\s/g, hit = null, x;
    while ((x = re.exec(text)) !== null){
      if (x.index >= 40 && (text.length - x.index) >= 40){ hit = x; break; }
    }
    if (!hit) return m;
    var cause = text.slice(0, hit.index).trim().replace(/[,;:]$/, '');
    var effect = text.slice(hit.index + hit[0].length).trim();
    if (!cause || !effect) return m;
    effect = effect.charAt(0).toUpperCase() + effect.slice(1);
    return '<div class="pm-title">'
      + '<div class="pm-cause">' + cause + '</div>'
      + '<div class="pm-arrow" aria-hidden="true">\u2193</div>'
      + '<div class="pm-effect">' + effect + '</div>'
      + '</div>';
  });
}
// ── SCENARIO HEADER: THREE EQUAL BUBBLES ───────────────────────
// The agent writes this grid with everything inline-styled, so the stylesheet
// could never reach it. Rebuilt into three same-size bubbles the sheet owns:
// probability, then the index and the book side by side, both labelled with
// the window they describe. The agent's own probability note is kept verbatim
// underneath, because it is the reasoning behind the number, and a short
// standing disclosure sits under that.
var SCEN_LABELS = {
  'what would trigger it': 'Trigger',
  'how to hedge': 'If concerned, how to hedge or reduce exposure'
};
function formatScenarioBubbles(html){
  var s = String(html);

  var guard = 0;
  for (;;){
    var at = s.indexOf('<div class="prob-grid">');
    if (at === -1 || guard++ > 12) break;
    var end = endOfDiv(s, at);
    if (end === -1) break;
    var inner = s.slice(at, end);

    function grab(label){
      var re = new RegExp(label + '\\s*<\\/div>\\s*<div[^>]*>([^<]*)<', 'i');
      var m = inner.match(re);
      return m ? m[1].trim() : '';
    }
    var prob = grab('Probability');
    var spx  = grab('S and P 500') || grab('S&amp;P 500');
    var you  = grab('Your book');
    var note = (inner.match(/font-style:italic[^>]*>([\s\S]*?)<\/div>/i) || [null,''])[1].trim();

    if (!prob && !spx && !you){
      // Nothing recognisable: leave the agent's block exactly as written.
      s = s.slice(0, at) + inner.replace('prob-grid', 'prob-grid pbub-raw') + s.slice(end);
      continue;
    }
    function bub(k, v, cls){
      if (!v) return '';
      return '<div class="pbub' + (cls ? ' ' + cls : '') + '">'
        + '<div class="pbub-k">' + esc(k) + '</div>'
        + '<div class="pbub-v ' + (/^\s*[-\u2212]/.test(v) ? 'dn' : '') + '">' + esc(v) + '</div>'
        + '</div>';
    }
    var built = '<div class="pbubs">'
      + bub('Probability', prob)
      + bub('S&P 500 if realized', spx)
      + bub('Your book if realized', you, 'pbub-you')
      + '</div>'
      + (note ? '<div class="pbub-note">' + note + '</div>' : '')
      + '<div class="pbub-disc">Scenario estimate, not a forecast. Probability and impact are'
      + ' judgment from the reasoning shown, not a modelled output, and not investment advice.</div>';
    s = s.slice(0, at) + built + s.slice(end);
  }

  // Row labels: say the thing, not a question about the thing.
  s = s.replace(/<div class="scen-fact-k">([^<]*)<\/div>/gi, function(m, k){
    var key = String(k).trim().toLowerCase();
    return SCEN_LABELS[key]
      ? '<div class="scen-fact-k">' + SCEN_LABELS[key] + '</div>'
      : m;
  });

  // "Why your book differs" is dropped at the reader's instruction.
  s = s.replace(/<div class="scen-fact">\s*<div class="scen-fact-k">Why your book differs<\/div>[\s\S]*?<\/div>\s*<\/div>\s*/gi, '');
  return s;
}
// ── WEEK AHEAD: ONE DRAWER ─────────────────────────────────────
// Only the starred event keeps its drop-down. Any other wk-dd is flattened to
// a plain row, with its body text kept as a line underneath, so nothing the
// agent wrote is lost. The duplicated prev/est viz is not carried over because
// wk-meta on the row already states both figures.
function oneWeekDrawer(html){
  return String(html).replace(/<details class="wk-dd">([\s\S]*?)<\/details>\s*/gi, function(m, inner){
    var row = (inner.match(/<div class="wk-row">[\s\S]*?<\/div>\s*<\/div>/i) || [null, ''])[0];
    if (!row) return m;                          // cannot flatten safely
    var body = (inner.match(/<div class="wk-more">([\s\S]*?)<\/div>\s*$/i) || [null, ''])[1] || '';
    var para = (body.match(/<p>([\s\S]*?)<\/p>/i) || [null, ''])[1] || '';
    return '<div class="wk-flat">' + row
      + (para ? '<div class="wk-extra">' + para + '</div>' : '')
      + '</div>';
  });
}
// ── EARNINGS ON DECK: BOXES, THEN DRIVERS ──────────────────────
// The estimate figures become a row of boxes under the ticker, and the prose
// becomes a lead driver plus bullets of what to watch. The expected-move box
// renders ONLY if the payload carries the figure. There is no implied
// volatility anywhere in this payload, so it is absent rather than invented:
// a made-up expected move is a number a reader would trade against.
// See SYSTEM_PROMPT_TODO.md.
function expectedMoveFor(sym){
  var rows = dv('earningsThisWeek', null);
  if (!Array.isArray(rows)) return null;
  var want = String(sym || '').toUpperCase().trim();
  for (var i = 0; i < rows.length; i++){
    var r = rows[i];
    if (!r) continue;
    if (String(r.symbol || r.ticker || '').toUpperCase().trim() !== want) continue;
    var v = num(r.expectedMovePct);
    if (v === null) v = num(r.impliedMovePct);
    if (v === null) v = num(r.expectedMove);
    return v;
  }
  return null;
}
function formatEarningsOnDeck(html){
  // Deliberately CONTAINED. An earlier version moved the estimate block out of
  // its column and rewrote row boundaries; the div count still balanced but the
  // nesting shifted and the whole card rendered one character per line inside
  // the narrow date column. This version only ever replaces the INNER html of
  // two leaf containers and never touches a wrapper or a row boundary.
  var s = String(html);

  // 1. Estimate figures become boxes, inside the container they already live in.
  var cur = 0, guard = 0;
  for (;;){
    var at = s.indexOf('<div class="earn-nums">', cur);
    if (at === -1 || guard++ > 20) break;
    var end = endOfDiv(s, at);
    if (end === -1) break;
    var open = '<div class="earn-nums">';
    var inner = s.slice(at + open.length, end - 6);
    if (inner.indexOf('ebox') !== -1){ cur = end; continue; }   // already done

    var boxes = [], pair = /<div class="k"[^>]*>([\s\S]*?)<\/div>\s*<div class="est">([\s\S]*?)<\/div>/gi, pm;
    while ((pm = pair.exec(inner)) !== null){
      boxes.push({ k: pm[1].replace(/<[^>]*>/g,'').trim(), v: pm[2].replace(/<[^>]*>/g,'').trim() });
    }
    if (!boxes.length){ cur = end; continue; }

    // Expected move only if the payload actually carries it.
    var before = s.slice(0, at);
    var sym = (before.match(/<div class="earn-tk">\s*([A-Z.]{1,6})[^]*$/i) || [null,''])[1] || '';
    var em = expectedMoveFor(sym);
    if (em !== null) boxes.push({ k: 'Expected move', v: '\u00b1' + Math.abs(em).toFixed(1) + '%' });

    var built = boxes.map(function(b){
      return '<div class="ebox"><div class="ebox-k">' + esc(b.k) + '</div>'
        + '<div class="ebox-v">' + esc(b.v) + '</div></div>';
    }).join('');
    s = s.slice(0, at + open.length) + built + s.slice(end - 6);
    cur = at + open.length + built.length;
  }

  // 2. Prose becomes a lead driver plus what to watch. earn-what is a leaf:
  //    it holds a <b> and text, no nested divs, so this is safe as a regex.
  s = s.replace(/<div class="earn-what">([\s\S]*?)<\/div>/gi, function(m, body){
    if (body.indexOf('earn-driver') !== -1) return m;
    var lead = (body.match(/<b>([\s\S]*?)<\/b>/i) || [null,''])[1];
    if (!lead) return m;
    var rest = body.replace(/<b>[\s\S]*?<\/b>\s*/i, '').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
    var watch = splitSentences(rest);
    return '<div class="earn-what">'
      + '<div class="earn-driver"><span class="earn-driver-k">Key driver</span>'
      + '<span class="earn-driver-b">' + lead + '</span></div>'
      + (watch.length
          ? '<div class="earn-watch-k">What to watch</div><ul class="earn-watch">'
            + watch.map(function(x){ return '<li>' + x + '</li>'; }).join('') + '</ul>'
          : '')
      + '</div>';
  });
  return s;
}
// ── WEEK AHEAD: EARNINGS FIRST, DATES WITH A MONTH ─────────────
// Earnings lead the section: they are the dated events tied to names this book
// actually holds. Both sub-headers get a real class instead of the agent's
// inline 9.5px gold, and each earnings row shows its month and day.
function formatWeekSections(html){
  var s = String(html);

  // Month and day on the earnings rows, from earningsThisWeek by symbol.
  var when = {};
  var rows = dv('earningsThisWeek', null);
  if (Array.isArray(rows)) rows.forEach(function(r){
    if (!r) return;
    var sym = String(r.symbol || r.ticker || '').toUpperCase().trim();
    var d = String(r.date || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (sym && d) when[sym] = parseInt(d[2], 10) + '/' + parseInt(d[3], 10);
  });
  var cur = 0, guard = 0;
  for (;;){
    var at = s.indexOf('<div class="earn-row', cur);
    if (at === -1 || guard++ > 20) break;
    var tk = (s.slice(at, at + 1400).match(/<div class="earn-tk">\s*([A-Z.]{1,6})/i) || [null,''])[1];
    var md = tk ? when[String(tk).toUpperCase()] : null;
    if (md){
      var seg = s.slice(at, at + 400);
      var next = seg.replace(/<div class="day">([^<]*)<\/div>/i, function(m, d){
        if (/\//.test(d)) return m;                       // already dated
        return '<div class="day">' + d + '</div><div class="edate">' + md + '</div>';
      });
      s = s.slice(0, at) + next + s.slice(at + 400);
    }
    cur = at + 20;
  }

  // Both sub-headers get a class the stylesheet can reach.
