}
// ── CLIENT QUESTIONS WEAR A QUESTION MARK ──────────────────────
// The week-ahead rows lead with a date square because the thing that follows
// is an event. These lead with a question mark for the same reason: the reader
// should know a question is coming before they read the words.
function markClientQuestions(html){
  return String(html).replace(/<div class="qa-q">([\s\S]*?)<\/div>/gi, function(m, inner){
    if (inner.indexOf('qa-mark') !== -1) return m;
    return '<div class="qa-q"><span class="qa-mark" aria-hidden="true">?</span>'
      + '<span class="qa-t">' + inner + '</span></div>';
  });
}
function reorderSections(html){
  var order = ORDER[MODE] || ORDER.hybrid;
  var re = /<div class="sec-num" id="(\w+)">\s*\d+\s*<\/div>/gi;
  var idxs = [], m;
  while ((m = re.exec(html)) !== null){ idxs.push({ id:m[1], start:m.index, tagLen:m[0].length }); }
  if (!idxs.length) return html;
  var head = html.slice(0, idxs[0].start);
  var chunks = {};
  for (var i=0;i<idxs.length;i++){
    var end = (i+1<idxs.length) ? idxs[i+1].start : html.length;
    var body = html.slice(idxs[i].start + idxs[i].tagLen, end);
    chunks[idxs[i].id] = body;
  }
  var out = head, n = 1;
  order.forEach(function(id){
    if (chunks[id] === undefined) return;
    var nn = (n<10?'0':'') + n;
    var body = chunks[id];
    var title = SEC_TITLES[id] || '';
    body = body.replace(/<div class="sec-title">([\s\S]*?)<\/div>/i, function(mm, t){
      if (t && t.trim()) title = t.trim();
      return '';
    });
    // The agent's own sec-title normally wins, which is right: it knows what it
    // wrote. FORCE_TITLES is the short list where the engine's name is the
    // decision, so an upstream prompt change cannot quietly rename the section.
    if (FORCE_TITLES[id]) title = FORCE_TITLES[id];
    var bar = '<div class="secbar" id="' + id + '">'
      + '<span class="secbar-num">' + nn + '</span>'
      + '<span class="secbar-title">' + esc(title).toUpperCase() + '</span>'
      + '</div>';
    out += bar + body;
    n++;
  });
  return out;
}
function fixScoreline(html){
  // Token substitution is global. The scoreline BOX stays retired, but if the
  // agent writes [[book]] or [[spx]] anywhere in prose, the verified figures
  // land there. Tokens are the one sanctioned way for the narrative to speak
  // the book's move, so leaving them unfilled outside one dead div was a trap.
  var bm = parseBookMove();
  var spx = num((dv('indexCloses',{})||{}).spxPct);
  if (bm.v===null && spx===null) return html;
  var bookStr = bm.v!==null ? signedPct(bm.v) : signedPct(0);
  var spxStr  = spx!==null ? signedPct(spx) : 'the index';
  return String(html)
    .replace(/\{\{\s*book\s*\}\}/g, bookStr).replace(/\[\[\s*book\s*\]\]/g, bookStr)
    .replace(/\{\{\s*spx\s*\}\}/g, spxStr).replace(/\[\[\s*spx\s*\]\]/g, spxStr);
}
function buildConsensus(){
  var raw = dv('priceTargetConsensus', null);
  if (!raw) return '';
  var cons = [];
  if (Array.isArray(raw)){
    cons = raw.slice();
  } else if (typeof raw === 'object'){
    Object.keys(raw).forEach(function(sym){
      var c = raw[sym]; if (c && typeof c === 'object'){ var cc = {}; for (var k in c) cc[k]=c[k]; cc.symbol = sym; cons.push(cc); }
    });
  }
  if (!cons.length) return '';
  var qmap = {};
  var qs = dv('quotes', null);
  if (Array.isArray(qs)) qs.forEach(function(q){
    var sym = String(q.symbol||'').toUpperCase(); if (!sym) return;
    var p = num(q.price!=null?q.price:(q.c!=null?q.c:null));
    if (p!==null) qmap[sym] = p;
  });
  var rows = [];
  var heldSet = {};
  var tk = dv('Ticker', null);
  function flatSyms(x){
    var out = [];
    if (Array.isArray(x)) x.forEach(function(el){
      if (Array.isArray(el)) el.forEach(function(s){ if (s) out.push(String(s).toUpperCase().trim()); });
      else if (el) out.push(String(el).toUpperCase().trim());
    });
    return out;
  }
  flatSyms(tk).forEach(function(t){ heldSet[t] = 1; });
  var hasHeldList = Object.keys(heldSet).length > 0;

  // The upstream rollup's stale exclusions are binding here too. v19.1 ignored
  // them and only filtered gap > 300, which is exactly how XNDU, STRC and QUBT
  // led the graphic on the same day the rollup said they were likely stale.
  // The prompt already binds the agent to those exclusions; the graphic now
  // obeys the same authority.
  var staleSet = {};
  (function(){
    var roll = String(dv('analystDeskSummary','') || '');
    if (!roll) return;
    // The rollup writes one line, e.g. "EXCLUDED as likely-stale consensus
    // data, DO NOT cite: XNDU (+258%), STRC (+160%), QUBT (+111%)". Parse the
    // remainder of THAT line only. No proximity guessing: a ticker on the line
    // above is fresh coverage, and flagging it stale hides a real holding.
    var re = /EXCLUDED[^\n:]{0,80}:\s*([^\n]+)/gi, m;
    while ((m = re.exec(roll)) !== null){
      var tre = /\b([A-Z]{1,5}(?:\.[A-Z])?)\b/g, t;
      while ((t = tre.exec(m[1])) !== null) staleSet[t[1]] = 1;
    }
  })();
  cons.forEach(function(c){
    var sym = String(c.symbol||c.ticker||'').toUpperCase(); if (!sym) return;
    if (hasHeldList && !heldSet[sym]) return;
    if (staleSet[sym]) return;
    var price = qmap[sym]!=null ? qmap[sym] : num(c.price);
    var hi = num(c.targetHigh!=null?c.targetHigh:c.high);
    var lo = num(c.targetLow!=null?c.targetLow:c.low);
    var avg = num(c.targetConsensus!=null?c.targetConsensus:(c.consensus!=null?c.consensus:(c.targetMedian!=null?c.targetMedian:c.median)));
    if (price===null || avg===null || hi===null || lo===null) return;
    if (avg<=0 || price<=0) return;
    // A range where low, average and high coincide is one analyst, not a
    // consensus. The prompt forbids quoting it as a gap; the graphic follows.
    if (hi === lo && lo === avg) return;
    var gap = (avg - price) / price * 100;
    if (gap > 300) return;
    rows.push({ sym:sym, price:price, hi:hi, lo:lo, avg:avg, gap:gap });
  });
  if (!rows.length) return '';
  rows.sort(function(a,b){ return b.gap - a.gap; });
  var mk = function(r, isTop){
    var dmin = Math.min(r.lo, r.price), dmax = Math.max(r.hi, r.price);
    var pad = (dmax - dmin) * 0.04 || 1;
    dmin -= pad; dmax += pad;
    var span = dmax - dmin || 1;
    function pos(v){ return Math.max(0, Math.min(100, (v - dmin)/span*100)); }
    var loP = pos(r.lo), hiP = pos(r.hi), pxP = pos(r.price), avP = pos(r.avg);
    var bandL = Math.min(loP,hiP), bandW = Math.abs(hiP-loP);
    var gapCls = r.gap>=0 ? 'up' : 'dn';
    var pill = (r.gap>=0?'+':'') + Math.round(r.gap) + '% to consensus';
    return '<div class="cg-row' + (isTop ? ' cg-top' : '') + '">'
      + '<div class="cg-tk">' + esc(r.sym) + '</div>'
      + '<div class="cg-track">'
      +   '<div class="cg-band" style="left:' + bandL.toFixed(1) + '%;width:' + bandW.toFixed(1) + '%"></div>'
      +   '<div class="cg-price" style="left:' + pxP.toFixed(1) + '%"><span class="cg-dot-px"></span></div>'
      +   '<div class="cg-avg" style="left:' + avP.toFixed(1) + '%"><span class="cg-dot-av"></span></div>'
      + '</div>'
      + '<div class="cg-gap ' + gapCls + '">' + pill + '</div>'
      + '<div class="cg-cap">low $' + r.lo.toFixed(2) + ' · now <b>$' + r.price.toFixed(2) + '</b> · avg $' + r.avg.toFixed(2) + ' · high $' + r.hi.toFixed(2) + '</div>'
      + '</div>';
  };
  var visible = rows.slice(0,3).map(function(r,i){ return mk(r, i===0); }).join('');
  var extra   = rows.slice(3).map(function(r){ return mk(r, false); }).join('');
  var more = extra
    ? '<details class="cg-more"><summary><span class="cg-more-t">More consensus gaps · full book</span><span class="cg-more-chev">▼</span></summary>' + extra + '</details>'
    : '';
  return '<div class="cg-wrap">' + visible + more + '</div>';
}
// ── RSI, RE-HOMED ──────────────────────────────────────────────
// The masthead tile had room for one overbought and one oversold name. The
// desk has room for all of them, each with its reading, which is the whole
// point of the measure: which names are stretched and which are washed out.
function rsiReadings(){
  function tri(a){
    if (!Array.isArray(a)) return [];
    return a.map(function(x){
      if (typeof x === 'string') return { t: String(x).trim(), r: null };
      var t = x.symbol || x.ticker || x.t || '';
      var r = (x.rsi!=null) ? x.rsi : (x.value!=null ? x.value : x.v);
      return { t: String(t).trim(), r: num(r) };
    }).filter(function(x){ return x.t; });
  }
  var ob = tri(dv('highest3', null)), os = tri(dv('lowest3', null));
  if (!ob.length && !os.length){
    // Fallback for payloads that predate highest3/lowest3: parse the summary
    // string, e.g. "Highest: ETH (77.9 OVERBOUGHT), IBIT (72.9) | Lowest: ...".
    var bar = String(dv('rsiBarSummary','') || '');
    if (bar){
      bar.split(/\s*\|\|?\s*|\s*;\s*/).forEach(function(seg){
        var isOb = /overbought|highest/i.test(seg), isOs = /oversold|lowest/i.test(seg);
        if (!isOb && !isOs) return;
        var names = seg.replace(/^[^:]*:\s*/, '');
        var list = names.split(/\s*[·,]\s*/).map(function(t){
          var mm = String(t).trim().match(/^([A-Za-z][A-Za-z.\-]{0,5})\s*\(?\s*(\d+(?:\.\d+)?)?/);
          return mm ? { t: mm[1].toUpperCase(), r: mm[2]!=null ? num(mm[2]) : null } : null;
        }).filter(Boolean);
        if (isOb && !ob.length) ob = list;
        else if (isOs && !os.length) os = list;
      });
    }
  }
  return { avg: num(dv('portfolioAvgRsi', null)), ob: ob, os: os };
}
function buildRsiDesk(){
  var r = rsiReadings();
  if (r.avg === null && !r.ob.length && !r.os.length) return '';
  function chips(list, cls){
    if (!list.length) return '<span class="rsi-none">None flagged this run.</span>';
    return list.map(function(x){
      return '<span class="rsi-chip ' + cls + '"><b>' + esc(x.t) + '</b>'
        + (x.r===null ? '' : '<span class="rsi-val">' + Number(x.r).toFixed(1) + '</span>')
        + '</span>';
    }).join('');
  }
  var lead = (r.avg===null) ? ''
    : '<div class="rsi-lead"><span class="rsi-lead-k">Book average</span>'
      + '<span class="rsi-lead-v">' + Number(r.avg).toFixed(1) + '</span>'
      + '<span class="rsi-lead-s">14-day RSI · below 30 is oversold, above 70 is overbought</span></div>';
  return '<div class="desk-block rsi-desk">'
    + '<span class="card-label dark-bar">📉 Momentum Check · Where Your Book Sits on RSI</span>'
    + lead
    // NOT dbk-sub. That class sits in both EMPTY_SWEEP and LABEL_ONLY, so
    // hasVisibleContent strips the block's own body before judging it and
    // dropEmptyContainers then deletes it as empty. rsi-sub mirrors the look
    // without walking into that trap.
    + '<div class="rsi-sub"><div class="rsi-h">Overbought</div>'
    +   '<div class="rsi-row">' + chips(r.ob, 'ob') + '</div></div>'
    + '<div class="rsi-sub"><div class="rsi-h">Oversold</div>'
    +   '<div class="rsi-row">' + chips(r.os, 'os') + '</div></div>'
    + '</div>';
}
function placeRsiDesk(html){
  var block = buildRsiDesk();
  if (!block) return html;
  var re = /(<div class="sec-num" id="analyst">\s*\d+\s*<\/div>\s*)/i;
  if (!re.test(html)) return html;                 // no Analyst Desk this run
  return String(html).replace(re, function(_, g1){ return g1 + block; });
}
function placeConsensus(html){
  var block = buildConsensus();
  var marker = /<div class="consensus-here">\s*<\/div>/i;
  if (marker.test(html)) return html.replace(marker, function(){ return block; })
    .replace(/<div class="consensus-here">\s*<\/div>/gi,'');
  return html;
}
function placeScenFlex(html){
