// v19.1 - THE FOCUS STRIP
// A ticker row in the masthead, sitting between the index tiles and the
// book-move row. Driven ENTIRELY by a [FOCUS] region in that advisor's
// Personalization cell. No region means no strip. Nothing here names any
// ticker; the sheet does.
//
//   [FOCUS]
//   LABEL: Client Employer Stock
//   TICKERS: INTC, NKE, LULU
//   [/FOCUS]
// ═══════════════════════════════════════════════════════════════
function readPersonalizationRaw(){
  var names = ['Read Personalization', 'Read personalization', 'Personalization'];
  for (var i = 0; i < names.length; i++){
    try {
      var rows = $(names[i]).all() || [];
      var txt = rows.map(function(r){
        var j = (r && r.json) ? r.json : {};
        return j.Personalization || j.personalization || j.PERSONALIZATION || '';
      }).filter(function(x){ return String(x).trim(); }).join('\n\n');
      if (txt && txt.trim()) return txt;
    } catch (e) { /* try the next node name */ }
  }
  return '';
}

function parseFocusRegion(){
  var raw = readPersonalizationRaw();
  if (!raw) return null;
  var blk = raw.match(/\[FOCUS\]([\s\S]*?)\[\/FOCUS\]/i);
  if (!blk) return null;
  var body = blk[1];
  var lab = body.match(/LABEL\s*:\s*(.+)/i);
  var tks = body.match(/TICKERS?\s*:\s*(.+)/i);
  if (!tks) return null;
  var list = tks[1].split(/[,;|]/)
    .map(function(x){ return x.trim().toUpperCase(); })
    .filter(function(x){ return /^[A-Z][A-Z.\-]{0,5}$/.test(x); })
    .slice(0, 6);
  if (!list.length) return null;
  return { label: lab ? lab[1].trim() : 'Client Focus', tickers: list };
}

function buildFocusStrip(){
  var cfg = null;
  try { cfg = parseFocusRegion(); } catch (e) { cfg = null; }
  if (!cfg) return '';

  var priceBy = {};
  var qs = dv('quotes', null);
  if (Array.isArray(qs)) qs.forEach(function(q){
    var s = String(q.symbol||'').toUpperCase();
    var p = num(q.price != null ? q.price : q.c);
    if (s && p !== null) priceBy[s] = p;
  });
  var wq = dv('watchlistQuotes', null);
  if (Array.isArray(wq)) wq.forEach(function(q){
    var s = String(q.symbol||'').toUpperCase();
    var p = num(q.price != null ? q.price : q.c);
    if (s && p !== null && priceBy[s] === undefined) priceBy[s] = p;
  });

  var perfBy = {};
  var wp = dv('watchlistPerf', null);
  if (Array.isArray(wp)) wp.forEach(function(r){
    var s = String(r.symbol||'').toUpperCase();
    if (s && r.perf) perfBy[s] = r.perf;
  });
  var hp = dv('holdingsPerf', null);
  if (Array.isArray(hp)) hp.forEach(function(r){
    var s = String(r.symbol||'').toUpperCase();
    if (s && r.perf && perfBy[s] === undefined) perfBy[s] = r.perf;
  });

  var profiles = dv('profiles.profilesByTicker', {}) || {};
  var cells = '', live = 0;

  cfg.tickers.forEach(function(tk){
    var p = perfBy[tk] || {};
    var today = num(p.today);
    var px = priceBy[tk];
    if (today === null && px === undefined) return;
    live++;

    var prof = profiles[tk] || {};
    var nm = String(prof.companyName || '')
      .replace(/,?\s*Inc\.?$/i,'').replace(/\s*Corp(oration)?\.?$/i,'')
      .replace(/\s*Company$/i,'').trim();

    var ctx = '', ctxK = '';
    [['ytd','YTD'],['y1','1Y'],['m3','3M'],['m1','1M']].some(function(w){
      var v = num(p[w[0]]);
      if (v === null) return false;
      ctx = signedPct(v); ctxK = w[1]; return true;
    });

    cells += '<div class="fs-cell">'
      + '<div class="fs-tk">' + esc(tk) + (nm ? '<span class="fs-nm">' + esc(nm) + '</span>' : '') + '</div>'
      + '<div class="fs-main">'
      +   (px !== undefined ? '<span class="fs-px">$' + Number(px).toFixed(2) + '</span>' : '')
      +   (today === null ? '' : '<span class="fs-mv ' + updn(today) + '">'
            + (today >= 0 ? '\u25B2 ' : '\u25BC ') + Math.abs(today).toFixed(2) + '%</span>')
      + '</div>'
      + (ctx ? '<div class="fs-ctx"><span class="fs-ctx-k">' + ctxK + '</span>'
            + '<span class="fs-ctx-v ' + (ctx.charAt(0) === '+' ? 'up' : 'dn') + '">' + ctx + '</span></div>' : '')
      + '</div>';
  });

  if (!live) return '';
  return '<div class="fstrip" data-n="' + live + '">'
    + '<div class="fs-lab"><span class="fs-dot"></span>' + esc(cfg.label) + '</div>'
    + '<div class="fs-row">' + cells + '</div>'
    + '</div>';
}

// v19.1 - format repairs for overlay-authored blocks
function tidyFocusBlocks(html){
  var s = String(html);

  // must-read kicker word cap, so a long one can never stack four lines of caps
  s = s.replace(/(<div class="rk">)([\s\S]*?)(<\/div>)/gi, function(m, open, body, close){
    var lead = (body.match(/^\s*(?:[^\w\s]\s*)*/) || [''])[0];
    var text = body.slice(lead.length).replace(/\s+/g, ' ').trim();
    var words = text.split(' ');
    if (words.length <= 9) return m;
    return open + lead + words.slice(0, 8).join(' ') + close;
  });

  // an overlay reads block gets the full-width card treatment
  s = s.replace(/<div class="reads-focus">\s*(<div class="reads">[\s\S]*?<\/div>)\s*<\/div>/gi,
    function(m, innerHtml){
      return '<div class="reads-card reads-focus"><div class="reads-bar">\u{1F4F0} Reads For These Clients</div>' + innerHtml + '</div>';
    });

  // kill the known filler peek in any of its ticker variants
  s = s.replace(/<div class="dd-peek">\s*The latest on [A-Za-z .&]+, what the stock is doing,? and what to tell your [A-Za-z .&]+ clients today\.?\s*<\/div>/gi, '');

  // a peek that is structurally identical to one above it is a template, not a line
  (function(){
    var seen = {};
    s = s.replace(/<div class="dd-peek">([\s\S]*?)<\/div>/gi, function(m, body){
      var key = body.replace(/<[^>]*>/g,'').replace(/\b[A-Z][a-z]+\b/g,'X').replace(/\s+/g,' ').trim().toLowerCase();
      if (key.length < 25) return m;
      if (seen[key]) return '';
      seen[key] = 1;
      return m;
    });
  })();

  return s;
}


