// \u2500\u2500 DASH SWEEP \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// v19.1 shipped a blunt pass here: every em/en dash became ", " regardless of
// context, so "2.5\u20132.6%" read as "2.5, 2.6%" and "AI-first\u2014and fast" lost its
// clause boundary. fixDashes (shared/helpers.js) is context-aware: spaced
// dashes become a comma, numeric ranges become "to", unspaced word boundaries
// become a comma, and only then does the catch-all run.
//
// Shield the Fed Funds range chip first \u2014 it is an intentional numeric range
// and must survive verbatim. Non-global match: the fed strip is the first and
// only "Fed Funds <strong>\u2026</strong>" occurrence.
// The sweep below is PROSE hygiene. It must never see the stylesheet: the
// comma cleanup rewrites ",." to "." and CSS is full of rgba(r,g,b,.07). The
// result is rgba(201,168,76.07), which modern CSS parses as a valid 3-argument
// rgb() \u2014 so every translucent colour in the sheet renders FULLY OPAQUE. That
// was silently true of every brief v19.1 has shipped (214 colours in the last
// production render, none intact). Shield the whole <style> block.
var _style = null;
html = html.replace(/<style>[\s\S]*?<\/style>/i, function (m) {
  _style = m; return '@@STYLEBLOCK@@';
});

// The style BLOCK is shielded above, but inline style attributes were not, and
// they contain rgba() too. The comma cleanup below rewrites ",." to "." for
// prose, which turns rgba(34,197,94,.2) into rgba(34,197,94.2) -- a value the
// browser drops, so the border silently never renders. Five of them were
// shipping on every brief. Same shield, same reason.
var _inline = [];
html = html.replace(/style=("[^"]*"|'[^']*')/gi, function (m) {
  _inline.push(m);
  return '@@INLINESTYLE' + (_inline.length - 1) + '@@';
});

var _fedRange = null;
html = html.replace(/(\ud83c\udfe6 Fed Funds <strong>)([\s\S]*?)(<\/strong>)/, function (m, pre, val, post) {
  _fedRange = val; return pre + '@@FEDRANGE@@' + post;
});
html = fixDashes(html);
if (_fedRange !== null) html = html.replace('@@FEDRANGE@@', function(){ return _fedRange; });
html = html.replace(/,\s*([.!?])/g, '$1');

_inline.forEach(function (v, i) {
  html = html.replace('@@INLINESTYLE' + i + '@@', function () { return v; });
});

// -- AMPERSAND SWEEP ------------------------------------------------------
// Hard rule: no ampersand entity survives into visible text. The engine's own
// templates author "S&amp;P 500" and "History &amp; Analysis", so the entity
// reaches the page even when the agent wrote none. One pass at the end covers
// every producer, present and future, instead of chasing each template.
//
// TEXT ONLY. The walker never enters a tag, so attribute values keep their
// escaping, and the stylesheet is still stubbed as @@STYLEBLOCK@@ at this
// point, so CSS is shielded for free.
//
// Repeated passes repair double escaping: "&amp;amp;" decodes to "&amp;" and
// then to "&". Replacing one entity at a time (never a run) keeps a literal
// "&&" written as "&amp;&amp;" from collapsing into a single ampersand.
function sweepAmpEntities(s){
  // A proper entity follows: this was double-escaped, so decoding restores
  // what the author meant.
  var ENTITY = /^(?:[a-zA-Z][a-zA-Z0-9]*|#[0-9]+|#[xX][0-9a-fA-F]+);/;
  // Named references an HTML5 parser still resolves WITHOUT a trailing
  // semicolon. A bare "&" in front of one of these would change the text, so
  // the escaped form stays put. Correctness outranks the health count.
  var LEGACY = /^(?:amp|lt|gt|quot|nbsp|copy|reg|times|divide|deg|pound|yen|cent|sect|para|middot|plusmn|laquo|raquo|not|shy|macr|uml|acute|micro|cedil|curren|brvbar|iexcl|iquest|szlig|eth|thorn|frac12|frac14|frac34|sup1|sup2|sup3|ordf|ordm)(?![a-zA-Z0-9])/;
  function pass(t){
    var out = '', i = 0, len = t.length, inTag = false;
    while (i < len){
      var c = t.charAt(i);
      if (c === '<'){ inTag = true; out += c; i++; continue; }
      if (c === '>'){ inTag = false; out += c; i++; continue; }
      if (!inTag && t.substr(i, 5) === '&amp;'){
        var tail = t.substr(i + 5, 12);
        out += (!ENTITY.test(tail) && LEGACY.test(tail)) ? '&amp;' : '&';
        i += 5;
        continue;
      }
      out += c; i++;
    }
    return out;
  }
  for (var n = 0; n < 4; n++){
    var next = pass(s);
    if (next === s) break;
    s = next;
  }
  return s;
}
html = sweepAmpEntities(html);

if (_style !== null) html = html.replace('@@STYLEBLOCK@@', function(){ return _style; });
html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>' + html + '</body></html>';
return [{ json: { html: html, subject: 'Market Pulse - ' + dStr } }];

const crypto = require('crypto');

// ---- R2 details ----
// ROTATE THESE. Both were exposed in plaintext. Move to n8n credentials
// or environment variables so they never sit in a node body again.
const ACCESS_KEY = 'REDACTED';
const SECRET_KEY = 'REDACTED';
const ACCOUNT_ID = 'REDACTED';
const BUCKET     = 'audio-briefs';
const REGION     = 'us-east-1';
const SERVICE    = 's3';
const PUBLIC_HOST = 'https://pub-517d2b1d766b490eb1587039102771ec.r2.dev';

// ─────────────────────────────────────────────────────────────
//  FILENAME — this is the fix.
//  Was: 'briefing-' + date + '.mp3'  → SAME KEY FOR EVERY CLIENT.
//  Every run overwrote the last one, so the newest upload served
//  every outstanding link. Now: advisor + timestamp + execution id.
// ─────────────────────────────────────────────────────────────
const slug = (s) => String(s || '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 40);

let advisorRaw = '';
try {
  advisorRaw = $('Read Config').all()
    .find(i => i.json.Field === 'advisor_name')?.json.Value || '';
} catch (e) { /* node name mismatch: falls through to the guard below */ }

const advisor = slug(advisorRaw);

// Hard stop rather than a silent collision. An empty advisor means the
// config read is broken, and shipping under a shared key is how the
// cross-client bug happened in the first place.
if (!advisor) {
  throw new Error('Cloudflare Audio Setup: advisor_name did not resolve from Read Config. Refusing to upload under a shared filename. Check the Read Config node name and the advisor_name row.');
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 16); // 2026-08-25T09-43
const execId = String($execution.id || 'noexec');
const fileName = `${advisor}/briefing-${stamp}-${execId}.mp3`;

// ---- presign the PUT (unchanged logic, new key) ----
const host = `${ACCOUNT_ID}.r2.cloudflarestorage.com`;
const encodedKey = fileName.split('/').map(encodeURIComponent).join('/');
const endpoint = `https://${host}/${BUCKET}/${encodedKey}`;

const now = new Date();
const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, '');   // YYYYMMDDTHHMMSSZ
const dateStamp = amzDate.slice(0, 8);                            // YYYYMMDD
const expires = 3600;
const credentialScope = `${dateStamp}/${REGION}/${SERVICE}/aws4_request`;
const signedHeaders = 'host';

const qs = {
  'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
  'X-Amz-Credential': `${ACCESS_KEY}/${credentialScope}`,
  'X-Amz-Date': amzDate,
  'X-Amz-Expires': String(expires),
  'X-Amz-SignedHeaders': signedHeaders,
};

const canonicalQs = Object.keys(qs).sort()
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(qs[k])}`).join('&');

const canonicalRequest = [
  'PUT',
  `/${BUCKET}/${encodedKey}`,
  canonicalQs,
  `host:${host}\n`,
  signedHeaders,
  'UNSIGNED-PAYLOAD',
].join('\n');

const hash = s => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const hmac = (key, s) => crypto.createHmac('sha256', key).update(s, 'utf8').digest();

const stringToSign = [
  'AWS4-HMAC-SHA256',
  amzDate,
  credentialScope,
  hash(canonicalRequest),
].join('\n');

const kDate    = hmac('AWS4' + SECRET_KEY, dateStamp);
const kRegion  = hmac(kDate, REGION);
const kService = hmac(kRegion, SERVICE);
const kSigning = hmac(kService, 'aws4_request');
const signature = crypto.createHmac('sha256', kSigning).update(stringToSign, 'utf8').digest('hex');

const presignedUrl = `${endpoint}?${canonicalQs}&X-Amz-Signature=${signature}`;

// pass the audio binary straight through for the PUT
const item = $input.first();

return [{
  json: {
    presignedUrl,
    fileName,
    advisor,
    publicUrl: `${PUBLIC_HOST}/${encodedKey}`,
  },
  binary: item.binary,
}];

